import type { DatabaseSync } from "node:sqlite";
import { INBOX_WEBHOOK_SECRET, OAUTH_BASE_HOST, PORT } from "../config/runtime.ts";
import { buildMessengerSourceWithTokenHint, buildMessengerTokenKey } from "./token-hint.ts";
import { decryptMessengerTokenForRuntime } from "./token-crypto.ts";

const MESSENGER_SETTINGS_KEY = "messengerChannels";
const TELEGRAM_RECEIVER_OFFSET_KEY = "telegramReceiverOffset";
const TELEGRAM_ACTIVE_DELAY_MS = 1_500;
const TELEGRAM_IDLE_DELAY_MS = 5_000;
const TELEGRAM_POLL_TIMEOUT_SECONDS = 20;
const TELEGRAM_CONFLICT_BACKOFF_MS = 90_000;

type PersistedSession = {
  targetId?: unknown;
  enabled?: unknown;
  token?: unknown;
};

type PersistedTelegramChannel = {
  token?: unknown;
  sessions?: unknown;
  receiveEnabled?: unknown;
};

type PersistedMessengerChannels = {
  telegram?: PersistedTelegramChannel;
};

type TelegramUpdateMessage = {
  message_id?: number;
  text?: string;
  caption?: string;
  chat?: {
    id?: number | string;
    title?: string;
  };
  from?: {
    id?: number;
    is_bot?: boolean;
    username?: string;
    first_name?: string;
    last_name?: string;
  };
};

type TelegramUpdate = {
  update_id?: number;
  message?: TelegramUpdateMessage;
  channel_post?: TelegramUpdateMessage;
};

type TelegramGetUpdatesResponse = {
  ok?: boolean;
  description?: string;
  result?: TelegramUpdate[];
};

type TelegramTokenRoute = {
  token: string;
  tokenKey: string;
  source: string;
  allowedChatIds: Set<string>;
};

type TelegramReceiverConfig = {
  receiveEnabled: boolean;
  hasToken: boolean;
  hasSession: boolean;
  routes: TelegramTokenRoute[];
  allowedChatCount: number;
};

export type TelegramReceiverStatus = {
  running: boolean;
  configured: boolean;
  receiveEnabled: boolean;
  enabled: boolean;
  allowedChatCount: number;
  nextOffset: number;
  lastPollAt: number | null;
  lastForwardAt: number | null;
  lastUpdateId: number | null;
  lastError: string | null;
};

export type StartTelegramReceiverOptions = {
  db: DatabaseSync;
  fetchImpl?: typeof fetch;
};

type ReceiverHandle = {
  stop: () => void;
  getStatus: () => TelegramReceiverStatus;
};

const initialStatus = (): TelegramReceiverStatus => ({
  running: false,
  configured: false,
  receiveEnabled: true,
  enabled: false,
  allowedChatCount: 0,
  nextOffset: 0,
  lastPollAt: null,
  lastForwardAt: null,
  lastUpdateId: null,
  lastError: null,
});

let receiverHandle: ReceiverHandle | null = null;
const runtimeOffsetByStatus = new WeakMap<TelegramReceiverStatus, Map<string, number>>();

function cloneStatus(status: TelegramReceiverStatus): TelegramReceiverStatus {
  return { ...status };
}

function normalizeText(value: unknown): string {
  return typeof value === "string" ? value.trim() : "";
}

function normalizeChatId(value: unknown): string {
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(Math.trunc(value));
  }
  return normalizeText(value);
}

function readMessengerChannels(db: DatabaseSync): PersistedMessengerChannels | null {
  try {
    const row = db.prepare("SELECT value FROM settings WHERE key = ?").get(MESSENGER_SETTINGS_KEY) as
      | { value?: unknown }
      | undefined;
    const raw = normalizeText(row?.value);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return null;
    return parsed as PersistedMessengerChannels;
  } catch {
    return null;
  }
}

function resolveTelegramConfig(db: DatabaseSync): TelegramReceiverConfig {
  let channelToken = "";
  let receiveEnabled = true;
  let hasSession = false;
  const tokenToChatIds = new Map<string, Set<string>>();

  const messengerChannels = readMessengerChannels(db);
  const telegram = messengerChannels?.telegram;
  if (!telegram || typeof telegram !== "object") {
    return {
      receiveEnabled,
      hasToken: false,
      hasSession: false,
      routes: [],
      allowedChatCount: 0,
    };
  }

  if (Object.prototype.hasOwnProperty.call(telegram, "token")) {
    channelToken = decryptMessengerTokenForRuntime("telegram", telegram.token);
  }

  if (typeof telegram.receiveEnabled === "boolean") {
    receiveEnabled = telegram.receiveEnabled;
  }

  if (Object.prototype.hasOwnProperty.call(telegram, "sessions") && Array.isArray(telegram.sessions)) {
    for (const rawSession of telegram.sessions) {
      const session = (rawSession ?? {}) as PersistedSession;
      if (session.enabled === false) continue;
      const chatId = normalizeChatId(session.targetId);
      if (!chatId) continue;
      hasSession = true;
      const sessionToken = decryptMessengerTokenForRuntime("telegram", session.token);
      const effectiveToken = sessionToken || channelToken;
      if (!effectiveToken) continue;
      const chats = tokenToChatIds.get(effectiveToken) ?? new Set<string>();
      chats.add(chatId);
      tokenToChatIds.set(effectiveToken, chats);
    }
  }

  const tokens = [...tokenToChatIds.keys()];
  const includeSourceHint = tokens.length > 1;
  const routes: TelegramTokenRoute[] = tokens.map((token) => {
    const tokenKey = buildMessengerTokenKey("telegram", token);
    return {
      token,
      tokenKey,
      source: includeSourceHint ? buildMessengerSourceWithTokenHint("telegram", tokenKey) : "telegram",
      allowedChatIds: tokenToChatIds.get(token) ?? new Set<string>(),
    };
  });

  const allowedChatCount = routes.reduce((acc, route) => acc + route.allowedChatIds.size, 0);
  return {
    receiveEnabled,
    hasToken: Boolean(channelToken) || tokens.length > 0,
    hasSession,
    routes,
    allowedChatCount,
  };
}

type TelegramReceiverOffsets = {
  legacy: number;
  byToken: Record<string, number>;
};

function normalizeOffset(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
    return Math.trunc(value);
  }
  if (typeof value === "string") {
    const numeric = Number(value.trim());
    if (Number.isFinite(numeric) && numeric >= 0) {
      return Math.trunc(numeric);
    }
  }
  return 0;
}

function readReceiverOffsets(db: DatabaseSync): TelegramReceiverOffsets {
  try {
    const row = db.prepare("SELECT value FROM settings WHERE key = ?").get(TELEGRAM_RECEIVER_OFFSET_KEY) as
      | { value?: unknown }
      | undefined;
    const raw = normalizeText(row?.value);
    if (!raw) return { legacy: 0, byToken: {} };

    let parsed: unknown;
    try {
      parsed = JSON.parse(raw) as unknown;
    } catch {
      parsed = raw;
    }

    if (typeof parsed === "number") {
      return { legacy: normalizeOffset(parsed), byToken: {} };
    }
    if (typeof parsed === "string") {
      return { legacy: normalizeOffset(parsed), byToken: {} };
    }
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return { legacy: 0, byToken: {} };
    }

    const record = parsed as Record<string, unknown>;
    const legacy = normalizeOffset(record.legacy);
    const byToken: Record<string, number> = {};
    const rawByToken = record.byToken;
    if (rawByToken && typeof rawByToken === "object" && !Array.isArray(rawByToken)) {
      for (const [key, value] of Object.entries(rawByToken as Record<string, unknown>)) {
        const normalized = normalizeOffset(value);
        if (normalized >= 0) {
          byToken[key] = normalized;
        }
      }
    }
    return { legacy, byToken };
  } catch {
    return { legacy: 0, byToken: {} };
  }
}

function writeReceiverOffsets(db: DatabaseSync, offsets: TelegramReceiverOffsets): void {
  const legacy = normalizeOffset(offsets.legacy);
  const byToken: Record<string, number> = {};
  for (const [key, value] of Object.entries(offsets.byToken)) {
    byToken[key] = normalizeOffset(value);
  }
  db.prepare(
    "INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
  ).run(TELEGRAM_RECEIVER_OFFSET_KEY, JSON.stringify({ legacy, byToken }));
}

function extractMessage(update: TelegramUpdate): TelegramUpdateMessage | null {
  if (update.message && typeof update.message === "object") return update.message;
  if (update.channel_post && typeof update.channel_post === "object") return update.channel_post;
  return null;
}

function buildAuthor(message: TelegramUpdateMessage): string {
  const from = message.from;
  if (!from || typeof from !== "object") {
    return "telegram";
  }
  const username = normalizeText(from.username);
  const firstName = normalizeText(from.first_name);
  const lastName = normalizeText(from.last_name);
  const display = [firstName, lastName].filter(Boolean).join(" ").trim() || username || String(from.id ?? "telegram");
  return username ? `${display}(@${username})` : display;
}

function isTelegramConflictError(message: string): boolean {
  const normalized = normalizeText(message).toLowerCase();
  if (!normalized) return false;
  return (
    normalized.includes("terminated by other getupdates request") ||
    normalized.includes("conflict") ||
    normalized.includes("409")
  );
}

async function forwardTelegramUpdate(params: {
  update: TelegramUpdate;
  source: string;
  allowedChatIds: Set<string>;
  fetchImpl: typeof fetch;
}): Promise<"forwarded" | "skipped"> {
  const { update, source, allowedChatIds, fetchImpl } = params;
  const message = extractMessage(update);
  if (!message) return "skipped";

  if (message.from?.is_bot) {
    return "skipped";
  }

  const chatId = normalizeChatId(message.chat?.id);
  if (!chatId || !allowedChatIds.has(chatId)) {
    return "skipped";
  }

  let text = normalizeText(message.text) || normalizeText(message.caption);
  if (!text) {
    return "skipped";
  }
  // Server returns 400 empty_content when directive body is only "$" or "$" + whitespace
  const raw = text.trimStart();
  if (raw.startsWith("$") && !raw.slice(1).trim()) {
    return "skipped";
  }

  const messageId =
    typeof message.message_id === "number" && Number.isFinite(message.message_id)
      ? String(Math.trunc(message.message_id))
      : String(update.update_id ?? `${Date.now()}`);
  const author = buildAuthor(message);
  const inboxRes = await fetchImpl(`http://${OAUTH_BASE_HOST}:${PORT}/api/inbox`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-inbox-secret": INBOX_WEBHOOK_SECRET,
    },
    body: JSON.stringify({
      source,
      message_id: messageId,
      author,
      chat: `telegram:${chatId}`,
      text,
    }),
  });

  if (!inboxRes.ok) {
    const detail = await inboxRes.text().catch(() => "");
    throw new Error(`inbox forward failed (${inboxRes.status})${detail ? `: ${detail}` : ""}`);
  }

  return "forwarded";
}

export async function pollTelegramReceiverOnce(options: {
  db: DatabaseSync;
  status: TelegramReceiverStatus;
  fetchImpl?: typeof fetch;
}): Promise<void> {
  const { db, status } = options;
  const fetchImpl = options.fetchImpl ?? fetch;
  const pollStartedAt = Date.now();
  status.lastPollAt = pollStartedAt;

  const config = resolveTelegramConfig(db);
  status.receiveEnabled = config.receiveEnabled;
  status.allowedChatCount = config.allowedChatCount;
  status.configured = config.routes.length > 0;
  status.enabled = false;

  if (!config.receiveEnabled) {
    status.lastError = null;
    return;
  }
  if (!config.hasToken) {
    status.lastError = "telegram token missing";
    return;
  }
  if (!config.hasSession || config.routes.length === 0) {
    status.lastError = "telegram sessions missing";
    return;
  }
  if (!INBOX_WEBHOOK_SECRET) {
    status.lastError = "INBOX_WEBHOOK_SECRET missing";
    return;
  }

  status.enabled = true;
  const persistedOffsets = readReceiverOffsets(db);
  const inMemoryOffsets = runtimeOffsetByStatus.get(status) ?? new Map<string, number>();
  runtimeOffsetByStatus.set(status, inMemoryOffsets);
  const hasPerTokenOffset = Object.keys(persistedOffsets.byToken).length > 0;
  let highestOffset = 0;
  let highestUpdateId: number | null = status.lastUpdateId;
  let forwardedAny = false;
  let offsetsChanged = false;

  for (const route of config.routes) {
    const persistedOffset = hasPerTokenOffset
      ? (persistedOffsets.byToken[route.tokenKey] ?? 0)
      : persistedOffsets.legacy;
    const inMemoryOffset = inMemoryOffsets.get(route.tokenKey) ?? 0;
    const nextOffset = Math.max(persistedOffset, inMemoryOffset);

    const telegramRes = await fetchImpl(`https://api.telegram.org/bot${route.token}/getUpdates`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        offset: nextOffset,
        timeout: TELEGRAM_POLL_TIMEOUT_SECONDS,
        allowed_updates: ["message", "channel_post"],
      }),
    });

    const payload = (await telegramRes.json().catch(() => null)) as TelegramGetUpdatesResponse | null;
    if (!telegramRes.ok || payload?.ok === false) {
      throw new Error(payload?.description || `telegram getUpdates failed (${telegramRes.status})`);
    }

    const updates = Array.isArray(payload?.result) ? payload.result : [];
    let maxUpdateId = nextOffset - 1;

    for (const update of updates) {
      const updateId =
        typeof update.update_id === "number" && Number.isFinite(update.update_id) ? Math.trunc(update.update_id) : null;
      if (updateId === null) continue;
      if (updateId < nextOffset) continue;

      const result = await forwardTelegramUpdate({
        update,
        source: route.source,
        allowedChatIds: route.allowedChatIds,
        fetchImpl,
      });
      if (result === "forwarded") {
        forwardedAny = true;
      }
      if (updateId > maxUpdateId) {
        maxUpdateId = updateId;
      }
      if (highestUpdateId === null || updateId > highestUpdateId) {
        highestUpdateId = updateId;
      }
    }

    let updatedOffset = nextOffset;
    if (maxUpdateId >= nextOffset) {
      updatedOffset = maxUpdateId + 1;
      offsetsChanged = true;
    }
    inMemoryOffsets.set(route.tokenKey, updatedOffset);
    persistedOffsets.byToken[route.tokenKey] = updatedOffset;
    if (updatedOffset > highestOffset) {
      highestOffset = updatedOffset;
    }
  }

  if (offsetsChanged) {
    persistedOffsets.legacy = highestOffset;
    writeReceiverOffsets(db, persistedOffsets);
  }
  status.nextOffset = highestOffset;
  status.lastUpdateId = highestUpdateId;

  if (forwardedAny) {
    status.lastForwardAt = Date.now();
  }
  status.lastError = null;
}

export function startTelegramReceiver(options: StartTelegramReceiverOptions): ReceiverHandle {
  if (receiverHandle) {
    return receiverHandle;
  }

  const { db } = options;
  const fetchImpl = options.fetchImpl ?? fetch;
  const status = initialStatus();
  status.running = true;

  let stopped = false;
  let busy = false;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let conflictPauseUntil = 0;
  let conflictWarnedInPause = false;

  const schedule = (delayMs: number) => {
    if (stopped) return;
    if (timer) clearTimeout(timer);
    timer = setTimeout(
      () => {
        void tick();
      },
      Math.max(250, delayMs),
    );
    timer.unref?.();
  };

  const tick = async () => {
    if (stopped || busy) return;
    const now = Date.now();
    if (conflictPauseUntil > 0 && now < conflictPauseUntil) {
      status.enabled = false;
      schedule(Math.min(TELEGRAM_IDLE_DELAY_MS, Math.max(500, conflictPauseUntil - now)));
      return;
    }
    if (conflictPauseUntil > 0 && now >= conflictPauseUntil) {
      conflictPauseUntil = 0;
      conflictWarnedInPause = false;
    }
    busy = true;
    try {
      await pollTelegramReceiverOnce({ db, status, fetchImpl });
      conflictWarnedInPause = false;
    } catch (err) {
      status.lastError = err instanceof Error ? err.message : String(err);
      if (isTelegramConflictError(status.lastError)) {
        conflictPauseUntil = Date.now() + TELEGRAM_CONFLICT_BACKOFF_MS;
        status.enabled = false;
        if (!conflictWarnedInPause) {
          console.warn(`[AgentDesk] telegram receiver paused: ${status.lastError}`);
          console.warn(
            `[AgentDesk] telegram receiver hint: another bot instance is polling this token. retry in ${Math.round(
              TELEGRAM_CONFLICT_BACKOFF_MS / 1000,
            )}s`,
          );
          conflictWarnedInPause = true;
        }
      } else {
        conflictWarnedInPause = false;
        console.warn(`[AgentDesk] telegram receiver error: ${status.lastError}`);
      }
    } finally {
      busy = false;
      schedule(status.enabled ? TELEGRAM_ACTIVE_DELAY_MS : TELEGRAM_IDLE_DELAY_MS);
    }
  };

  schedule(1_200);

  receiverHandle = {
    stop() {
      stopped = true;
      status.running = false;
      status.enabled = false;
      runtimeOffsetByStatus.delete(status);
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      receiverHandle = null;
    },
    getStatus() {
      return cloneStatus(status);
    },
  };

  return receiverHandle;
}

export function getTelegramReceiverStatus(): TelegramReceiverStatus {
  if (!receiverHandle) {
    return initialStatus();
  }
  return receiverHandle.getStatus();
}

import type { RuntimeContext } from "../../../types/runtime-context.ts";
import type { Lang } from "../../../types/lang.ts";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createCrossDeptSubtaskTools } from "./coordination/cross-dept-subtasks.ts";
import { createCrossDeptCooperationTools } from "./coordination/cross-dept-cooperation.ts";
import { createReportRoutingTools } from "./coordination/report-routing.ts";
import type { AgentRow, DelegationOptions } from "../shared/types.ts";

export function initializeCollabCoordination(ctx: RuntimeContext): any {
  const __ctx: RuntimeContext = ctx;
  const db = __ctx.db;
  const appendTaskLog = __ctx.appendTaskLog;
  const broadcast = __ctx.broadcast;
  const buildTaskExecutionPrompt = __ctx.buildTaskExecutionPrompt;
  const buildAvailableSkillsPromptBlock =
    __ctx.buildAvailableSkillsPromptBlock ||
    ((provider: string) => `[Available Skills][provider=${provider || "unknown"}][unavailable]`);
  const crossDeptNextCallbacks = __ctx.crossDeptNextCallbacks;
  const delegatedTaskToSubtask = __ctx.delegatedTaskToSubtask;
  const ensureTaskExecutionSession = __ctx.ensureTaskExecutionSession;
  const findBestSubordinate = __ctx.findBestSubordinate;
  const findTeamLeader = __ctx.findTeamLeader;
  const getAgentDisplayName = __ctx.getAgentDisplayName;
  const getDeptName = __ctx.getDeptName;
  const getDeptRoleConstraint = __ctx.getDeptRoleConstraint;
  const getProviderModelConfig = __ctx.getProviderModelConfig;
  const getRecentConversationContext = __ctx.getRecentConversationContext;
  const handleSubtaskDelegationComplete = __ctx.handleSubtaskDelegationComplete;
  const handleTaskRunComplete = __ctx.handleTaskRunComplete;
  const hasExplicitWarningFixRequest = __ctx.hasExplicitWarningFixRequest;
  const isTaskWorkflowInterrupted = __ctx.isTaskWorkflowInterrupted;
  const l = __ctx.l;
  const logsDir = __ctx.logsDir;
  const notifyCeo = __ctx.notifyCeo;
  const nowMs = __ctx.nowMs;
  const pickL = __ctx.pickL;
  const randomDelay = __ctx.randomDelay;
  const recordTaskCreationAudit = __ctx.recordTaskCreationAudit;
  const resolveLang = __ctx.resolveLang;
  const sendAgentMessage = __ctx.sendAgentMessage;
  const spawnCliAgent = __ctx.spawnCliAgent;
  const startProgressTimer = __ctx.startProgressTimer;
  const startTaskExecutionForAgent = __ctx.startTaskExecutionForAgent;

  const { linkCrossDeptTaskToParentSubtask, reconcileCrossDeptSubtasks } = createCrossDeptSubtaskTools({
    db,
    nowMs,
    broadcast,
    delegatedTaskToSubtask,
  });

  function normalizeTextField(value: unknown): string | null {
    if (typeof value !== "string") return null;
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : null;
  }

  /**
   * Detect project path from CEO message.
   * Recognizes:
   * 1. Absolute paths: /home/user/Projects/foo, ~/Projects/bar
   * 2. Project names: "agentdesk ?꾨줈?앺듃", "agentdesk-kanban?먯꽌"
   * 3. Known project directories under ~/Projects
   */
  function detectProjectPath(message: string): string | null {
    const homeDir = os.homedir();
    const projectsDir = path.join(homeDir, "Projects");
    const projectsDirLower = path.join(homeDir, "projects");
    const isDirectorySafe = (targetPath: string): boolean => {
      try {
        return fs.statSync(targetPath).isDirectory();
      } catch {
        return false;
      }
    };
    const readProjectNamesSafe = (projectDir: string): string[] => {
      try {
        return fs
          .readdirSync(projectDir, { withFileTypes: true })
          .filter((entry) => entry.isDirectory() && !entry.name.startsWith("."))
          .map((entry) => entry.name);
      } catch {
        return [];
      }
    };

    // 1a. Explicit absolute path in message (Unix)
    const absMatch = message.match(/(?:^|\s)(\/[\w./-]+)/);
    if (absMatch) {
      const p = absMatch[1];
      if (isDirectorySafe(p)) return p;
      const parent = path.dirname(p);
      if (isDirectorySafe(parent)) return parent;
    }

    // 1b. Explicit absolute path in message (Windows: C:\path\to\project)
    const winAbsMatch = message.match(/(?:^|\s)([A-Za-z]:[\\\/][\w.\\/ -]+)/);
    if (winAbsMatch) {
      const p = winAbsMatch[1].replace(/[\\/]+$/, ""); // trim trailing slashes
      if (isDirectorySafe(p)) return p;
      const parent = path.dirname(p);
      if (isDirectorySafe(parent)) return parent;
    }

    // 2. ~ path
    const tildeMatch = message.match(/~\/([\w./-]+)/);
    if (tildeMatch) {
      const expanded = path.join(homeDir, tildeMatch[1]);
      if (isDirectorySafe(expanded)) return expanded;
    }

    // 3. Scan known project directories and match by name
    const knownProjects = [projectsDir, projectsDirLower].flatMap((projectDir) => readProjectNamesSafe(projectDir));

    // Match project names in the message (case-insensitive)
    const msgLower = message.toLowerCase();
    for (const proj of knownProjects) {
      if (msgLower.includes(proj.toLowerCase())) {
        // Return the actual path
        const fullPath = path.join(projectsDir, proj);
        if (isDirectorySafe(fullPath)) return fullPath;
        const fullPathLower = path.join(projectsDirLower, proj);
        if (isDirectorySafe(fullPathLower)) return fullPathLower;
      }
    }

    return null;
  }

  /**
   * Resolve project path (canonical-first):
   * 1) task.project_id -> projects.project_path
   * 2) task.project_path
   * 3) detect from description/title
   * 4) latest known project path from DB
   * 5) process.cwd() (unless it's a packaged app dir)
   */
  function resolveProjectPath(task: {
    project_id?: string | null;
    project_path?: string | null;
    description?: string | null;
    title?: string;
  }): string {
    const projectId = String(task.project_id ?? "").trim();
    if (projectId) {
      const row = db
        .prepare(
          `
      SELECT project_path
      FROM projects
      WHERE id = ?
      LIMIT 1
    `,
        )
        .get(projectId) as { project_path: string | null } | undefined;
      const canonical = String(row?.project_path ?? "").trim();
      if (canonical) {
        const detectedCanonical = detectProjectPath(canonical);
        return detectedCanonical || canonical;
      }
    }

    const taskProjectPath = String(task.project_path ?? "").trim();
    if (taskProjectPath) {
      const detectedTaskPath = detectProjectPath(taskProjectPath);
      return detectedTaskPath || taskProjectPath;
    }

    const detected = detectProjectPath(task.description || "") || detectProjectPath(task.title || "");
    if (detected) return detected;

    // Try latest known project path from previous tasks
    const latestKnown = getLatestKnownProjectPath();
    if (latestKnown) return latestKnown;

    return process.cwd();
  }

  function getLatestKnownProjectPath(): string | null {
    const row = db
      .prepare(
        `
    SELECT project_path
    FROM tasks
    WHERE project_path IS NOT NULL AND TRIM(project_path) != ''
    ORDER BY updated_at DESC
    LIMIT 1
  `,
      )
      .get() as { project_path: string | null } | undefined;
    const candidate = normalizeTextField(row?.project_path ?? null);
    if (!candidate) return null;
    try {
      if (fs.statSync(candidate).isDirectory()) return candidate;
    } catch {
      // Ignore stale paths from historical task rows.
    }
    return null;
  }

  function getDefaultProjectRoot(): string {
    const homeDir = os.homedir();
    const candidates = [path.join(homeDir, "Projects"), path.join(homeDir, "projects"), process.cwd()];
    for (const candidate of candidates) {
      try {
        if (fs.statSync(candidate).isDirectory()) return candidate;
      } catch {
        // Ignore inaccessible or non-existent directories.
      }
    }
    return process.cwd();
  }

  function resolveDirectiveProjectPath(
    ceoMessage: string,
    options: DelegationOptions = {},
  ): { projectPath: string | null; source: string } {
    const explicitProjectId = normalizeTextField((options as { projectId?: unknown }).projectId);
    if (explicitProjectId) {
      const projectById = db
        .prepare(
          `
      SELECT project_path
      FROM projects
      WHERE id = ?
      LIMIT 1
    `,
        )
        .get(explicitProjectId) as { project_path: string | null } | undefined;
      const byIdPath = normalizeTextField(projectById?.project_path);
      if (byIdPath) {
        const detectedByIdPath = detectProjectPath(byIdPath) || byIdPath;
        return { projectPath: detectedByIdPath, source: "project_id" };
      }
    }

    const explicitProjectPath = normalizeTextField(options.projectPath);
    if (explicitProjectPath) {
      const detected = detectProjectPath(explicitProjectPath);
      if (detected) return { projectPath: detected, source: "project_path" };
    }

    const contextHint = normalizeTextField(options.projectContext);
    if (contextHint) {
      const detectedFromContext = detectProjectPath(contextHint);
      if (detectedFromContext) return { projectPath: detectedFromContext, source: "project_context" };

      const newProjectHint =
        /?좉퇋\s*?꾨줈?앺듃|??\s*?꾨줈?앺듃|new project|greenfield|from scratch|?계쫸.*?쀣꺆?멥궒??깉|?곈」??i.test(
          contextHint,
        );
      if (newProjectHint) {
        return { projectPath: getDefaultProjectRoot(), source: "new_project_default" };
      }
    }

    const detectedFromMessage = detectProjectPath(ceoMessage);
    if (detectedFromMessage) return { projectPath: detectedFromMessage, source: "message" };

    return { projectPath: null, source: "none" };
  }

  const { recoverCrossDeptQueueAfterMissingCallback, startCrossDeptCooperation } = createCrossDeptCooperationTools({
    db,
    nowMs,
    appendTaskLog,
    broadcast,
    recordTaskCreationAudit,
    delegatedTaskToSubtask,
    crossDeptNextCallbacks,
    findTeamLeader,
    findBestSubordinate,
    resolveLang,
    getDeptName,
    getAgentDisplayName,
    sendAgentMessage,
    notifyCeo,
    l,
    pickL,
    startTaskExecutionForAgent,
    linkCrossDeptTaskToParentSubtask,
    detectProjectPath,
    resolveProjectPath,
    logsDir,
    getDeptRoleConstraint,
    getRecentConversationContext,
    buildAvailableSkillsPromptBlock,
    buildTaskExecutionPrompt,
    hasExplicitWarningFixRequest,
    ensureTaskExecutionSession,
    getProviderModelConfig,
    spawnCliAgent,
    handleSubtaskDelegationComplete,
    handleTaskRunComplete,
    startProgressTimer,
  });

  const { stripReportRequestPrefix, detectReportOutputFormat, pickPlanningReportAssignee, handleReportRequest } =
    createReportRoutingTools({
      db,
      nowMs,
      randomDelay,
      resolveLang,
      detectProjectPath,
      normalizeTextField,
      recordTaskCreationAudit,
      appendTaskLog,
      getAgentDisplayName,
      sendAgentMessage,
      notifyCeo,
      l,
      pickL,
      broadcast,
      isTaskWorkflowInterrupted,
      startTaskExecutionForAgent,
    });

  return {
    reconcileCrossDeptSubtasks,
    recoverCrossDeptQueueAfterMissingCallback,
    startCrossDeptCooperation,
    detectProjectPath,
    resolveProjectPath,
    getLatestKnownProjectPath,
    getDefaultProjectRoot,
    resolveDirectiveProjectPath,
    stripReportRequestPrefix,
    detectReportOutputFormat,
    pickPlanningReportAssignee,
    handleReportRequest,
  };
}

import { isLang, type Lang } from "../../../types/lang.ts";

export type L10n = Record<Lang, string[]>;

export type DirectivePolicy = {
  skipDelegation: boolean;
  skipDelegationReason: "no_task" | "lightweight" | null;
  skipPlannedMeeting: boolean;
  skipPlanSubtasks: boolean;
};

interface LanguagePolicyDeps {
  db: any;
}

const ROLE_LABEL: Record<string, string> = {
  team_leader: "???

?명꽩",
};

const ROLE_LABEL_L10N: Record<string, Record<Lang, string>> = {
  team_leader: { ko: "???

 ").trim();
  const compact = normalized.replace(/\s+/g, "");
  const includesTerm = (term: string): boolean => {
    const termNorm = term.toLowerCase();
    return normalized.includes(termNorm) || compact.includes(termNorm.replace(/\s+/g, ""));
  };
  return terms.some(includesTerm);
}

function normalizeForSearch(value: unknown): string {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function compactForSearch(value: unknown): string {
  return normalizeForSearch(value).replace(/\s+/g, "");
}

function collectDepartmentAliases(input: unknown): string[] {
  const base = String(input ?? "").trim();
  if (!base) return [];
  const out = new Set<string>();
  const add = (value: string) => {
    const normalized = normalizeForSearch(value);
    if (normalized.length < 2) return;
    out.add(normalized);
  };

  add(base);
  add(base.replace(/[\s_-]+/g, ""));
  add(base.replace(/\s*(????|遺??department|dept|team|?곥꺖???③?|瀯꾦빣|瀯?永??③뿨)\s*$/i, ""));
  add(base.replace(/[(){}\[\]<>]/g, " "));

  return [...out];
}

export function initializeCollabLanguagePolicy(deps: LanguagePolicyDeps) {
  const { db } = deps;

  function pickRandom<T>(arr: T[]): T {
    return arr[Math.floor(Math.random() * arr.length)];
  }

  function readSettingString(key: string): string | undefined {
    const row = db.prepare("SELECT value FROM settings WHERE key = ?").get(key) as { value: string } | undefined;
    if (!row) return undefined;
    try {
      const parsed = JSON.parse(row.value);
      return typeof parsed === "string" ? parsed : row.value;
    } catch {
      return row.value;
    }
  }

  function getPreferredLanguage(): Lang {
    const settingLang = readSettingString("language");
    return isLang(settingLang) ? settingLang : "en";
  }

  function detectLang(text: string): Lang {
    const ko = text.match(/[\uAC00-\uD7AF\u1100-\u11FF\u3130-\u318F]/g)?.length ?? 0;
    const ja = text.match(/[\u3040-\u309F\u30A0-\u30FF]/g)?.length ?? 0;
    const zh = text.match(/[\u4E00-\u9FFF]/g)?.length ?? 0;
    const total = text.replace(/\s/g, "").length || 1;
    if (ko / total > 0.15) return "ko";
    if (ja / total > 0.15) return "ja";
    if (zh / total > 0.3) return "zh";
    return "en";
  }

  function resolveLang(text?: string, fallback?: Lang): Lang {
    const settingLang = readSettingString("language");
    if (isLang(settingLang)) return settingLang;
    const trimmed = typeof text === "string" ? text.trim() : "";
    if (trimmed) return detectLang(trimmed);
    return fallback ?? getPreferredLanguage();
  }

  function l(ko: string[], en: string[], ja?: string[], zh?: string[]): L10n {
    return {
      ko,
      en,
      ja: ja ?? en.map((s) => s),
      zh: zh ?? en.map((s) => s),
    };
  }

  function pickL(pool: L10n, lang: Lang): string {
    const arr = pool[lang];
    return arr[Math.floor(Math.random() * arr.length)];
  }

  function getFlairs(agentName: string, lang: Lang): string[] {
    const flairs: Record<string, Record<Lang, string[]>> = {
      Aria: {
        ko: ["肄붾뱶 由щ럭 以묒뿉", "由ы뙥?좊쭅 援ъ긽?섎㈃??

?ゅ뒯?뽭깿營꿩뿶"],
      },
    };
    const agentFlairs = flairs[agentName];
    if (agentFlairs) return agentFlairs[lang] ?? agentFlairs.en;
    const defaults: Record<Lang, string[]> = {
      ko: ["?낅Т 泥섎━?섎㈃??

skipDelegationReason"] = isNoTask
      ? "no_task"
      : isLightweight
        ? "lightweight"
        : null;
    const skipPlannedMeeting = !skipDelegation && isNoMeeting;
    const skipPlanSubtasks = skipPlannedMeeting;

    return {
      skipDelegation,
      skipDelegationReason,
      skipPlannedMeeting,
      skipPlanSubtasks,
    };
  }

  function shouldExecuteDirectiveDelegation(policy: DirectivePolicy, explicitSkipPlannedMeeting: boolean): boolean {
    if (!policy.skipDelegation) return true;
    if (explicitSkipPlannedMeeting && policy.skipDelegationReason === "lightweight") return true;
    return false;
  }

  function detectTargetDepartments(message: string): string[] {
    const found = new Set<string>();
    for (const [deptId, keywords] of Object.entries(DEPT_KEYWORDS)) {
      for (const kw of keywords) {
        if (message.includes(kw)) {
          found.add(deptId);
          break;
        }
      }
    }

    // Dynamic department aliases: supports office-pack specific localized names.
    const messageNormalized = normalizeForSearch(message);
    const messageCompact = compactForSearch(message);
    const departments = db.prepare("SELECT id, name, name_ko, name_ja, name_zh FROM departments").all() as Array<{
      id: string;
      name: string;
      name_ko?: string | null;
      name_ja?: string | null;
      name_zh?: string | null;
    }>;
    for (const dept of departments) {
      const aliases = [
        ...collectDepartmentAliases(dept.id),
        ...collectDepartmentAliases(dept.name),
        ...collectDepartmentAliases(dept.name_ko),
        ...collectDepartmentAliases(dept.name_ja),
        ...collectDepartmentAliases(dept.name_zh),
      ];
      for (const alias of aliases) {
        const aliasCompact = alias.replace(/\s+/g, "");
        if (messageNormalized.includes(alias) || (aliasCompact && messageCompact.includes(aliasCompact))) {
          found.add(dept.id);
          break;
        }
      }
    }

    return [...found];
  }

  return {
    DEPT_KEYWORDS,
    pickRandom,
    getPreferredLanguage,
    resolveLang,
    detectLang,
    l,
    pickL,
    getFlairs,
    getRoleLabel,
    classifyIntent,
    analyzeDirectivePolicy,
    shouldExecuteDirectiveDelegation,
    detectTargetDepartments,
  };
}

