import { useEffect, type Dispatch, type MutableRefObject, type SetStateAction } from "react";
import type { TaskReportDetail } from "../api";
import * as api from "../api";
import type {
  Agent,
  CrossDeptDelivery,
  MeetingPresence,
  MeetingReviewDecision,
  Message,
  SubAgent,
  SubTask,
  Task,
  CeoOfficeCall,
  WSEventType,
} from "../types";
import {
  CODEX_THREAD_BINDING_TTL_MS,
  MAX_CEO_OFFICE_CALLS,
  MAX_CODEX_THREAD_BINDINGS,
  MAX_CROSS_DEPT_DELIVERIES,
  MAX_LIVE_MESSAGES,
  MAX_LIVE_SUBAGENTS,
  MAX_LIVE_SUBTASKS,
  MAX_SUBAGENT_STREAM_TAIL_CHARS,
  MAX_SUBAGENT_STREAM_TRACKED_TASKS,
} from "./constants";
import { parseCliSubAgentEvents, shouldParseCliChunkForSubAgents } from "./sub-agent-events";
import type { View } from "./types";
import { appendCapped, areAgentsEquivalent } from "./utils";

type SocketOn = (event: WSEventType, handler: (payload: unknown) => void) => () => void;

interface UseRealtimeSyncParams {
  on: SocketOn;
  scheduleLiveSync: (delayMs?: number) => void;
  agentsRef: MutableRefObject<Agent[]>;
  tasksRef: MutableRefObject<Task[]>;
  subAgentsRef: MutableRefObject<SubAgent[]>;
  viewRef: MutableRefObject<View>;
  activeChatRef: MutableRefObject<{ showChat: boolean; agentId: string | null }>;
  codexThreadToSubAgentIdRef: MutableRefObject<Map<string, string>>;
  codexThreadBindingTsRef: MutableRefObject<Map<string, number>>;
  subAgentStreamTailRef: MutableRefObject<Map<string, string>>;
  setAgents: Dispatch<SetStateAction<Agent[]>>;
  setMessages: Dispatch<SetStateAction<Message[]>>;
  setUnreadAgentIds: Dispatch<SetStateAction<Set<string>>>;
  setTaskReport: Dispatch<SetStateAction<TaskReportDetail | null>>;
  setCrossDeptDeliveries: Dispatch<SetStateAction<CrossDeptDelivery[]>>;
  setCeoOfficeCalls: Dispatch<SetStateAction<CeoOfficeCall[]>>;
  setMeetingPresence: Dispatch<SetStateAction<MeetingPresence[]>>;
  setSubtasks: Dispatch<SetStateAction<SubTask[]>>;
  setSubAgents: Dispatch<SetStateAction<SubAgent[]>>;
  setStreamingMessage: Dispatch<
    SetStateAction<{
      message_id: string;
      agent_id: string;
      agent_name: string;
      agent_avatar: string;
      content: string;
    } | null>
  >;
}

export function useRealtimeSync({
  on,
  scheduleLiveSync,
  agentsRef,
  tasksRef,
  subAgentsRef,
  viewRef,
  activeChatRef,
  codexThreadToSubAgentIdRef,
  codexThreadBindingTsRef,
  subAgentStreamTailRef,
  setAgents,
  setMessages,
  setUnreadAgentIds,
  setTaskReport,
  setCrossDeptDeliveries,
  setCeoOfficeCalls,
  setMeetingPresence,
  setSubtasks,
  setSubAgents,
  setStreamingMessage,
}: UseRealtimeSyncParams): void {
  useEffect(() => {
    const unsubs = [
      on("task_update", () => {
        scheduleLiveSync(80);
      }),
      on("agent_status", (payload: unknown) => {
        const p = payload as Agent & { subAgents?: SubAgent[] };
        const { subAgents: incomingSubAgents, ...agentPatch } = p;
        const hasKnownAgent = agentsRef.current.some((a) => a.id === agentPatch.id);
        if (!hasKnownAgent) {
          scheduleLiveSync(80);
          return;
        }
        setAgents((prev) => {
          const idx = prev.findIndex((a) => a.id === agentPatch.id);
          if (idx < 0) return prev;
          const current = prev[idx];
          const merged = { ...current, ...agentPatch };
          if (areAgentsEquivalent(current, merged)) return prev;
          const next = [...prev];
          next[idx] = merged;
          return next;
        });
        if (incomingSubAgents) {
          setSubAgents((prev) => {
            const others = prev.filter((s) => s.parentAgentId !== p.id);
            const next = [...others, ...incomingSubAgents];
            return next.length > MAX_LIVE_SUBAGENTS ? next.slice(next.length - MAX_LIVE_SUBAGENTS) : next;
          });
        }
      }),
      on("agent_created", () => {
        scheduleLiveSync(60);
      }),
      on("agent_deleted", () => {
        scheduleLiveSync(60);
      }),
      on("departments_changed", () => {
        scheduleLiveSync(60);
      }),
      on("new_message", (payload: unknown) => {
        const msg = payload as Message;
        setMessages((prev) => {
          if (prev.some((m) => m.id === msg.id)) return prev;
          return appendCapped(prev, msg, MAX_LIVE_MESSAGES);
        });
        if (msg.sender_type === "agent" && msg.sender_id) {
          const { showChat: chatOpen, agentId: activeId } = activeChatRef.current;
          if (chatOpen && activeId === msg.sender_id) return;
          setUnreadAgentIds((prev) => {
            if (prev.has(msg.sender_id!)) return prev;
            const next = new Set(prev);
            next.add(msg.sender_id!);
            return next;
          });
        }
      }),
      on("announcement", (payload: unknown) => {
        const msg = payload as Message;
        setMessages((prev) => {
          if (prev.some((m) => m.id === msg.id)) return prev;
          return appendCapped(prev, msg, MAX_LIVE_MESSAGES);
        });
        if (msg.sender_type === "agent" && msg.sender_id) {
          const { showChat: chatOpen, agentId: activeId } = activeChatRef.current;
          if (chatOpen && activeId === msg.sender_id) return;
          setUnreadAgentIds((prev) => {
            if (prev.has(msg.sender_id!)) return prev;
            const next = new Set(prev);
            next.add(msg.sender_id!);
            return next;
          });
        }
      }),
      on("task_report", (payload: unknown) => {
        const p = payload as { task?: { id?: string } } | null;
        const reportTaskId = typeof p?.task?.id === "string" ? p.task.id : null;
        if (!reportTaskId) {
          setTaskReport(payload as TaskReportDetail);
          return;
        }
        api
          .getTaskReportDetail(reportTaskId)
          .then((detail) => setTaskReport(detail))
          .catch(() => setTaskReport(payload as TaskReportDetail));
      }),
      on("cross_dept_delivery", (payload: unknown) => {
        const p = payload as { from_agent_id: string; to_agent_id: string };
        setCrossDeptDeliveries((prev) =>
          appendCapped(
            prev,
            {
              id: `cd-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
              fromAgentId: p.from_agent_id,
              toAgentId: p.to_agent_id,
            },
            MAX_CROSS_DEPT_DELIVERIES,
          ),
        );
      }),
      on("ceo_office_call", (payload: unknown) => {
        const p = payload as {
          from_agent_id: string;
          seat_index?: number;
          phase?: "kickoff" | "review";
          action?: "arrive" | "speak" | "dismiss";
          line?: string;
          decision?: MeetingReviewDecision;
          task_id?: string;
          hold_until?: number;
        };
        if (!p.from_agent_id) return;
        const action = p.action ?? "arrive";
        if (action === "arrive" || action === "speak") {
          setMeetingPresence((prev) => {
            const existing = prev.find((row) => row.agent_id === p.from_agent_id);
            const rest = prev.filter((row) => row.agent_id !== p.from_agent_id);
            const holdUntil =
              action === "arrive"
                ? (p.hold_until ?? existing?.until ?? Date.now() + 600_000)
                : (existing?.until ?? Date.now() + 600_000);
            return [
              ...rest,
              {
                decision:
                  (p.phase ?? existing?.phase ?? "kickoff") === "review"
                    ? (p.decision ?? existing?.decision ?? "reviewing")
                    : null,
                agent_id: p.from_agent_id,
                seat_index: p.seat_index ?? existing?.seat_index ?? 0,
                phase: p.phase ?? existing?.phase ?? "kickoff",
                task_id: p.task_id ?? existing?.task_id ?? null,
                until: holdUntil,
              },
            ];
          });
        } else if (action === "dismiss") {
          setMeetingPresence((prev) => prev.filter((row) => row.agent_id !== p.from_agent_id));
        }
        setCeoOfficeCalls((prev) =>
          appendCapped(
            prev,
            {
              id: `ceo-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
              fromAgentId: p.from_agent_id,
              seatIndex: p.seat_index ?? 0,
              phase: p.phase ?? "kickoff",
              action,
              line: p.line,
              decision: p.decision,
              taskId: p.task_id,
              holdUntil: p.hold_until,
              instant: action === "arrive" && viewRef.current !== "office",
            },
            MAX_CEO_OFFICE_CALLS,
          ),
        );
      }),
      on("subtask_update", (payload: unknown) => {
        const st = payload as SubTask;
        setSubtasks((prev) => {
          const idx = prev.findIndex((s) => s.id === st.id);
          if (idx >= 0) {
            const next = [...prev];
            next[idx] = st;
            return next;
          }
          return appendCapped(prev, st, MAX_LIVE_SUBTASKS);
        });
        scheduleLiveSync(160);
      }),
      on("cli_output", (payload: unknown) => {
        const p = payload as { task_id?: string; stream?: string; data?: string };
        if (typeof p.task_id !== "string" || typeof p.data !== "string") return;
        const threadMap = codexThreadToSubAgentIdRef.current;
        const threadTsMap = codexThreadBindingTsRef.current;
        const pruneCodexThreadBindings = (now: number) => {
          for (const [threadId, ts] of threadTsMap.entries()) {
            if (now - ts <= CODEX_THREAD_BINDING_TTL_MS) continue;
            threadTsMap.delete(threadId);
            threadMap.delete(threadId);
          }
          if (threadMap.size <= MAX_CODEX_THREAD_BINDINGS) return;
          const entries = Array.from(threadTsMap.entries()).sort((a, b) => a[1] - b[1]);
          const overflow = threadMap.size - MAX_CODEX_THREAD_BINDINGS;
          for (let i = 0; i < overflow && i < entries.length; i += 1) {
            const threadId = entries[i][0];
            threadTsMap.delete(threadId);
            threadMap.delete(threadId);
          }
        };
        const now = Date.now();
        pruneCodexThreadBindings(now);
        const tailMap = subAgentStreamTailRef.current;
        const setTaskTail = (taskId: string, rawTail: string) => {
          const trimmedTail =
            rawTail.length > MAX_SUBAGENT_STREAM_TAIL_CHARS
              ? rawTail.slice(rawTail.length - MAX_SUBAGENT_STREAM_TAIL_CHARS)
              : rawTail;
          if (!trimmedTail) {
            tailMap.delete(taskId);
            return;
          }
          if (!tailMap.has(taskId) && tailMap.size >= MAX_SUBAGENT_STREAM_TRACKED_TASKS) {
            const oldestTaskId = tailMap.keys().next().value as string | undefined;
            if (oldestTaskId) tailMap.delete(oldestTaskId);
          }
          tailMap.set(taskId, trimmedTail);
        };

        const previousTail = tailMap.get(p.task_id) ?? "";
        const combined = previousTail + p.data;
        let lines: string[] = [];
        const lastNewline = combined.lastIndexOf("\n");

        if (lastNewline < 0) {
          setTaskTail(p.task_id, combined);
          const singleLineCandidate = combined.trim();
          if (
            singleLineCandidate &&
            singleLineCandidate[0] === "{" &&
            singleLineCandidate[singleLineCandidate.length - 1] === "}" &&
            shouldParseCliChunkForSubAgents(singleLineCandidate)
          ) {
            lines = [singleLineCandidate];
            setTaskTail(p.task_id, "");
          } else {
            return;
          }
        } else {
          const completeChunk = combined.slice(0, lastNewline);
          const nextTail = combined.slice(lastNewline + 1);
          setTaskTail(p.task_id, nextTail);
          if (!shouldParseCliChunkForSubAgents(completeChunk)) return;
          lines = completeChunk.split("\n");
        }
        const knownSubAgentIds = new Set(subAgentsRef.current.map((s) => s.id));
        const doneSubAgentIds = new Set(subAgentsRef.current.filter((s) => s.status === "done").map((s) => s.id));
        let cachedParentAgentId: string | null | undefined;
        const resolveParentAgentId = () => {
          if (cachedParentAgentId !== undefined) return cachedParentAgentId;
          const byAgent = agentsRef.current.find((a) => a.current_task_id === p.task_id)?.id ?? null;
          if (byAgent) {
            cachedParentAgentId = byAgent;
            return byAgent;
          }
          const byTask = tasksRef.current.find((t) => t.id === p.task_id)?.assigned_agent_id ?? null;
          cachedParentAgentId = byTask;
          return byTask;
        };
        const upsertSubAgent = (subAgentId: string, taskLabel: string | null) => {
          knownSubAgentIds.add(subAgentId);
          doneSubAgentIds.delete(subAgentId);
          const parentAgentId = resolveParentAgentId();
          setSubAgents((prev) => {
            const idx = prev.findIndex((s) => s.id === subAgentId);
            if (idx >= 0) {
              const current = prev[idx];
              const nextTask = taskLabel ?? current.task;
              const nextParentAgentId = current.parentAgentId || parentAgentId || current.parentAgentId;
              if (current.task === nextTask && current.parentAgentId === nextParentAgentId) return prev;
              const next = [...prev];
              next[idx] = { ...current, task: nextTask, parentAgentId: nextParentAgentId };
              return next;
            }
            if (!parentAgentId) return prev;
            return appendCapped(
              prev,
              {
                id: subAgentId,
                parentAgentId,
                task: taskLabel ?? "Sub-task",
                status: "working" as const,
              },
              MAX_LIVE_SUBAGENTS,
            );
          });
        };
        const markSubAgentDone = (subAgentId: string) => {
          if (!knownSubAgentIds.has(subAgentId) || doneSubAgentIds.has(subAgentId)) return;
          doneSubAgentIds.add(subAgentId);
          for (const [threadId, mappedSubAgentId] of threadMap.entries()) {
            if (mappedSubAgentId !== subAgentId) continue;
            threadMap.delete(threadId);
            threadTsMap.delete(threadId);
          }
          setSubAgents((prev) => {
            const idx = prev.findIndex((s) => s.id === subAgentId);
            if (idx < 0 || prev[idx].status === "done") return prev;
            const next = [...prev];
            next[idx] = { ...prev[idx], status: "done" as const };
            return next;
          });
        };
        for (const rawLine of lines) {
          const line = rawLine.trim();
          if (!line || line[0] !== "{") continue;
          if (!shouldParseCliChunkForSubAgents(line)) continue;
          let json: Record<string, unknown> | null = null;
          try {
            json = JSON.parse(line) as Record<string, unknown>;
          } catch {
            continue;
          }
          if (!json) continue;
          const events = parseCliSubAgentEvents(json);
          for (const event of events) {
            if (event.kind === "spawn") {
              upsertSubAgent(event.id, event.task);
              continue;
            }
            if (event.kind === "done") {
              markSubAgentDone(event.id);
              continue;
            }
            if (event.kind === "bind_thread") {
              threadMap.set(event.threadId, event.subAgentId);
              threadTsMap.set(event.threadId, now);
              if (threadMap.size > MAX_CODEX_THREAD_BINDINGS) {
                pruneCodexThreadBindings(now);
              }
              continue;
            }
            const mappedSubAgentId = threadMap.get(event.threadId);
            if (!mappedSubAgentId) continue;
            threadMap.delete(event.threadId);
            threadTsMap.delete(event.threadId);
            markSubAgentDone(mappedSubAgentId);
          }
        }
      }),
      on("chat_stream", (payload: unknown) => {
        const p = payload as {
          phase: "start" | "delta" | "end";
          message_id: string;
          agent_id: string;
          agent_name?: string;
          agent_avatar?: string;
          text?: string;
          content?: string;
          created_at?: number;
        };
        if (p.phase === "start") {
          setStreamingMessage({
            message_id: p.message_id,
            agent_id: p.agent_id,
            agent_name: p.agent_name ?? "",
            agent_avatar: p.agent_avatar ?? "",
            content: "",
          });
        } else if (p.phase === "delta") {
          setStreamingMessage((prev) => {
            if (!prev || prev.message_id !== p.message_id) return prev;
            return { ...prev, content: prev.content + (p.text ?? "") };
          });
        } else if (p.phase === "end") {
          setStreamingMessage(null);
          if (p.content && p.message_id) {
            const finalMsg: Message = {
              id: p.message_id,
              sender_type: "agent",
              sender_id: p.agent_id,
              receiver_type: "agent",
              receiver_id: null,
              content: p.content,
              message_type: "chat",
              task_id: null,
              created_at: p.created_at ?? Date.now(),
            };
            setMessages((prev) => {
              if (prev.some((m) => m.id === finalMsg.id)) return prev;
              return appendCapped(prev, finalMsg, MAX_LIVE_MESSAGES);
            });
          }
        }
      }),
    ];
    return () => unsubs.forEach((fn) => fn());
  }, [on, scheduleLiveSync]);

  useEffect(() => {
    let timer: ReturnType<typeof setInterval>;
    function start() {
      timer = setInterval(() => scheduleLiveSync(0), 5000);
    }
    function handleVisibility() {
      clearInterval(timer);
      if (!document.hidden) {
        scheduleLiveSync(0);
        start();
      }
    }
    start();
    document.addEventListener("visibilitychange", handleVisibility);
    return () => {
      clearInterval(timer);
      document.removeEventListener("visibilitychange", handleVisibility);
    };
  }, [scheduleLiveSync]);
}

import { useCallback, useEffect, useMemo, useState, type DragEvent } from "react";
import { motion } from "framer-motion";
import type { Agent, Department } from "../types";
import { useI18n } from "../i18n";
import * as api from "../api";
import { normalizeOfficeWorkflowPack } from "../app/office-workflow-pack";
import { buildSpriteMap } from "./AgentAvatar";
import AgentFormModal from "./agent-manager/AgentFormModal";
import AgentsTab from "./agent-manager/AgentsTab";
import { BLANK, ICON_SPRITE_POOL } from "./agent-manager/constants";
import DepartmentFormModal from "./agent-manager/DepartmentFormModal";
import DepartmentsTab from "./agent-manager/DepartmentsTab";
import { StackedSpriteIcon } from "./agent-manager/EmojiPicker";
import type { AgentManagerProps, FormData } from "./agent-manager/types";
import { pickRandomSpritePair } from "./agent-manager/utils";

export default function AgentManager({
  agents,
  departments,
  onAgentsChange,
  activeOfficeWorkflowPack,
  dbBackedOfficePack = false,
  onSaveOfficePackProfile,
}: AgentManagerProps) {
  const { t, locale } = useI18n();
  const isKo = locale.startsWith("ko");
  const tr = (ko: string, en: string) => t({ ko, en, ja: en, zh: en });
  const officePackKey = normalizeOfficeWorkflowPack(activeOfficeWorkflowPack);
  const isIsolatedPack = officePackKey !== "development";
  const useDbBackedPack = isIsolatedPack && dbBackedOfficePack;

  const [subTab, setSubTab] = useState<"agents" | "departments">("agents");
  const [search, setSearch] = useState("");
  const [deptTab, setDeptTab] = useState("all");
  const [modalAgent, setModalAgent] = useState<Agent | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState<FormData>({ ...BLANK });
  const [saving, setSaving] = useState(false);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const [showDeptModal, setShowDeptModal] = useState(false);
  const [editDept, setEditDept] = useState<Department | null>(null);
  const [deptOrder, setDeptOrder] = useState<Department[]>([]);
  const [deptOrderDirty, setDeptOrderDirty] = useState(false);
  const [reorderSaving, setReorderSaving] = useState(false);
  const [draggingDeptId, setDraggingDeptId] = useState<string | null>(null);
  const [dragOverDeptId, setDragOverDeptId] = useState<string | null>(null);
  const [dragOverPosition, setDragOverPosition] = useState<"before" | "after" | null>(null);

  const persistIsolatedProfile = useCallback(
    async (nextDepartments: Department[], nextAgents: Agent[]) => {
      if (!isIsolatedPack) return;
      await onSaveOfficePackProfile(officePackKey, {
        departments: nextDepartments,
        agents: nextAgents,
        updated_at: Date.now(),
      });
    },
    [isIsolatedPack, officePackKey, onSaveOfficePackProfile],
  );

  useEffect(() => {
    setDeptOrder([...departments].sort((a, b) => a.sort_order - b.sort_order));
    setDeptOrderDirty(false);
    setDraggingDeptId(null);
    setDragOverDeptId(null);
    setDragOverPosition(null);
  }, [departments]);

  const spriteMap = buildSpriteMap(agents);
  const randomIconSprites = useMemo(
    () => ({
      tab: pickRandomSpritePair(ICON_SPRITE_POOL),
      total: pickRandomSpritePair(ICON_SPRITE_POOL),
    }),
    [],
  );

  const filteredAgents = useMemo(
    () =>
      agents.filter((agent) => {
        if (deptTab !== "all" && agent.department_id !== deptTab) return false;
        if (!search) return true;
        const query = search.toLowerCase();
        return (
          agent.name.toLowerCase().includes(query) ||
          agent.name_ko.toLowerCase().includes(query) ||
          (agent.name_ja || "").toLowerCase().includes(query) ||
          (agent.name_zh || "").toLowerCase().includes(query)
        );
      }),
    [agents, deptTab, search],
  );

  const sortedAgents = useMemo(() => {
    const roleOrder: Record<string, number> = { team_leader: 0, senior: 1, junior: 2, intern: 3 };
    return [...filteredAgents].sort(
      (a, b) => (roleOrder[a.role] ?? 9) - (roleOrder[b.role] ?? 9) || a.name.localeCompare(b.name),
    );
  }, [filteredAgents]);

  const openCreate = useCallback(() => {
    setModalAgent(null);
    setForm({ ...BLANK, department_id: deptTab !== "all" ? deptTab : departments[0]?.id || "" });
    setShowModal(true);
  }, [deptTab, departments]);

  const openEdit = useCallback(
    (agent: Agent) => {
      setModalAgent(agent);
      const computed = agent.sprite_number ?? buildSpriteMap(agents).get(agent.id) ?? null;
      setForm({
        name: agent.name,
        name_ko: agent.name_ko,
        name_ja: agent.name_ja || "",
        name_zh: agent.name_zh || "",
        department_id: agent.department_id || "",
        role: agent.role,
        cli_provider: agent.cli_provider,
        avatar_emoji: agent.avatar_emoji,
        sprite_number: computed,
        personality: agent.personality || "",
        persona_id: agent.persona_id || undefined,
      });
      setShowModal(true);
    },
    [agents],
  );

  const closeModal = useCallback(() => {
    setShowModal(false);
    setModalAgent(null);
  }, []);

  const handleSave = useCallback(async () => {
    if (!form.name.trim()) return;
    setSaving(true);
    try {
      const departmentId = form.department_id.trim();
      const basePayload = {
        name: form.name.trim(),
        name_ko: form.name_ko.trim(),
        name_ja: form.name_ja.trim(),
        name_zh: form.name_zh.trim(),
        role: form.role,
        cli_provider: form.cli_provider,
        avatar_emoji: form.avatar_emoji || "?쨼",
        sprite_number: form.sprite_number,
        personality: form.personality.trim() || null,
        persona_id: form.persona_id || null,
      };
      if (isIsolatedPack) {
        if (useDbBackedPack) {
          if (modalAgent) {
            await api.updateAgent(modalAgent.id, {
              ...basePayload,
              department_id: departmentId || null,
              workflow_pack_key: officePackKey,
            });
            const nextAgents = agents.map((agent) =>
              agent.id === modalAgent.id
                ? {
                    ...agent,
                    ...basePayload,
                    department_id: departmentId || null,
                  }
                : agent,
            );
            await persistIsolatedProfile(departments, nextAgents);
          } else {
            const createdAgent = await api.createAgent({
              ...basePayload,
              department_id: departmentId || null,
              workflow_pack_key: officePackKey,
            });
            await persistIsolatedProfile(departments, [...agents, createdAgent]);
          }
          onAgentsChange();
        } else {
          const nextAgents = modalAgent
            ? agents.map((agent) =>
                agent.id === modalAgent.id
                  ? {
                      ...agent,
                      ...basePayload,
                      department_id: departmentId || null,
                    }
                  : agent,
              )
            : [
                ...agents,
                {
                  id:
                    typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
                      ? crypto.randomUUID()
                      : `agent-${Date.now()}`,
                  ...basePayload,
                  department_id: departmentId || null,
                  status: "idle" as const,
                  current_task_id: null,
                  stats_tasks_done: 0,
                  stats_xp: 0,
                  created_at: Date.now(),
                },
              ];
          await persistIsolatedProfile(departments, nextAgents);
        }
      } else {
        if (modalAgent) {
          await api.updateAgent(modalAgent.id, {
            ...basePayload,
            department_id: departmentId || null,
          });
        } else {
          await api.createAgent({
            ...basePayload,
            department_id: departmentId || null,
          });
        }
        onAgentsChange();
      }
      closeModal();
    } catch (err) {
      console.error("Save failed:", err);
    } finally {
      setSaving(false);
    }
  }, [
    agents,
    closeModal,
    departments,
    form,
    isIsolatedPack,
    modalAgent,
    onAgentsChange,
    persistIsolatedProfile,
    useDbBackedPack,
  ]);

  const handleDelete = useCallback(
    async (id: string) => {
      setSaving(true);
      try {
        if (isIsolatedPack) {
          if (useDbBackedPack) {
            await api.deleteAgent(id);
            const nextAgents = agents.filter((agent) => agent.id !== id);
            await persistIsolatedProfile(departments, nextAgents);
            onAgentsChange();
          } else {
            const nextAgents = agents.filter((agent) => agent.id !== id);
            await persistIsolatedProfile(departments, nextAgents);
          }
        } else {
          await api.deleteAgent(id);
          onAgentsChange();
        }
        setConfirmDeleteId(null);
        if (modalAgent?.id === id) closeModal();
      } catch (err) {
        console.error("Delete failed:", err);
      } finally {
        setSaving(false);
      }
    },
    [
      agents,
      closeModal,
      departments,
      isIsolatedPack,
      modalAgent,
      onAgentsChange,
      persistIsolatedProfile,
      useDbBackedPack,
    ],
  );

  const openCreateDept = useCallback(() => {
    setEditDept(null);
    setShowDeptModal(true);
  }, []);

  const openEditDept = useCallback((department: Department) => {
    setEditDept(department);
    setShowDeptModal(true);
  }, []);

  const closeDeptModal = useCallback(() => {
    setShowDeptModal(false);
    setEditDept(null);
  }, []);

  const moveDept = useCallback(
    (index: number, direction: -1 | 1) => {
      const nextOrder = [...deptOrder];
      const target = index + direction;
      if (target < 0 || target >= nextOrder.length) return;
      [nextOrder[index], nextOrder[target]] = [nextOrder[target], nextOrder[index]];
      setDeptOrder(nextOrder);
      setDeptOrderDirty(true);
    },
    [deptOrder],
  );

  const getDropPosition = useCallback((event: DragEvent<HTMLDivElement>): "before" | "after" => {
    const rect = event.currentTarget.getBoundingClientRect();
    return event.clientY < rect.top + rect.height / 2 ? "before" : "after";
  }, []);

  const clearDeptDragState = useCallback(() => {
    setDraggingDeptId(null);
    setDragOverDeptId(null);
    setDragOverPosition(null);
  }, []);

  const moveDeptByDrag = useCallback(
    (dragDeptId: string, targetDeptId: string, position: "before" | "after") => {
      if (dragDeptId === targetDeptId) return;
      const fromIndex = deptOrder.findIndex((department) => department.id === dragDeptId);
      const targetIndex = deptOrder.findIndex((department) => department.id === targetDeptId);
      if (fromIndex < 0 || targetIndex < 0) return;

      const nextOrder = [...deptOrder];
      const [dragged] = nextOrder.splice(fromIndex, 1);
      let insertIndex = targetIndex + (position === "after" ? 1 : 0);
      if (fromIndex < insertIndex) insertIndex -= 1;
      insertIndex = Math.max(0, Math.min(insertIndex, nextOrder.length));
      nextOrder.splice(insertIndex, 0, dragged);

      const changed = nextOrder.some((department, i) => department.id !== deptOrder[i]?.id);
      if (!changed) return;
      setDeptOrder(nextOrder);
      setDeptOrderDirty(true);
    },
    [deptOrder],
  );

  const saveDeptOrder = useCallback(async () => {
    setReorderSaving(true);
    try {
      const nextDepartments = deptOrder.map((department, index) => ({
        ...department,
        sort_order: index + 1,
      }));
      if (isIsolatedPack) {
        if (useDbBackedPack) {
          const orders = nextDepartments.map((department) => ({
            id: department.id,
            sort_order: department.sort_order,
          }));
          await api.reorderDepartments(orders, { workflowPackKey: officePackKey });
          await persistIsolatedProfile(nextDepartments, agents);
          onAgentsChange();
        } else {
          await persistIsolatedProfile(nextDepartments, agents);
        }
      } else {
        const orders = nextDepartments.map((department) => ({ id: department.id, sort_order: department.sort_order }));
        await api.reorderDepartments(orders);
        onAgentsChange();
      }
      setDeptOrderDirty(false);
    } catch (err) {
      console.error("Reorder failed:", err);
    } finally {
      setReorderSaving(false);
    }
  }, [agents, deptOrder, isIsolatedPack, onAgentsChange, persistIsolatedProfile, useDbBackedPack]);

  const resetDeptOrder = useCallback(() => {
    setDeptOrder([...departments].sort((a, b) => a.sort_order - b.sort_order));
    setDeptOrderDirty(false);
  }, [departments]);

  const handleDeptDragStart = useCallback((deptId: string, event: DragEvent<HTMLDivElement>) => {
    setDraggingDeptId(deptId);
    setDragOverDeptId(null);
    setDragOverPosition(null);
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("text/plain", deptId);
  }, []);

  const handleDeptDragOver = useCallback(
    (deptId: string, event: DragEvent<HTMLDivElement>) => {
      if (!draggingDeptId || draggingDeptId === deptId) return;
      event.preventDefault();
      const nextPosition = getDropPosition(event);
      if (dragOverDeptId !== deptId || dragOverPosition !== nextPosition) {
        setDragOverDeptId(deptId);
        setDragOverPosition(nextPosition);
      }
      event.dataTransfer.dropEffect = "move";
    },
    [dragOverDeptId, dragOverPosition, draggingDeptId, getDropPosition],
  );

  const handleDeptDrop = useCallback(
    (deptId: string, event: DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      const droppedId = event.dataTransfer.getData("text/plain") || draggingDeptId;
      if (droppedId && droppedId !== deptId) {
        moveDeptByDrag(droppedId, deptId, getDropPosition(event));
      }
      clearDeptDragState();
    },
    [clearDeptDragState, draggingDeptId, getDropPosition, moveDeptByDrag],
  );

  const handleDbBackedDepartmentSave = useCallback(
    async (input: {
      mode: "create" | "update";
      id: string;
      payload: {
        name: string;
        name_ko: string;
        name_ja: string | null;
        name_zh: string | null;
        icon: string;
        color: string;
        description: string | null;
        prompt: string | null;
        sort_order: number;
      };
    }) => {
      if (!useDbBackedPack) return;
      if (input.mode === "update") {
        await api.updateDepartment(input.id, {
          name: input.payload.name,
          name_ko: input.payload.name_ko,
          name_ja: input.payload.name_ja,
          name_zh: input.payload.name_zh,
          icon: input.payload.icon,
          color: input.payload.color,
          description: input.payload.description,
          prompt: input.payload.prompt,
          workflow_pack_key: officePackKey,
        });
        const nextDepartments = departments.map((d) =>
          d.id === input.id
            ? {
                ...d,
                name: input.payload.name,
                name_ko: input.payload.name_ko,
                name_ja: input.payload.name_ja,
                name_zh: input.payload.name_zh,
                icon: input.payload.icon,
                color: input.payload.color,
                description: input.payload.description,
                prompt: input.payload.prompt,
              }
            : d,
        );
        await persistIsolatedProfile(nextDepartments, agents);
      } else {
        const created = await api.createDepartment({
          id: input.id,
          name: input.payload.name,
          name_ko: input.payload.name_ko,
          name_ja: input.payload.name_ja ?? undefined,
          name_zh: input.payload.name_zh ?? undefined,
          icon: input.payload.icon,
          color: input.payload.color,
          description: input.payload.description ?? undefined,
          prompt: input.payload.prompt ?? undefined,
          workflow_pack_key: officePackKey,
        });
        await persistIsolatedProfile([...departments, created], agents);
      }
    },
    [agents, departments, officePackKey, persistIsolatedProfile, useDbBackedPack],
  );

  const handleDbBackedDepartmentDelete = useCallback(
    async (departmentId: string) => {
      if (!useDbBackedPack) return;
      await api.deleteDepartment(departmentId, { workflowPackKey: officePackKey });
      const nextDepartments = departments
        .filter((d) => d.id !== departmentId)
        .sort((a, b) => a.sort_order - b.sort_order)
        .map((d, i) => ({ ...d, sort_order: i + 1 }));
      const nextAgents = agents.map((a) =>
        a.department_id === departmentId ? { ...a, department_id: null } : a,
      );
      await persistIsolatedProfile(nextDepartments, nextAgents);
    },
    [agents, departments, officePackKey, persistIsolatedProfile, useDbBackedPack],
  );

  const handleIsolatedDepartmentSave = useCallback(
    async (input: {
      mode: "create" | "update";
      id: string;
      payload: {
        name: string;
        name_ko: string;
        name_ja: string | null;
        name_zh: string | null;
        icon: string;
        color: string;
        description: string | null;
        prompt: string | null;
        sort_order: number;
      };
    }) => {
      if (!isIsolatedPack) return;
      const nextDepartments =
        input.mode === "create"
          ? [
              ...departments,
              {
                id: input.id,
                name: input.payload.name,
                name_ko: input.payload.name_ko,
                name_ja: input.payload.name_ja,
                name_zh: input.payload.name_zh,
                icon: input.payload.icon,
                color: input.payload.color,
                description: input.payload.description,
                prompt: input.payload.prompt,
                sort_order: input.payload.sort_order,
                created_at: Date.now(),
              },
            ]
          : departments.map((department) =>
              department.id === input.id
                ? {
                    ...department,
                    name: input.payload.name,
                    name_ko: input.payload.name_ko,
                    name_ja: input.payload.name_ja,
                    name_zh: input.payload.name_zh,
                    icon: input.payload.icon,
                    color: input.payload.color,
                    description: input.payload.description,
                    prompt: input.payload.prompt,
                    sort_order: input.payload.sort_order,
                  }
                : department,
            );
      await persistIsolatedProfile(nextDepartments, agents);
    },
    [agents, departments, isIsolatedPack, persistIsolatedProfile],
  );

  const handleIsolatedDepartmentDelete = useCallback(
    async (departmentId: string) => {
      if (!isIsolatedPack) return;
      const filteredDepartments = departments
        .filter((department) => department.id !== departmentId)
        .sort((a, b) => a.sort_order - b.sort_order)
        .map((department, index) => ({
          ...department,
          sort_order: index + 1,
        }));
      const nextAgents = agents.map((agent) =>
        agent.department_id === departmentId
          ? {
              ...agent,
              department_id: null,
            }
          : agent,
      );
      await persistIsolatedProfile(filteredDepartments, nextAgents);
    },
    [agents, departments, isIsolatedPack, persistIsolatedProfile],
  );

  return (
    <motion.div
      className="mx-auto max-w-4xl space-y-4 sm:space-y-5"
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.12, ease: "linear" }}
    >
      <div className="flex flex-wrap items-center justify-between gap-3" style={{ borderLeft: "3px solid var(--th-accent)", paddingLeft: "0.75rem" }}>
        <h1
          className="text-sm font-bold uppercase tracking-widest"
          style={{ color: "var(--th-text-heading)", fontFamily: "var(--th-font-mono)" }}
        >
          {tr("吏곸썝愿由?

Agent Management")}
        </h1>
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={openCreateDept}
            className="px-3 py-1.5 text-xs font-mono uppercase transition-colors hover:opacity-90"
            style={{
              borderRadius: "2px",
              border: "1px solid var(--th-border)",
              color: "var(--th-text-heading)",
              background: "var(--th-bg-surface)",
            }}
          >
            + {tr("遺??異붽?", "ADD DEPT")}
          </button>
          <button
            type="button"
            onClick={openCreate}
            className="px-4 py-1.5 text-xs font-mono font-bold uppercase transition-colors hover:opacity-90"
            style={{ borderRadius: "2px", background: "var(--th-accent)", color: "#000" }}
          >
            + {tr("?좉퇋 梨꾩슜", "HIRE")}
          </button>
        </div>
      </div>

      <div
        className="flex"
        style={{ background: "var(--th-bg-surface)", border: "1px solid var(--th-border)", borderRadius: "2px" }}
      >
        {[
          { key: "agents" as const, label: tr("吏곸썝", "AGENTS") },
          { key: "departments" as const, label: tr("遺??

DEPARTMENTS") },
        ].map((tab, idx) => (
          <button
            key={tab.key}
            type="button"
            onClick={() => setSubTab(tab.key)}
            className="flex-1 flex items-center justify-center px-4 py-2 text-xs font-mono font-bold uppercase transition-colors hover:opacity-90"
            style={{
              color: subTab === tab.key ? "var(--th-accent)" : "var(--th-text-muted)",
              background: "transparent",
              borderBottom: subTab === tab.key ? "2px solid var(--th-accent)" : "2px solid transparent",
              borderRight: idx === 0 ? "1px solid var(--th-border)" : "none",
              letterSpacing: "0.08em",
            }}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {subTab === "agents" && (
        <AgentsTab
          tr={tr}
          locale={locale}
          isKo={isKo}
          agents={agents}
          departments={departments}
          deptTab={deptTab}
          setDeptTab={setDeptTab}
          search={search}
          setSearch={setSearch}
          sortedAgents={sortedAgents}
          spriteMap={spriteMap}
          confirmDeleteId={confirmDeleteId}
          setConfirmDeleteId={setConfirmDeleteId}
          onEditAgent={openEdit}
          onEditDepartment={openEditDept}
          onDeleteAgent={handleDelete}
          saving={saving}
          randomIconSprites={{ total: randomIconSprites.total }}
        />
      )}

      {subTab === "departments" && (
        <DepartmentsTab
          tr={tr}
          locale={locale}
          agents={agents}
          departments={departments}
          deptOrder={deptOrder}
          deptOrderDirty={deptOrderDirty}
          reorderSaving={reorderSaving}
          draggingDeptId={draggingDeptId}
          dragOverDeptId={dragOverDeptId}
          dragOverPosition={dragOverPosition}
          onSaveOrder={saveDeptOrder}
          onCancelOrder={resetDeptOrder}
          onMoveDept={moveDept}
          onEditDept={openEditDept}
          onDragStart={handleDeptDragStart}
          onDragOver={handleDeptDragOver}
          onDrop={handleDeptDrop}
          onDragEnd={clearDeptDragState}
        />
      )}

      {showModal && (
        <AgentFormModal
          isKo={isKo}
          locale={locale}
          tr={tr}
          form={form}
          setForm={setForm}
          departments={departments}
          isEdit={!!modalAgent}
          saving={saving}
          onSave={handleSave}
          onClose={closeModal}
        />
      )}

      {showDeptModal && (
        <DepartmentFormModal
          locale={locale}
          tr={tr}
          department={editDept}
          departments={departments}
          workflowPackKey={isIsolatedPack ? officePackKey : undefined}
          onSave={() => {
            if (!isIsolatedPack || useDbBackedPack) onAgentsChange();
          }}
          onSaveDepartment={
            isIsolatedPack
              ? useDbBackedPack
                ? handleDbBackedDepartmentSave
                : handleIsolatedDepartmentSave
              : undefined
          }
          onDeleteDepartment={
            isIsolatedPack
              ? useDbBackedPack
                ? handleDbBackedDepartmentDelete
                : handleIsolatedDepartmentDelete
              : undefined
          }
          onClose={closeDeptModal}
        />
      )}
    </motion.div>
  );
}

import { useState, useEffect, useRef, useMemo, useCallback } from "react";
import type { Agent, Message, Project } from "../types";
import { buildSpriteMap } from "./AgentAvatar";
import { useI18n } from "../i18n";
import { createProject, getProjects } from "../api";
import { uploadChatFiles } from "../api/messaging-runtime-oauth";
import type { ChatAttachment } from "../api/messaging-runtime-oauth";
import { parseDecisionRequest } from "./chat/decision-request";
import type { DecisionOption } from "./chat/decision-request";
import ChatComposer from "./chat-panel/ChatComposer";
import ChatMessageList from "./chat-panel/ChatMessageList";
import ChatPanelHeader from "./chat-panel/ChatPanelHeader";
import { useDecisionReplyHandlers } from "./chat-panel/useDecisionReply";
import {
  ROLE_LABELS,
  STATUS_COLORS,
  STATUS_LABELS,
  type ChatMode,
  type PendingSendAction,
  type ProjectMetaPayload,
  type StreamingMessage,
} from "./chat-panel/model";
import ProjectFlowDialog from "./chat-panel/ProjectFlowDialog";

interface ChatPanelProps {
  selectedAgent: Agent | null;
  messages: Message[];
  agents: Agent[];
  streamingMessage?: StreamingMessage | null;
  onSendMessage: (
    content: string,
    receiverType: "agent" | "department" | "all",
    receiverId?: string,
    messageType?: string,
    projectMeta?: {
      project_id?: string;
      project_path?: string;
      project_context?: string;
    },
  ) => void | Promise<void>;
  onSendAnnouncement: (content: string) => void;
  onSendDirective: (
    content: string,
    projectMeta?: {
      project_id?: string;
      project_path?: string;
      project_context?: string;
    },
  ) => void;
  onClearMessages?: (agentId?: string) => void;
  onClose: () => void;
}

export function ChatPanel({
  selectedAgent,
  messages,
  agents,
  streamingMessage,
  onSendMessage,
  onSendAnnouncement,
  onSendDirective,
  onClearMessages,
  onClose,
}: ChatPanelProps) {
  const [input, setInput] = useState("");
  const [attachments, setAttachments] = useState<File[]>([]);
  const [mode, setMode] = useState<ChatMode>(selectedAgent ? "task" : "announcement");
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [pinnedIds, setPinnedIds] = useState<Set<string>>(() => {
    try {
      const key = `agentdesk_pinned_${selectedAgent?.id ?? "all"}`;
      const raw = localStorage.getItem(key);
      return raw ? new Set(JSON.parse(raw) as string[]) : new Set();
    } catch { return new Set(); }
  });
  const [pinnedBarOpen, setPinnedBarOpen] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const spriteMap = useMemo(() => buildSpriteMap(agents), [agents]);
  const { t, locale } = useI18n();
  const isKorean = locale.startsWith("ko");

  const tr = (ko: string, en: string, ja = en, zh = en) => t({ ko, en, ja, zh });

  const getAgentName = (agent: Agent | null | undefined) => {
    if (!agent) return "";
    return isKorean ? agent.name_ko || agent.name : agent.name || agent.name_ko;
  };

  const getRoleLabel = (role: string) => {
    const label = ROLE_LABELS[role];
    return label ? t(label) : role;
  };

  const getStatusLabel = (status: string) => {
    const label = STATUS_LABELS[status];
    return label ? t(label) : status;
  };

  const selectedDeptName = selectedAgent?.department
    ? isKorean
      ? selectedAgent.department.name_ko || selectedAgent.department.name
      : selectedAgent.department.name || selectedAgent.department.name_ko
    : selectedAgent?.department_id;
  const selectedTaskId = selectedAgent?.current_task_id;

  // Close on Escape key
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);

  // ?ㅽ듃由щ컢 以묒씤 硫붿떆吏媛 ?꾩옱 ?먯씠?꾪듃 寃껋씤吏 ?먮퀎
  const isStreamingForAgent = streamingMessage && selectedAgent && streamingMessage.agent_id === selectedAgent.id;

  // Auto-scroll to bottom on new messages or streaming delta
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, streamingMessage?.content]);

  // Switch mode when agent selection changes
  useEffect(() => {
    if (!selectedAgent) {
      setMode("announcement");
    } else if (mode === "announcement") {
      setMode("task");
    }
  }, [selectedAgent]);

  const isDirectiveMode = input.trimStart().startsWith("$");
  const [pendingSend, setPendingSend] = useState<PendingSendAction | null>(null);
  const [projectFlowOpen, setProjectFlowOpen] = useState(false);
  const [projectFlowStep, setProjectFlowStep] = useState<"choose" | "existing" | "new" | "confirm">("choose");
  const [projectItems, setProjectItems] = useState<Project[]>([]);
  const [projectLoading, setProjectLoading] = useState(false);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [existingProjectInput, setExistingProjectInput] = useState("");
  const [existingProjectError, setExistingProjectError] = useState("");
  const [newProjectName, setNewProjectName] = useState("");
  const [newProjectPath, setNewProjectPath] = useState("");
  const [newProjectGoal, setNewProjectGoal] = useState("");
  const [projectSaving, setProjectSaving] = useState(false);
  const [decisionReplyKey, setDecisionReplyKey] = useState<string | null>(null);
  const isDirectivePending = pendingSend?.kind === "directive";

  const closeProjectFlow = () => {
    setProjectFlowOpen(false);
    setProjectFlowStep("choose");
    setPendingSend(null);
    setSelectedProject(null);
    setExistingProjectInput("");
    setExistingProjectError("");
    setNewProjectName("");
    setNewProjectPath("");
    setNewProjectGoal("");
    setProjectItems([]);
  };

  const loadRecentProjects = useCallback(async () => {
    setProjectLoading(true);
    try {
      const res = await getProjects({ page: 1, page_size: 10 });
      setProjectItems(res.projects.slice(0, 10));
    } catch (err) {
      console.error("Failed to load projects:", err);
    } finally {
      setProjectLoading(false);
    }
  }, []);

  const resolveExistingProjectSelection = useCallback(
    (raw: string): Project | null => {
      const trimmed = raw.trim();
      if (!trimmed || projectItems.length === 0) return null;

      if (/^\d+$/.test(trimmed)) {
        const idx = Number.parseInt(trimmed, 10);
        if (idx >= 1 && idx <= projectItems.length) {
          return projectItems[idx - 1];
        }
      }

      const query = trimmed.toLowerCase();
      const tokens = query.split(/\s+/).filter(Boolean);
      let best: { project: Project; score: number } | null = null;

      for (const p of projectItems) {
        const name = p.name.toLowerCase();
        const path = p.project_path.toLowerCase();
        const goal = p.core_goal.toLowerCase();
        let score = 0;

        if (name === query) score = Math.max(score, 100);
        if (name.startsWith(query)) score = Math.max(score, 90);
        if (name.includes(query)) score = Math.max(score, 80);
        if (path === query) score = Math.max(score, 75);
        if (path.includes(query)) score = Math.max(score, 65);
        if (goal.includes(query)) score = Math.max(score, 50);

        if (tokens.length > 0) {
          const tokenHits = tokens.filter((tk) => name.includes(tk) || path.includes(tk) || goal.includes(tk)).length;
          score = Math.max(score, tokenHits * 20);
        }

        if (!best || score > best.score) {
          best = { project: p, score };
        }
      }

      if (!best || best.score < 50) return null;
      return best.project;
    },
    [projectItems],
  );

  const applyExistingProjectSelection = useCallback(() => {
    const picked = resolveExistingProjectSelection(existingProjectInput);
    if (!picked) {
      setExistingProjectError(
        tr(
          "踰덊샇(1-10) ?먮뒗 ?꾨줈?앺듃紐낆쓣 ?ㅼ떆 ?낅젰?댁＜?몄슂.",
          "Please enter a number (1-10) or a project name.",
          "?ゅ뤇(1-10)?얇걼??깤??궦?㎯궚?덂릫?믣뀯?쎼걮?╉걦?졼걬?꾠?

");
    setSelectedProject(picked);
    setProjectFlowStep("confirm");
  }, [existingProjectInput, resolveExistingProjectSelection]);

  const handleChooseExistingProject = useCallback(() => {
    setProjectFlowStep("existing");
    setExistingProjectInput("");
    setExistingProjectError("");
    void loadRecentProjects();
  }, [loadRecentProjects]);

  const handleSelectExistingProject = useCallback((project: Project, index: number) => {
    setSelectedProject(project);
    setExistingProjectInput(String(index + 1));
    setExistingProjectError("");
    setProjectFlowStep("confirm");
  }, []);

  const handleExistingProjectInputChange = useCallback(
    (value: string) => {
      setExistingProjectInput(value);
      if (existingProjectError) setExistingProjectError("");
    },
    [existingProjectError],
  );

  const dispatchPending = useCallback(
    (action: PendingSendAction, projectMeta?: ProjectMetaPayload) => {
      if (action.kind === "directive") {
        onSendDirective(action.content, projectMeta);
        return;
      }
      if (action.kind === "announcement") {
        onSendAnnouncement(action.content);
        return;
      }
      if (action.kind === "task") {
        onSendMessage(action.content, "agent", action.receiverId, "task_assign", projectMeta);
        return;
      }
      if (action.kind === "report") {
        onSendMessage(action.content, "agent", action.receiverId, "report", projectMeta);
        return;
      }
      if (action.kind === "chat") {
        onSendMessage(action.content, "agent", action.receiverId, "chat", projectMeta);
        return;
      }
      onSendMessage(action.content, "all", undefined, undefined, projectMeta);
    },
    [onSendAnnouncement, onSendDirective, onSendMessage],
  );

  const handleConfirmProject = () => {
    if (!pendingSend || !selectedProject) return;
    const projectMeta: ProjectMetaPayload = {
      project_id: selectedProject.id,
      project_path: selectedProject.project_path,
      project_context: selectedProject.core_goal,
    };
    dispatchPending(pendingSend, projectMeta);
    setInput("");
    textareaRef.current?.focus();
    closeProjectFlow();
  };

  const handleCreateProject = async () => {
    const goal = isDirectivePending ? (pendingSend?.content ?? "").trim() : newProjectGoal.trim();
    if (!newProjectName.trim() || !newProjectPath.trim() || !goal || projectSaving) return;
    setProjectSaving(true);
    try {
      const created = await createProject({
        name: newProjectName.trim(),
        project_path: newProjectPath.trim(),
        core_goal: goal,
      });
      setSelectedProject(created);
      setProjectFlowStep("confirm");
    } catch (err) {
      console.error("Failed to create project:", err);
    } finally {
      setProjectSaving(false);
    }
  };

  const openProjectBranch = (action: PendingSendAction) => {
    setPendingSend(action);
    setProjectFlowOpen(true);
    setProjectFlowStep("choose");
    setSelectedProject(null);
    setExistingProjectInput("");
    setExistingProjectError("");
    setProjectItems([]);
    setNewProjectGoal(action.kind === "directive" ? action.content : "");
  };

  const formatAttachmentPrefix = (uploaded: ChatAttachment[]): string => {
    if (uploaded.length === 0) return "";
    return uploaded
      .map((a) => {
        const sizeStr =
          a.size < 1024
            ? a.size + "B"
            : a.size < 1024 * 1024
              ? (a.size / 1024).toFixed(1) + "KB"
              : (a.size / (1024 * 1024)).toFixed(1) + "MB";
        return `[\u{1F4CE} ${a.fileName} (${sizeStr})]`;
      })
      .join(" ") + "\n";
  };

  const handleSend = async () => {
    const trimmed = input.trim();
    if (!trimmed && attachments.length === 0) return;

    // Upload attachments first if any
    let uploaded: ChatAttachment[] = [];
    if (attachments.length > 0) {
      try {
        uploaded = await uploadChatFiles(attachments);
      } catch (err) {
        console.error("File upload failed:", err);
        // Continue sending the message without attachments
      }
      setAttachments([]);
    }

    const attachmentPrefix = formatAttachmentPrefix(uploaded);
    const contentWithAttachments = attachmentPrefix + trimmed;

    if (!contentWithAttachments.trim()) return;

    let action: PendingSendAction;
    if (trimmed.startsWith("$")) {
      const directiveContent = trimmed.slice(1).trim();
      if (!directiveContent && uploaded.length === 0) return;
      action = { kind: "directive", content: attachmentPrefix + (directiveContent || "") };
    } else if (mode === "announcement") {
      action = { kind: "announcement", content: contentWithAttachments };
    } else if (mode === "task" && selectedAgent) {
      action = { kind: "task", content: contentWithAttachments, receiverId: selectedAgent.id };
    } else if (mode === "report" && selectedAgent) {
      action = {
        kind: "report",
        content: `[${tr("蹂닿퀬 ?붿껌", "Report Request", "?с깮?쇈깉堊앶졏", "?ε몜瑥룡콆")}] ${contentWithAttachments}`,
        receiverId: selectedAgent.id,
      };
    } else if (selectedAgent) {
      action = { kind: "chat", content: contentWithAttachments, receiverId: selectedAgent.id };
    } else {
      action = { kind: "broadcast", content: contentWithAttachments };
    }

    const requiresProject = action.kind === "directive" || action.kind === "task" || action.kind === "report";

    if (requiresProject) {
      openProjectBranch(action);
      return;
    }

    dispatchPending(action);
    setInput("");
    textareaRef.current?.focus();
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      void handleSend();
    }
  };

  useEffect(() => {
    if (!projectFlowOpen) return;
    if (projectFlowStep !== "existing") return;
    void loadRecentProjects();
  }, [projectFlowOpen, projectFlowStep, loadRecentProjects]);

  const canCreateProject =
    Boolean(newProjectName.trim()) &&
    Boolean(newProjectPath.trim()) &&
    Boolean(isDirectivePending ? (pendingSend?.content ?? "").trim() : newProjectGoal.trim());

  const isAnnouncementMode = mode === "announcement";

  // Filter messages relevant to current view (memoized to avoid re-filtering on every render)
  const selectedAgentId = selectedAgent?.id;
  const visibleMessages = useMemo(
    () =>
      messages.filter((msg) => {
        if (!selectedAgentId) {
          return msg.receiver_type === "all" || msg.message_type === "announcement" || msg.message_type === "directive";
        }
        if (selectedTaskId && msg.task_id === selectedTaskId) return true;
        return (
          (msg.sender_type === "ceo" && msg.receiver_type === "agent" && msg.receiver_id === selectedAgentId) ||
          (msg.sender_type === "agent" && msg.sender_id === selectedAgentId) ||
          msg.message_type === "announcement" ||
          msg.message_type === "directive" ||
          msg.receiver_type === "all"
        );
      }),
    [messages, selectedAgentId, selectedTaskId],
  );

  const decisionRequestByMessage = useMemo(() => {
    const mapped = new Map<string, { options: DecisionOption[] }>();
    if (!selectedAgentId) return mapped;
    for (const msg of visibleMessages) {
      if (msg.sender_type !== "agent" || msg.sender_id !== selectedAgentId) continue;
      const parsed = parseDecisionRequest(msg.content);
      if (parsed) mapped.set(msg.id, parsed);
    }
    return mapped;
  }, [selectedAgentId, visibleMessages]);

  const displayMessages = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return visibleMessages;
    return visibleMessages.filter((m) => m.content.toLowerCase().includes(q));
  }, [visibleMessages, searchQuery]);

  const handleSearchToggle = useCallback(() => {
    setSearchOpen((prev) => {
      if (prev) setSearchQuery("");
      return !prev;
    });
  }, []);

  const handlePinToggle = useCallback((msgId: string) => {
    const agentKey = selectedAgent?.id ?? "all";
    setPinnedIds((prev) => {
      const next = new Set(prev);
