  // ?? Floor indicator (shows current floor from camera position) ??????
  const [floorIndicator, setFloorIndicator] = useState<string | null>(null);
  const floorIndicatorTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const updateFloorIndicator = useCallback(() => {
    const app = appRef.current;
    if (!app || totalHRef.current <= 0 || isOverviewModeRef.current) return;

    const { y: scrollY } = app.getCameraScroll();
    const vp = app.getCameraViewportSize();
    const viewCenterY = scrollY + vp.h / 2;
    const towerLocalY = viewCenterY - SKY_H;

    const depts = dataRef.current.departments;
    let label = "";
    if (towerLocalY < ROOF_H) {
      label = "ROOF";
    } else if (towerLocalY < ROOF_H + PENTHOUSE_H) {
      label = "P  CEO";
    } else if (towerLocalY < ROOF_H + PENTHOUSE_H + CONFERENCE_FLOOR_H) {
      label = "CONF";
    } else {
      const floorStartY = ROOF_H + PENTHOUSE_H + CONFERENCE_FLOOR_H;
      const basementStartY = floorStartY + depts.length * FLOOR_TOTAL_H;
      if (towerLocalY >= basementStartY) {
        label = "B1  BREAK";
      } else {
        const idx = Math.floor((towerLocalY - floorStartY) / FLOOR_TOTAL_H);
        const dept = depts[Math.min(idx, depts.length - 1)];
        label = dept ? `F${idx + 1}  ${dept.name}` : `F${idx + 1}`;
      }
    }

    setFloorIndicator(label);
    if (floorIndicatorTimerRef.current) clearTimeout(floorIndicatorTimerRef.current);
    floorIndicatorTimerRef.current = setTimeout(() => setFloorIndicator(null), 1200);
  }, []);

  // ?? Wheel: Ctrl+Wheel = zoom toggle, normal wheel = camera scroll ??
  useEffect(() => {
    const el = containerRef.current?.parentElement?.parentElement ?? containerRef.current;
    if (!el) return;

    const onWheel = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        if (e.deltaY > 0 && !isOverviewModeRef.current) {
          applyCameraOverview();
        } else if (e.deltaY < 0 && isOverviewModeRef.current) {
          applyCameraFloorFocus();
        }
        return;
      }
      // In overview mode, ignore normal wheel scroll
      if (isOverviewModeRef.current) return;
      e.preventDefault();
      cameraTargetRef.current = null; // manual scroll clears area-zoom target
      const app = appRef.current;
      if (!app) return;
      const { y: curY } = app.getCameraScroll();
      const zoom = app.getCameraZoom();
      // Convert CSS deltaY to world units (1.5횞 multiplier for snappier scrolling)
      const scrollDelta = (e.deltaY / zoom) * 1.5;
      const sceneH = totalHRef.current + SKY_H + GROUND_H;
      const vp = app.getCameraViewportSize();
      const maxScrollY = Math.max(0, sceneH - vp.h);
      app.setCameraScroll(0, Math.min(maxScrollY, Math.max(0, curY + scrollDelta)));
      // Trigger floor indicator
      updateFloorIndicator();
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, [applyCameraOverview, applyCameraFloorFocus]);

  // ?? Keyboard shortcuts (Escape=overview, Home/End=top/bottom) ??
  useEffect(() => {
    const isInputFocused = () => {
      const tag = document.activeElement?.tagName;
      return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" ||
        (document.activeElement as HTMLElement)?.isContentEditable;
    };

    const onKeyDown = (e: KeyboardEvent) => {
      if (isInputFocused()) return;
      if (e.code === "Escape") {
        e.preventDefault();
        if (!isOverviewModeRef.current) {
          applyCameraOverview();
        }
      } else if (e.code === "Home") {
        e.preventDefault();
        if (isOverviewModeRef.current) {
          exitOverviewAndScroll(0, 0);
        } else {
          scrollToFloorY(0, 0);
        }
      } else if (e.code === "End") {
        e.preventDefault();
        const nFloors = dataRef.current.departments.length;
        const basementY = ROOF_H + PENTHOUSE_H + CONFERENCE_FLOOR_H + nFloors * FLOOR_TOTAL_H;
        if (isOverviewModeRef.current) {
          exitOverviewAndScroll(basementY, 0.5);
        } else {
          scrollToFloorY(basementY, 0.5);
        }
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [applyCameraOverview, exitOverviewAndScroll, scrollToFloorY]);

  useEffect(() => {
    const prev = prevTaskStatusesRef.current;
    const newlyDone: Array<{ id: string; label: string }> = [];
    for (const task of tasks) {
      const prevStatus = prev.get(task.id);
      if (prevStatus && prevStatus !== "done" && task.status === "done") {
        newlyDone.push({ id: task.id, label: task.title?.slice(0, 20) ?? "DONE" });
      }
      prev.set(task.id, task.status);
    }
    if (newlyDone.length === 0) return;
    const bursts = newlyDone.map((t) => ({
      id: `burst-${t.id}-${Date.now()}`,
      x: 20 + Math.random() * 60,
      y: 20 + Math.random() * 60,
      label: t.label,
    }));
    setCompletionBursts((prev) => [...prev, ...bursts]);
    const timer = setTimeout(() => {
      setCompletionBursts((prev) => prev.filter((b) => !bursts.some((nb) => nb.id === b.id)));
    }, 1400);
    return () => clearTimeout(timer);
  }, [tasks]);

  // Poll visitor state every 1s for FM ticker + CEO incoming alert + dept visitor badges
  const [announcementBanner, setAnnouncementBanner] = useState<{ text: string; sender: string } | null>(null);
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent<{ text: string; sender: string }>).detail;
      setAnnouncementBanner(detail);
      const t = setTimeout(() => setAnnouncementBanner(null), 4500);
      return () => clearTimeout(t);
    };
    window.addEventListener("agentdesk_office_announcement", handler);
    return () => window.removeEventListener("agentdesk_office_announcement", handler);
  }, []);

  const [visitorCount, setVisitorCount] = useState(0);
  const [ceoIncomingCount, setCeoIncomingCount] = useState(0);
  const [visitorsByDeptId, setVisitorsByDeptId] = useState<Record<string, number>>({});
  const [visitingAgentIds, setVisitingAgentIds] = useState<Set<string>>(new Set());
  useEffect(() => {
    const inboundPhases = new Set([
      "walk_to_elev", "fading_out", "in_elev", "fading_in", "walk_to_dest", "at_dest",
    ]);
    const timer = setInterval(() => {
      const visitors = visitorTickRef.current?.visitors ?? [];
      setVisitorCount(visitors.length);
      setCeoIncomingCount(visitors.filter((v) => v.destFloor === 0 && inboundPhases.has(v.phase)).length);
      // Map destFloor ??dept.id using same sort order as OfficeDeptPanel
      const sortedDepts = [...(dataRef.current.departments ?? [])].sort((a, b) => a.sort_order - b.sort_order);
      const byDeptId: Record<string, number> = {};
      for (const v of visitors) {
        if (v.destFloor >= 1 && v.destFloor <= sortedDepts.length && inboundPhases.has(v.phase)) {
          const dept = sortedDepts[v.destFloor - 1];
          if (dept) byDeptId[dept.id] = (byDeptId[dept.id] ?? 0) + 1;
        }
      }
      setVisitorsByDeptId(byDeptId);
      setVisitingAgentIds(new Set(visitors.map((v) => v.agentId)));
      const n = new Date();
      setClockStr(`${n.getHours().toString().padStart(2, "0")}:${n.getMinutes().toString().padStart(2, "0")}`);
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // FM-style live event ticker ??computed from current agent/task state
  const fmTickerEvents = useMemo(() => {
    const working = agents.filter((a) => a.status === "working");
    const idle = agents.filter((a) => a.status === "idle");
    const onBreak = agents.filter((a) => a.status === "break");
    const activeTasks = tasks.filter((t) => t.status === "in_progress");
    const doneTasks = tasks.filter((t) => t.status === "done");
    const events: string[] = [];

    // Headline capacity
    if (agents.length > 0) {
      const actPct = Math.round((working.length / agents.length) * 100);
      events.push(`HQ CAPACITY ${actPct}% 쨌 ${working.length}/${agents.length} ${packVocab.agents.toUpperCase()} ACTIVE`);
    }

    // Working agents + their tasks
    if (working.length > 0) {
      const sample = working.slice(0, 3);
      for (const a of sample) {
        const task = tasks.find((t) => t.assigned_agent_id === a.id && t.status === "in_progress");
        if (task) events.push(`${a.avatar_emoji} ${a.name} >> ${task.title.slice(0, 30)}`);
      }
    }

    // Dept highlights
    const topDept = departments
      .map((d) => {
        const das = agents.filter((a) => a.department_id === d.id);
        const runCount = das.filter((a) => a.status === "working").length;
        return { d, pct: das.length > 0 ? Math.round((runCount / das.length) * 100) : 0 };
      })
      .sort((a, b) => b.pct - a.pct)[0];
    if (topDept && topDept.pct > 0) {
      events.push(`${topDept.d.icon} ${topDept.d.name} LEADS AT ${topDept.pct}% ACTIVITY`);
    }

    if (idle.length > 0) events.push(`${idle.length} ${packVocab.agent.toUpperCase()}${idle.length > 1 ? "S" : ""} ${packVocab.idle.toUpperCase()} ??AWAITING ASSIGNMENT`);
    if (onBreak.length > 0) events.push(`${onBreak.length} IN ${packVocab.breakRoom.toUpperCase()}`);
    if (visitorCount > 0) events.push(`${visitorCount} ${packVocab.agent.toUpperCase()}${visitorCount > 1 ? "S" : ""} ON INTER-DEPT VISIT`);

    // Task throughput
    if (activeTasks.length > 0) events.push(`${activeTasks.length} ${packVocab.task.toUpperCase()}${activeTasks.length > 1 ? "S" : ""} IN PROGRESS`);
    if (doneTasks.length > 0) events.push(`${doneTasks.length} ${packVocab.task.toUpperCase()}${doneTasks.length > 1 ? "S" : ""} ${packVocab.done.toUpperCase()}`);

    // Top XP agent
    const topXpAgent = [...agents].sort((a, b) => (b.stats_xp ?? 0) - (a.stats_xp ?? 0))[0];
    if (topXpAgent && (topXpAgent.stats_xp ?? 0) > 0) {
      events.push(`TOP PERFORMER: ${topXpAgent.avatar_emoji} ${topXpAgent.name} 쨌 ${(topXpAgent.stats_xp ?? 0).toLocaleString()} ${packVocab.xp}`);
    }

    if (events.length === 0) events.push("AGENTDESK HQ ??ALL SYSTEMS NOMINAL");
    return events.join("     //     ");
  }, [agents, tasks, departments, visitorCount, packVocab]);

  return (
    <div className="office-screen">
      {/* ?? Toolbar ?? */}
      <div className="office-toolbar">
        <div className="office-toolbar-breadcrumb">
          <span className="office-toolbar-prompt">??/span>
          <span className="office-toolbar-title">AgentDesk HQ</span>
          <span className="office-toolbar-sep">쨌</span>
          <span className="office-toolbar-sub">
            {departments.length}F Tower
          </span>
        </div>
        <div className="office-toolbar-center">
          <span className="office-toolbar-stat-chip" style={{ color: "#22c55e" }}>
            {agents.filter((a) => a.status === "working").length} {packVocab.running.toUpperCase()}
          </span>
          <span className="office-toolbar-stat-chip">
            {tasks.filter((t) => t.status === "in_progress").length} {packVocab.tasks.toUpperCase()}
          </span>
          {visitorCount > 0 && (
            <span className="office-toolbar-stat-chip" style={{ color: "var(--th-accent)" }}>
              {visitorCount} VISITING
            </span>
          )}
          {currentSeasonKey !== "none" && (
            <span className="office-toolbar-stat-chip" style={{ color: "rgba(255,255,255,0.5)" }}>
              {currentSeasonKey === "spring" ? "SPRING" : currentSeasonKey === "summer" ? "SUMMER" : currentSeasonKey === "autumn" ? "AUTUMN" : "WINTER"}
            </span>
          )}
        </div>
        <div className="office-toolbar-actions">
          <span style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.65rem", color: "var(--th-accent)", letterSpacing: 2, opacity: 0.85 }}>
            {clockStr}
          </span>
          {/* Zoom controls */}
          <div style={{ display: "flex", alignItems: "center", gap: 0, border: "1px solid var(--th-border)", borderRadius: 2 }}>
            <button
              className="office-toolbar-btn"
              title="Zoom In (Floor Focus)"
              onClick={() => { if (isOverviewMode) applyCameraFloorFocus(); }}
              style={{ borderRadius: "2px 0 0 2px", border: "none", padding: "2px 6px", fontSize: "0.7rem", opacity: isOverviewMode ? 1 : 0.4 }}
            >
              +
            </button>
            <button
              className="office-toolbar-btn"
              title={isOverviewMode ? "Floor Focus (Esc)" : "Overview (Esc)"}
              onClick={handleToggleOverview}
              style={{
                border: "none", borderLeft: "1px solid var(--th-border)", borderRight: "1px solid var(--th-border)",
                padding: "2px 8px", fontSize: "0.6rem", letterSpacing: 1,
                ...(isOverviewMode ? { color: "var(--th-accent)" } : {}),
              }}
            >
              {isOverviewMode ? "FIT" : "1:1"}
            </button>
            <button
              className="office-toolbar-btn"
              title="Zoom Out (Overview)"
              onClick={() => { if (!isOverviewMode) applyCameraOverview(); }}
              style={{ borderRadius: "0 2px 2px 0", border: "none", padding: "2px 6px", fontSize: "0.7rem", opacity: isOverviewMode ? 0.4 : 1 }}
            >
              -
            </button>
          </div>
          <button className="office-toolbar-btn" title="Season / Style settings" onClick={onOpenRoomManager}>
            Season ??n          </button>
          <button className="office-toolbar-btn" title="Season / Style settings" onClick={onOpenRoomManager}>
            Style ??n          </button>
        </div>
      </div>

      {/* ?? 3-column body ?? */}
      <div className="office-body">
        {/* Left ??department list */}
        <motion.div
          className="office-left"
          initial={{ opacity: 0, x: -16 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.18, ease: "linear" }}
        >
          <OfficeDeptPanel
            departments={sortedDepartments}
            agents={agents}
            tasks={tasks}
            selectedDeptId={selectedDept?.id ?? null}
            onSelectDept={handleCanvasSelectDept}
            onCallElevator={handleCallElevator}
            onScrollToFloor={handleScrollToFloor}
            visitorsByDeptId={visitorsByDeptId}
            cliStatus={cliStatus}
            cliUsage={cliUsage}
            cliUsageRefreshing={cliUsageRefreshing}
            onRefreshCliUsage={onRefreshCliUsage}
            isOverviewMode={isOverviewMode}
          />
        </motion.div>

        {/* Center ??PixiJS canvas + fixed overlay for HUD elements */}
        <div style={{ position: "relative", flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
          <div className="office-canvas-wrap" style={{ position: "relative", overflow: "hidden" }}>
            {/* office-canvas-frame: fills container, amber border, camera handles scroll */}
            <div className="office-canvas-frame" style={{ display: "block", width: "100%", height: "100%" }}>
              <div
                ref={containerRef}
                style={{ lineHeight: 0, outline: "none", display: "block", width: "100%", height: "100%" }}
                tabIndex={0}
              />
            </div>
            {!isOverviewMode && (
              <VirtualPadOverlay
                showVirtualPad={showVirtualPad}
                t={t}
                onInteract={triggerDepartmentInteract}
                onSetMoveDirectionPressed={setMoveDirectionPressed}
              />
            )}

            {/* ?? Semantic Zoom: Full-screen department list (overview) or hidden ?? */}
            <OfficeOverviewBars
              departments={sortedDepartments}
              agents={agents}
              tasks={tasks}
              isOverviewMode={isOverviewMode}
              onClickFloor={exitOverviewAndScroll}
              onSelectDept={(dept) => { setSelectedDept(dept); setSelectedAgent(null); }}
              containerRef={containerRef}
              totalH={totalHRef.current}
              customDeptThemes={customDeptThemes}
            />
          </div>

          {/* ?? Fixed overlay (doesn't scroll with canvas) ?? */}
          <div
            className="pointer-events-none"
            style={{ position: "absolute", inset: 0, zIndex: 40, overflow: "hidden" }}
          >
            {/* ?? Minimap (hidden in overview ??whole scene already visible) ?? */}
            {!isOverviewMode && (
              <div className="pointer-events-auto" style={{ position: "absolute", bottom: 8, right: 8 }}>
                <OfficeMinimap
                  departments={sortedDepartments}
                  totalH={totalHRef.current}
                  appRef={appRef}
                  isOverviewMode={isOverviewMode}
                  customDeptThemes={customDeptThemes}
                />
              </div>
            )}

            {/* ?? Floor Indicator (shows current floor during scroll) ?? */}
            {floorIndicator && !isOverviewMode && (
              <div
                style={{
                  position: "absolute",
                  left: 12,
                  top: "50%",
                  transform: "translateY(-50%)",
                  zIndex: 60,
                  background: "rgba(0,0,0,0.82)",
                  border: "1px solid rgba(245,158,11,0.5)",
                  borderRadius: 2,
                  padding: "4px 10px",
                  fontFamily: "var(--th-font-mono)",
                  fontSize: 11,
                  color: "var(--th-accent)",
                  letterSpacing: 1.5,
                  whiteSpace: "nowrap",
                  transition: "opacity 0.15s",
                }}
              >
                {floorIndicator}
              </div>
            )}

            {/* ?? Global Announcement Banner ?? */}
            {announcementBanner && (
              <motion.div
                key={announcementBanner.text + announcementBanner.sender}
                initial={{ y: -60, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={{ y: -60, opacity: 0 }}
                transition={{ duration: 0.25, ease: "linear" }}
                style={{
                  position: "absolute",
                  top: 8,
                  left: "50%",
                  transform: "translateX(-50%)",
                  zIndex: 80,
                  minWidth: 280,
                  maxWidth: "90%",
                  background: "rgba(0,0,0,0.88)",
                  border: "1px solid rgba(245,158,11,0.6)",
                  borderRadius: "2px",
                  padding: "8px 14px",
                  pointerEvents: "none",
                }}
              >
                <div className="flex items-center gap-2">
                  <span style={{ color: "var(--th-accent)", fontSize: 9, fontFamily: "monospace", letterSpacing: 1 }}>??BROADCAST</span>
                  <span style={{ color: "rgba(245,158,11,0.4)", fontSize: 9 }}>|</span>
                  <span style={{ color: "var(--th-text-primary)", fontSize: 10, fontFamily: "monospace", flex: 1 }}>{announcementBanner.text}</span>
                </div>
                <div style={{ color: "rgba(245,158,11,0.55)", fontSize: 8, fontFamily: "monospace", textAlign: "right", marginTop: 2 }}>
                  ??{announcementBanner.sender}
                </div>
              </motion.div>
            )}
            {/* Task completion burst particles */}
            {completionBursts.map((burst) => (
              <div
                key={burst.id}
                className="pointer-events-none"
                style={{ position: "absolute", left: `${burst.x}%`, top: `${burst.y}%`, zIndex: 50 }}
              >
                {/* Rays */}
                {[0, 45, 90, 135, 180, 225, 270, 315].map((deg, ri) => (
                  <div
                    key={ri}
                    style={{
                      position: "absolute",
                      width: 3,
                      height: 3,
                      borderRadius: "50%",
                      background: ri % 2 === 0 ? "var(--th-accent)" : "rgb(52,211,153)",
                      animation: "task-burst-ray 1.2s ease-out forwards",
                      animationDelay: `${ri * 30}ms`,
                      transform: `rotate(${deg}deg)`,
                      transformOrigin: "1.5px 1.5px",
                    }}
                  />
                ))}
                {/* Label */}
                <div
                  style={{
                    position: "absolute",
                    left: 8,
                    top: -10,
                    whiteSpace: "nowrap",
                    fontSize: 9,
                    fontFamily: "var(--th-font-mono)",
                    color: "var(--th-accent)",
                    background: "rgba(0,0,0,0.7)",
                    padding: "1px 4px",
                    borderRadius: 2,
                    animation: "task-burst-label 1.2s ease-out forwards",
                    letterSpacing: 0.5,
                  }}
                >
                  ??{burst.label}
                </div>
              </div>
            ))}

          </div>
        </div>

        {/* Right ??agent / dept detail (visible >= 1280px) */}
        <motion.div
          className="office-right"
          initial={{ opacity: 0, x: 16 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.18, ease: "linear", delay: 0.04 }}
        >
          <OfficeAgentPanel
            selectedAgent={selectedAgent}
            selectedDept={selectedDept}
            agents={agents}
            tasks={tasks}
            departments={departments}
            ceoIncoming={ceoIncomingCount}
            visitingAgentIds={visitingAgentIds}
            onViewAgent={onSelectAgent}
            onViewDept={onSelectDepartment}
          />
        </motion.div>

        {/* Floating agent/dept detail (visible < 1280px when selected) */}
        {(selectedAgent || selectedDept) && (
          <div className="office-right-float">
            <button
              className="office-right-float__close"
              onClick={() => { setSelectedAgent(null); setSelectedDept(null); }}
              aria-label="Close"
            >??/button>
            <OfficeAgentPanel
              selectedAgent={selectedAgent}
              selectedDept={selectedDept}
              agents={agents}
              tasks={tasks}
              departments={departments}
              ceoIncoming={ceoIncomingCount}
              visitingAgentIds={visitingAgentIds}
              onViewAgent={onSelectAgent}
              onViewDept={onSelectDepartment}
            />
          </div>
        )}
      </div>

      {/* ?? FM Event Ticker ?? */}
      <div className="office-fm-ticker" aria-label="Live event feed">
        <span className="office-fm-ticker__label">
          <span className="office-fm-ticker__dot" />
          LIVE
        </span>
        <div className="office-fm-ticker__track">
          <span className="office-fm-ticker__text">{fmTickerEvents}</span>
        </div>
      </div>

      {/* ?? Pack HUD overlay ?? */}
      <PackHud
        packKey={activeWorkflowPackKey ?? "development"}
        agents={agents}
        tasks={tasks}
      />

      {/* ?? FM-style Action bar ?? */}
      <div className="office-actionbar">
        <div className="office-actionbar-stat">
          <span className="office-actionbar-stat__lbl">{packVocab.agent.slice(0, 3).toUpperCase()}</span>
          <span className="office-actionbar-stat__val" style={{ color: "#22c55e" }}>
            {agents.filter((a) => a.status === "working").length}
          </span>
          <span className="office-actionbar-stat__total">/{agents.length}</span>
        </div>
        <div className="office-actionbar-sep" />
        <div className="office-actionbar-stat">
          <span className="office-actionbar-stat__lbl">{packVocab.task.slice(0, 3).toUpperCase()}</span>
          <span className="office-actionbar-stat__val" style={{ color: "var(--th-accent)" }}>
            {tasks.filter((t) => t.status === "in_progress").length}
          </span>
          <span className="office-actionbar-stat__total">/{tasks.length}</span>
        </div>
        <div className="office-actionbar-sep" />
        <div className="office-actionbar-stat">
          <span className="office-actionbar-stat__lbl">{packVocab.department.slice(0, 4).toUpperCase()}</span>
          <span className="office-actionbar-stat__val">{departments.length}</span>
        </div>
        <div className="office-actionbar-sep" />
        <div className="office-actionbar-stat">
          <span className="office-actionbar-stat__lbl">{packVocab.onBreak.slice(0, 5).toUpperCase()}</span>
          <span className="office-actionbar-stat__val" style={{ color: "rgba(245,158,11,0.7)" }}>
            {agents.filter((a) => a.status === "break").length}
          </span>
        </div>
        {visitorCount > 0 && (
          <>
            <div className="office-actionbar-sep" />
            <div className="office-actionbar-stat">
              <span className="office-actionbar-stat__lbl">VISIT</span>
              <span className="office-actionbar-stat__val" style={{ color: "#22c55e" }}>
                {visitorCount}
              </span>
            </div>
          </>
        )}
        <div className="office-actionbar-info" style={{ marginLeft: "auto" }}>
          <span style={{ color: agents.filter((a) => a.status === "working").length > 0 ? "#22c55e" : "var(--th-text-muted)" }}>
            {agents.filter((a) => a.status === "working").length > 0 ? packVocab.running.toUpperCase() : packVocab.idle.toUpperCase()}
          </span>
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import type { Agent, AssignmentMode, Department, Project, WorkflowPackKey } from "../types";
import {
  deleteProject,
  getProjectDetail,
  getProjects,
  getTaskReportDetail,
  type ProjectDecisionEventItem,
  type ProjectDetailResponse,
  type ProjectReportHistoryItem,
  type ProjectTaskHistoryItem,
  type TaskReportDetail,
} from "../api";
import { useI18n } from "../i18n";
import { useSpriteMap } from "./AgentAvatar";
import GitHubImportPanel from "./GitHubImportPanel";
import TaskReportPopup from "./TaskReportPopup";
import ManualAssignmentWarningDialog from "./project-manager/ManualAssignmentWarningDialog";
import ManualPathPickerDialog from "./project-manager/ManualPathPickerDialog";
import MissingPathPromptDialog from "./project-manager/MissingPathPromptDialog";
import ProjectEditorPanel from "./project-manager/ProjectEditorPanel";
import ProjectInsightsPanel from "./project-manager/ProjectInsightsPanel";
import ProjectSidebar from "./project-manager/ProjectSidebar";
import type {
  GroupedProjectTaskCard,
  ManualAssignmentWarning,
  ProjectI18nTranslate,
  ProjectManagerModalProps,
  ProjectManualSelectionStats,
} from "./project-manager/types";
import { getDecisionEventLabel as mapDecisionEventLabel } from "./project-manager/utils";
import { useProjectManagerPathTools } from "./project-manager/useProjectManagerPathTools";
import { useProjectSaveHandler } from "./project-manager/useProjectSaveHandler";

const PAGE_SIZE = 5;

export default function ProjectManagerModal({ agents, departments = [], onClose }: ProjectManagerModalProps) {
  const { t, language } = useI18n();

  const [projects, setProjects] = useState<Project[]>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [search, setSearch] = useState("");
  const [loadingList, setLoadingList] = useState(false);

  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [detail, setDetail] = useState<ProjectDetailResponse | null>(null);
  const [loadingDetail, setLoadingDetail] = useState(false);

  const [isCreating, setIsCreating] = useState(false);
  const [githubImportMode, setGithubImportMode] = useState(false);
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [projectPath, setProjectPath] = useState("");
  const [coreGoal, setCoreGoal] = useState("");
  const [saving, setSaving] = useState(false);
  const [reportDetail, setReportDetail] = useState<TaskReportDetail | null>(null);

  const [defaultPackKey, setDefaultPackKey] = useState<WorkflowPackKey>("development");
  const [assignmentMode, setAssignmentMode] = useState<AssignmentMode>("auto");
  const [selectedAgentIds, setSelectedAgentIds] = useState<Set<string>>(new Set());
  const [agentFilterDept, setAgentFilterDept] = useState<string>("all");
  const [manualAssignmentWarning, setManualAssignmentWarning] = useState<ManualAssignmentWarning | null>(null);

  const spriteMap = useSpriteMap(agents);

  /** 吏곸썝 ?좏깮 紐⑸줉: ?좏깮??湲곕낯 ?뚰겕?뚮줈?????ㅽ뵾?ㅽ뙥)???뚯냽???먯씠?꾪듃留??쒖떆 */
  const agentsInCurrentPack = useMemo(() => {
    if (defaultPackKey === "development") {
      return agents.filter((a) => !a.workflow_pack_key || a.workflow_pack_key === "development");
    }
    return agents.filter((a) => a.workflow_pack_key === defaultPackKey);
  }, [agents, defaultPackKey]);

  /** ?대떦 ?⑹뿉 吏곸썝????紐낆씠?쇰룄 ?덈뒗 遺?쒕쭔 吏곸썝 ?꾪꽣 ?쒕∼?ㅼ슫???쒖떆 */
  const departmentsInCurrentPack = useMemo(() => {
    const deptIds = new Set(agentsInCurrentPack.map((a) => a.department_id).filter(Boolean));
    return departments.filter((d) => deptIds.has(d.id));
  }, [departments, agentsInCurrentPack]);

  const viewedProject = detail?.project ?? null;
  const selectedProject = isCreating ? null : viewedProject;
  const canSave = !!name.trim() && !!projectPath.trim() && !!coreGoal.trim();
  const pathToolsVisible = isCreating || !!editingProjectId;

  const pathTools = useProjectManagerPathTools({
    t: t as ProjectI18nTranslate,
    projectPath,
    pathToolsVisible,
  });

  const loadProjects = useCallback(
    async (targetPage: number, keyword: string) => {
      setLoadingList(true);
      try {
        const res = await getProjects({
          page: targetPage,
          page_size: PAGE_SIZE,
          search: keyword.trim() || undefined,
        });
        setProjects(res.projects);
        setPage(res.page);
        setTotalPages(Math.max(1, res.total_pages || 1));
        if (res.projects.length === 0) {
          setIsCreating(true);
        }
        if (!selectedProjectId && res.projects[0]) {
          setSelectedProjectId(res.projects[0].id);
        }
      } catch (err) {
        console.error("Failed to load projects:", err);
      } finally {
        setLoadingList(false);
      }
    },
    [selectedProjectId],
  );

  useEffect(() => {
    void loadProjects(1, search);
  }, []);

  useEffect(() => {
    if (!selectedProjectId) {
      setDetail(null);
      return;
    }
    setLoadingDetail(true);
    getProjectDetail(selectedProjectId)
      .then((res) => {
        setDetail(res);
        if (!editingProjectId && !isCreating) {
          setName(res.project.name);
          setProjectPath(res.project.project_path);
          setCoreGoal(res.project.core_goal);
          setAssignmentMode(res.project.assignment_mode || "auto");
          setDefaultPackKey(res.project.default_pack_key || "development");
          setSelectedAgentIds(new Set(res.project.assigned_agent_ids || []));
        }
      })
      .catch((err) => {
        console.error("Failed to load project detail:", err);
      })
      .finally(() => setLoadingDetail(false));
  }, [selectedProjectId, editingProjectId, isCreating]);

  const getManualAssignmentWarning = useCallback((): ManualAssignmentWarning["reason"] | null => {
    const selectedAgents = agents.filter((agent) => selectedAgentIds.has(agent.id));
    if (selectedAgents.length === 0) return "no_agents";
    const hasSubordinate = selectedAgents.some((agent) => agent.role !== "team_leader");
    return hasSubordinate ? null : "leaders_only";
  }, [agents, selectedAgentIds]);

  const manualSelectionStats = useMemo<ProjectManualSelectionStats>(() => {
    const selected = agents.filter((agent) => selectedAgentIds.has(agent.id));
    const leaders = selected.filter((agent) => agent.role === "team_leader").length;
    const subordinates = selected.length - leaders;
    return {
      total: selected.length,
      leaders,
      subordinates,
    };
  }, [agents, selectedAgentIds]);

  const groupedTaskCards = useMemo<GroupedProjectTaskCard[]>(() => {
    if (!detail) return [];
    const rows = [...detail.tasks].sort((a, b) => (b.created_at || 0) - (a.created_at || 0));
    const byId = new Map<string, ProjectTaskHistoryItem>(rows.map((row) => [row.id, row]));
    const groups = new Map<string, GroupedProjectTaskCard>();

    for (const row of rows) {
      const parentId =
        typeof row.source_task_id === "string" && row.source_task_id.trim() ? row.source_task_id.trim() : null;
      const root = parentId ? (byId.get(parentId) ?? row) : row;
      const rootId = root.id;
      const existing = groups.get(rootId);
      const group = existing ?? {
        root,
        children: [],
        latestAt: root.created_at || 0,
      };

      if (row.id === rootId) {
        group.root = row;
      } else {
        group.children.push(row);
      }
      group.latestAt = Math.max(group.latestAt, row.created_at || 0);
      groups.set(rootId, group);
    }

    return [...groups.values()]
      .map((group) => ({
        ...group,
        children: [...group.children].sort((a, b) => (b.created_at || 0) - (a.created_at || 0)),
      }))
      .sort((a, b) => b.latestAt - a.latestAt);
  }, [detail]);

  const sortedReports = useMemo<ProjectReportHistoryItem[]>(() => {
    if (!detail) return [];
    return [...detail.reports].sort(
      (a, b) => (b.completed_at || b.created_at || 0) - (a.completed_at || a.created_at || 0),
    );
  }, [detail]);

  const sortedDecisionEvents = useMemo<ProjectDecisionEventItem[]>(() => {
    if (!detail) return [];
    return [...detail.decision_events].sort((a, b) => (b.created_at || 0) - (a.created_at || 0));
  }, [detail]);

  const getDecisionEventLabel = useCallback(
    (eventType: ProjectDecisionEventItem["event_type"]) => mapDecisionEventLabel(eventType, t as ProjectI18nTranslate),
    [t],
  );

  const startCreate = useCallback(() => {
    setIsCreating(true);
    setEditingProjectId(null);
    setName("");
    setProjectPath("");
    setCoreGoal("");
    setDefaultPackKey("development");
    setAssignmentMode("auto");
    setSelectedAgentIds(new Set());
    setManualAssignmentWarning(null);
    pathTools.resetPathHelperState();
  }, [pathTools]);

  const startEditSelected = useCallback(() => {
    if (!viewedProject) return;
    setIsCreating(false);
    setEditingProjectId(viewedProject.id);
    setName(viewedProject.name);
    setProjectPath(viewedProject.project_path);
    setCoreGoal(viewedProject.core_goal);
    setDefaultPackKey(viewedProject.default_pack_key || "development");
    setAssignmentMode(viewedProject.assignment_mode || "auto");
    setSelectedAgentIds(new Set(viewedProject.assigned_agent_ids || []));
    setManualAssignmentWarning(null);
    pathTools.resetPathHelperState();
  }, [pathTools, viewedProject]);

  const handleSave = useProjectSaveHandler({
    canSave,
    saving,
    setSaving,
    assignmentMode,
    defaultPackKey,
    getManualAssignmentWarning,
    setManualAssignmentWarning,
    projectPath,
    setProjectPath,
    pathTools,
    editingProjectId,
    name,
    coreGoal,
    selectedAgentIds,
    loadProjects,
    search,
    setSelectedProjectId,
    setEditingProjectId,
    setIsCreating,
    t: t as ProjectI18nTranslate,
  });

  const handleDelete = useCallback(async () => {
    if (!selectedProject) return;
    const confirmed = window.confirm(
      t({
        ko: `?꾨줈?앺듃 '${selectedProject.name}' ??瑜? ??젣?좉퉴??`,
        en: `Delete project '${selectedProject.name}'?`,
        ja: `?쀣꺆?멥궒??깉 '${selectedProject.name}' ?믣뎷?ㅳ걮?얇걲?뗰폕`,
        zh: `誤곩닠?ㅹ」??'${selectedProject.name}' ?쀯폕`,
      }),
    );
    if (!confirmed) return;

    try {
      await deleteProject(selectedProject.id);
      setSelectedProjectId(null);
      setDetail(null);
      await loadProjects(1, search);
      startCreate();
    } catch (err) {
      console.error("Failed to delete project:", err);
    }
  }, [loadProjects, search, selectedProject, startCreate, t]);

  const handleOpenTaskDetail = useCallback(async (taskId: string) => {
    try {
      const d = await getTaskReportDetail(taskId);
      setReportDetail(d);
    } catch (err) {
      console.error("Failed to open task detail:", err);
    }
  }, []);

  const headerTitle = t({ ko: "?꾨줈?앺듃 愿由?

Project Management", ja: "?쀣꺆?멥궒??깉嶸←릤", zh: "窈밭쎅嶸←릤" });
  const formTitle = editingProjectId
    ? t({ ko: "?꾨줈?앺듃 ?섏젙", en: "Edit Project", ja: "?쀣꺆?멥궒??깉渶③썓", zh: "煐뽬풌窈밭쎅" })
    : isCreating
      ? t({ ko: "?좉퇋 ?꾨줈?앺듃 ?깅줉", en: "Register New Project", ja: "?계쫸?쀣꺆?멥궒??깉?삯뙯", zh: "?겼뻠窈밭쎅" })
      : t({ ko: "?꾨줈?앺듃 ?뺣낫", en: "Project Info", ja: "?쀣꺆?멥궒??깉?끻젿", zh: "窈밭쎅岳→겘" });

  if (reportDetail) {
    return (
      <TaskReportPopup
        report={reportDetail}
        agents={agents}
        departments={departments}
        uiLanguage={language}
        onClose={() => setReportDetail(null)}
      />
    );
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60"
      onClick={(e) => e.target === e.currentTarget && onClose()}
    >
      <div className="flex h-[86vh] w-[min(1180px,95vw)] flex-col overflow-hidden md:flex-row" style={{ border: "1px solid var(--th-border)", borderRadius: "4px", background: "var(--th-bg-surface)" }}>
        <div
          className={`w-full md:w-[330px] ${selectedProjectId || isCreating || githubImportMode ? "hidden md:block" : "block"}`}
        >
          <ProjectSidebar
            headerTitle={headerTitle}
            t={t as ProjectI18nTranslate}
            onClose={onClose}
            search={search}
            setSearch={setSearch}
            loadProjects={loadProjects}
            startCreate={startCreate}
            onOpenGitHubImport={() => {
              setGithubImportMode(true);
              setIsCreating(false);
              setEditingProjectId(null);
            }}
            loadingList={loadingList}
            projects={projects}
            selectedProjectId={selectedProjectId}
            onSelectProject={(projectId) => {
              setSelectedProjectId(projectId);
              setIsCreating(false);
              setEditingProjectId(null);
            }}
            page={page}
            totalPages={totalPages}
          />
        </div>

        <section
          className={`flex min-w-0 flex-1 flex-col overflow-hidden ${!selectedProjectId && !isCreating && !githubImportMode ? "hidden md:flex" : "flex"}`}
        >
          <div className="flex items-center gap-2 px-3 py-2 md:hidden" style={{ borderBottom: "1px solid var(--th-border)" }}>
            <button
              type="button"
              onClick={() => {
                setSelectedProjectId(null);
                setIsCreating(false);
                setEditingProjectId(null);
                setGithubImportMode(false);
              }}
              className="px-2 py-1 text-xs font-mono transition"
              style={{ borderRadius: "2px", color: "var(--th-text-secondary)", background: "transparent" }}
            >
              ??{t({ ko: "紐⑸줉", en: "List", ja: "訝誤?

?쀨〃" })}
            </button>
          </div>

          {githubImportMode ? (
            <GitHubImportPanel
              onComplete={(result) => {
                setGithubImportMode(false);
                void loadProjects(1, "");
                setSelectedProjectId(result.projectId);
                setIsCreating(false);
                setEditingProjectId(null);
              }}
              onCancel={() => setGithubImportMode(false)}
            />
          ) : (
            <>
              <div className="px-5 py-3" style={{ borderBottom: "1px solid var(--th-border)", borderLeft: "3px solid var(--th-accent)" }}>
                <h3 className="text-xs font-bold uppercase tracking-widest" style={{ color: "var(--th-text-heading)", fontFamily: "var(--th-font-mono)" }}>{formTitle}</h3>
              </div>

              <div className="grid min-w-0 flex-1 grid-cols-1 gap-4 overflow-y-auto overflow-x-hidden p-5 xl:grid-cols-[minmax(0,360px)_minmax(0,1fr)]">
                <ProjectEditorPanel
                  t={t as ProjectI18nTranslate}
                  language={language}
                  isCreating={isCreating}
                  editingProjectId={editingProjectId}
                  selectedProject={selectedProject}
                  detail={detail}
                  name={name}
                  setName={setName}
                  projectPath={projectPath}
                  setProjectPath={setProjectPath}
                  coreGoal={coreGoal}
                  setCoreGoal={setCoreGoal}
                  saving={saving}
                  canSave={canSave}
                  pathToolsVisible={pathToolsVisible}
                  pathSuggestionsOpen={pathTools.pathSuggestionsOpen}
                  setPathSuggestionsOpen={pathTools.setPathSuggestionsOpen}
                  pathSuggestionsLoading={pathTools.pathSuggestionsLoading}
                  pathSuggestions={pathTools.pathSuggestions}
                  missingPathPrompt={pathTools.missingPathPrompt}
                  setMissingPathPrompt={pathTools.setMissingPathPrompt}
                  pathApiUnsupported={pathTools.pathApiUnsupported}
                  setPathApiUnsupported={pathTools.setPathApiUnsupported}
                  nativePathPicking={pathTools.nativePathPicking}
                  setNativePathPicking={pathTools.setNativePathPicking}
                  nativePickerUnsupported={pathTools.nativePickerUnsupported}
                  setNativePickerUnsupported={pathTools.setNativePickerUnsupported}
                  setManualPathPickerOpen={pathTools.setManualPathPickerOpen}
                  loadManualPathEntries={pathTools.loadManualPathEntries}
                  unsupportedPathApiMessage={pathTools.unsupportedPathApiMessage}
                  resolvePathHelperErrorMessage={pathTools.resolvePathHelperErrorMessage}
                  formFeedback={pathTools.formFeedback}
                  setFormFeedback={pathTools.setFormFeedback}
                  defaultPackKey={defaultPackKey}
                  setDefaultPackKey={setDefaultPackKey}
                  assignmentMode={assignmentMode}
                  setAssignmentMode={setAssignmentMode}
                  setManualAssignmentWarning={setManualAssignmentWarning}
                  manualSelectionStats={manualSelectionStats}
                  selectedAgentIds={selectedAgentIds}
                  setSelectedAgentIds={setSelectedAgentIds}
                  agentFilterDept={agentFilterDept}
                  setAgentFilterDept={setAgentFilterDept}
                  agents={agentsInCurrentPack}
                  departments={departmentsInCurrentPack}
                  spriteMap={spriteMap}
                  onSave={() => {
                    void handleSave();
                  }}
                  onCancelEdit={() => {
                    setIsCreating(false);
                    setEditingProjectId(null);
                    pathTools.resetPathHelperState();
                    if (viewedProject) {
                      setName(viewedProject.name);
                      setProjectPath(viewedProject.project_path);
                      setCoreGoal(viewedProject.core_goal);
                      setDefaultPackKey(viewedProject.default_pack_key || "development");
                    }
                  }}
                  onStartEditSelected={startEditSelected}
                  onDelete={() => {
                    void handleDelete();
                  }}
                />

                <ProjectInsightsPanel
                  t={t as ProjectI18nTranslate}
                  selectedProject={selectedProject}
                  loadingDetail={loadingDetail}
                  isCreating={isCreating}
                  groupedTaskCards={groupedTaskCards}
                  sortedReports={sortedReports}
                  sortedDecisionEvents={sortedDecisionEvents}
                  getDecisionEventLabel={getDecisionEventLabel}
                  handleOpenTaskDetail={handleOpenTaskDetail}
                />
              </div>
            </>
          )}
        </section>
      </div>

      <ManualAssignmentWarningDialog
        warning={manualAssignmentWarning}
        stats={manualSelectionStats}
        t={t as ProjectI18nTranslate}
        onCancel={() => setManualAssignmentWarning(null)}
        onConfirm={(warning) => {
          setManualAssignmentWarning(null);
          void handleSave(warning.allowCreateMissingPath, true);
        }}
      />

      <MissingPathPromptDialog
        prompt={pathTools.missingPathPrompt}
        t={t as ProjectI18nTranslate}
        saving={saving}
        onCancel={() => pathTools.setMissingPathPrompt(null)}
        onConfirmCreate={() => {
          pathTools.setMissingPathPrompt(null);
          void handleSave(true);
        }}
      />

      <ManualPathPickerDialog
        open={pathTools.manualPathPickerOpen}
        t={t as ProjectI18nTranslate}
        manualPathCurrent={pathTools.manualPathCurrent}
        manualPathParent={pathTools.manualPathParent}
        manualPathEntries={pathTools.manualPathEntries}
        manualPathLoading={pathTools.manualPathLoading}
        manualPathError={pathTools.manualPathError}
        manualPathTruncated={pathTools.manualPathTruncated}
        onClose={() => pathTools.setManualPathPickerOpen(false)}
        onLoadEntries={pathTools.loadManualPathEntries}
        onSelectCurrent={() => {
          if (!pathTools.manualPathCurrent) return;
          setProjectPath(pathTools.manualPathCurrent);
          pathTools.setMissingPathPrompt(null);
          pathTools.setPathSuggestionsOpen(false);
          pathTools.setFormFeedback(null);
          pathTools.setManualPathPickerOpen(false);
        }}
      />
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  getAvailableLearnedSkills,
  getSkillLearningHistory,
  unlearnSkill,
  type LearnedSkillEntry,
  type SkillHistoryProvider,
  type SkillLearningHistoryEntry,
} from "../api";
import { type Agent } from "../types";
import AgentAvatar from "./AgentAvatar";
import {
  HISTORY_PREVIEW_COUNT,
  PROVIDER_ORDER,
  learningRowKey,
  normalizeSkillLabel,
  pickRepresentativeForProvider,
  providerLabel,
  relativeTime,
  statusClass,
  statusLabel,
} from "./skill-history/utils";

type UnlearnEffect = "pot" | "hammer";

interface SkillHistoryPanelProps {
  agents: Agent[];
  refreshToken?: number;
  className?: string;
  onLearningDataChanged?: () => void;
}

export default function SkillHistoryPanel({
  agents,
  refreshToken = 0,
  className = "",
  onLearningDataChanged,
}: SkillHistoryPanelProps) {
  const [tab, setTab] = useState<"history" | "available">("history");
  const [providerFilter, setProviderFilter] = useState<"all" | SkillHistoryProvider>("all");
  const [historyRows, setHistoryRows] = useState<SkillLearningHistoryEntry[]>([]);
  const [availableRows, setAvailableRows] = useState<LearnedSkillEntry[]>([]);
  const [retentionDays, setRetentionDays] = useState<number>(180);
  const [historyExpanded, setHistoryExpanded] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [unlearnError, setUnlearnError] = useState<string | null>(null);
  const [unlearningKeys, setUnlearningKeys] = useState<string[]>([]);
  const [unlearnEffects, setUnlearnEffects] = useState<Partial<Record<string, UnlearnEffect>>>({});
  const [centerBonk, setCenterBonk] = useState<{
    provider: SkillHistoryProvider;
    agent: Agent | null;
  } | null>(null);
  const unlearnEffectTimersRef = useRef<Partial<Record<string, number>>>({});
  const centerBonkTimerRef = useRef<number | null>(null);

  const representatives = useMemo(() => {
    const out = new Map<SkillHistoryProvider, Agent | null>();
    for (const provider of PROVIDER_ORDER) {
      out.set(provider, pickRepresentativeForProvider(agents, provider));
    }
    return out;
  }, [agents]);

  const activeProviders = useMemo(() => {
    const fromRows = new Set<SkillHistoryProvider>();
    for (const row of historyRows) fromRows.add(row.provider);
    for (const row of availableRows) fromRows.add(row.provider);
    for (const provider of PROVIDER_ORDER) {
      if (representatives.get(provider)) {
        fromRows.add(provider);
      }
    }
    return PROVIDER_ORDER.filter((provider) => fromRows.has(provider));
  }, [availableRows, historyRows, representatives]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const provider = providerFilter === "all" ? undefined : providerFilter;
      const [historyData, availableData] = await Promise.all([
        getSkillLearningHistory({ provider, limit: 80 }),
        getAvailableLearnedSkills({ provider, limit: 30 }),
      ]);
      setHistoryRows(historyData.history);
      setAvailableRows(availableData);
      if (historyData.retentionDays > 0) {
        setRetentionDays(historyData.retentionDays);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }, [providerFilter]);

  useEffect(() => {
    void load();
  }, [load, refreshToken]);

  useEffect(() => {
    const timer = window.setInterval(() => {
      void load();
    }, 20_000);
    return () => window.clearInterval(timer);
  }, [load]);

  useEffect(() => {
    setHistoryExpanded(false);
  }, [providerFilter, tab]);

  useEffect(() => {
    return () => {
      for (const timerId of Object.values(unlearnEffectTimersRef.current)) {
        if (typeof timerId === "number") {
          window.clearTimeout(timerId);
        }
      }
      if (typeof centerBonkTimerRef.current === "number") {
        window.clearTimeout(centerBonkTimerRef.current);
      }
    };
  }, []);

  function triggerUnlearnEffect(rowKey: string, provider: SkillHistoryProvider) {
    const effect: UnlearnEffect = Math.random() < 0.5 ? "pot" : "hammer";
    setUnlearnEffects((prev) => ({ ...prev, [rowKey]: effect }));
    setCenterBonk({
      provider,
      agent: representatives.get(provider) ?? null,
    });
    if (typeof centerBonkTimerRef.current === "number") {
      window.clearTimeout(centerBonkTimerRef.current);
    }
    centerBonkTimerRef.current = window.setTimeout(() => {
      setCenterBonk(null);
      centerBonkTimerRef.current = null;
    }, 950);
    const existingTimer = unlearnEffectTimersRef.current[rowKey];
    if (typeof existingTimer === "number") {
      window.clearTimeout(existingTimer);
    }
    unlearnEffectTimersRef.current[rowKey] = window.setTimeout(() => {
      setUnlearnEffects((prev) => {
        const next = { ...prev };
        delete next[rowKey];
        return next;
      });
      delete unlearnEffectTimersRef.current[rowKey];
    }, 1100);
  }

  async function handleUnlearn(row: { provider: SkillHistoryProvider; repo: string; skill_id: string }) {
    const rowKey = learningRowKey(row);
    if (unlearningKeys.includes(rowKey)) return;
    setUnlearnError(null);
    setUnlearningKeys((prev) => [...prev, rowKey]);
    try {
      const result = await unlearnSkill({
        provider: row.provider,
        repo: row.repo,
        skillId: row.skill_id,
