import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  getAvailableLearnedHooks,
  getHookLearningHistory,
  unlearnHook,
  type LearnedHookEntry,
  type HookHistoryProvider,
  type HookLearningHistoryEntry,
} from "../../api/hooks";
import type { Agent } from "../../types";
import AgentAvatar from "../AgentAvatar";
import {
  HOOK_LEARNED_PROVIDER_ORDER,
  hookProviderLabel,
  hookStatusLabel,
  hookStatusClass,
  hookRelativeTime,
  hookLearningRowKey,
  pickRepresentativeForProvider,
  type TFunction,
  type UnlearnEffect,
} from "./model";

const HISTORY_PREVIEW_COUNT = 3;

interface HookHistoryPanelProps {
  t: TFunction;
  agents: Agent[];
  refreshToken?: number;
  className?: string;
  onLearningDataChanged?: () => void;
}

export default function HookHistoryPanel({
  t,
  agents,
  refreshToken = 0,
  className = "",
  onLearningDataChanged,
}: HookHistoryPanelProps) {
  const [tab, setTab] = useState<"history" | "available">("history");
  const [providerFilter, setProviderFilter] = useState<"all" | HookHistoryProvider>("all");
  const [historyRows, setHistoryRows] = useState<HookLearningHistoryEntry[]>([]);
  const [availableRows, setAvailableRows] = useState<LearnedHookEntry[]>([]);
  const [historyExpanded, setHistoryExpanded] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [unlearnError, setUnlearnError] = useState<string | null>(null);
  const [unlearningKeys, setUnlearningKeys] = useState<string[]>([]);
  const [unlearnEffects, setUnlearnEffects] = useState<Partial<Record<string, UnlearnEffect>>>({});
  const [centerBonk, setCenterBonk] = useState<{
    provider: HookHistoryProvider;
    agent: Agent | null;
  } | null>(null);
  const unlearnEffectTimersRef = useRef<Partial<Record<string, number>>>({});
  const centerBonkTimerRef = useRef<number | null>(null);

  const representatives = useMemo(() => {
    const out = new Map<HookHistoryProvider, Agent | null>();
    for (const provider of HOOK_LEARNED_PROVIDER_ORDER) {
      out.set(provider, pickRepresentativeForProvider(agents, provider));
    }
    return out;
  }, [agents]);

  const activeProviders = useMemo(() => {
    const fromRows = new Set<HookHistoryProvider>();
    for (const row of historyRows) fromRows.add(row.provider);
    for (const row of availableRows) fromRows.add(row.provider);
    for (const provider of HOOK_LEARNED_PROVIDER_ORDER) {
      if (representatives.get(provider)) {
        fromRows.add(provider);
      }
    }
    return HOOK_LEARNED_PROVIDER_ORDER.filter((provider) => fromRows.has(provider));
  }, [availableRows, historyRows, representatives]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const provider = providerFilter === "all" ? undefined : providerFilter;
      const [historyData, availableData] = await Promise.all([
        getHookLearningHistory({ provider, limit: 80 }).catch((err) => {
          const msg = err instanceof Error ? err.message : String(err);
          if (/not_found|404/.test(msg)) return { history: [] as HookLearningHistoryEntry[], retentionDays: 180 };
          throw err;
        }),
        getAvailableLearnedHooks({ provider, limit: 30 }).catch((err) => {
          const msg = err instanceof Error ? err.message : String(err);
          if (/not_found|404/.test(msg)) return [] as LearnedHookEntry[];
          throw err;
        }),
      ]);
      setHistoryRows(historyData.history);
      setAvailableRows(availableData);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }, [providerFilter]);

  useEffect(() => {
    void load();
  }, [load, refreshToken]);

  useEffect(() => {
    setHistoryExpanded(false);
  }, [providerFilter, tab]);

  useEffect(() => {
    return () => {
      for (const timerId of Object.values(unlearnEffectTimersRef.current)) {
        if (typeof timerId === "number") window.clearTimeout(timerId);
      }
      if (typeof centerBonkTimerRef.current === "number") {
        window.clearTimeout(centerBonkTimerRef.current);
      }
    };
  }, []);

  function triggerUnlearnEffect(rowKey: string, provider: HookHistoryProvider) {
    const effect: UnlearnEffect = Math.random() < 0.5 ? "pot" : "hammer";
    setUnlearnEffects((prev) => ({ ...prev, [rowKey]: effect }));
    setCenterBonk({
      provider,
      agent: representatives.get(provider) ?? null,
    });
    if (typeof centerBonkTimerRef.current === "number") {
      window.clearTimeout(centerBonkTimerRef.current);
    }
    centerBonkTimerRef.current = window.setTimeout(() => {
      setCenterBonk(null);
      centerBonkTimerRef.current = null;
    }, 950);
    const existingTimer = unlearnEffectTimersRef.current[rowKey];
    if (typeof existingTimer === "number") {
      window.clearTimeout(existingTimer);
    }
    unlearnEffectTimersRef.current[rowKey] = window.setTimeout(() => {
      setUnlearnEffects((prev) => {
        const next = { ...prev };
        delete next[rowKey];
        return next;
      });
      delete unlearnEffectTimersRef.current[rowKey];
    }, 1100);
  }

  async function handleUnlearn(row: { provider: HookHistoryProvider; hook_id: string }) {
    const rowKey = hookLearningRowKey(row);
    if (unlearningKeys.includes(rowKey)) return;
    setUnlearnError(null);
    setUnlearningKeys((prev) => [...prev, rowKey]);
    try {
      const result = await unlearnHook({
        provider: row.provider,
        hookId: row.hook_id,
      });
      if (result.removed > 0) {
        setAvailableRows((prev) => prev.filter((item) => hookLearningRowKey(item) !== rowKey));
        setHistoryRows((prev) =>
          prev.filter(
            (item) =>
              !(item.provider === row.provider && item.hook_id === row.hook_id && item.status === "succeeded"),
          ),
        );
        triggerUnlearnEffect(rowKey, row.provider);
      }
      onLearningDataChanged?.();
      void load();
    } catch (e) {
      setUnlearnError(e instanceof Error ? e.message : String(e));
    } finally {
      setUnlearningKeys((prev) => prev.filter((key) => key !== rowKey));
    }
  }

  const visibleHistoryRows = useMemo(() => {
    if (historyExpanded) return historyRows;
    return historyRows.slice(0, HISTORY_PREVIEW_COUNT);
  }, [historyExpanded, historyRows]);

  const hiddenHistoryCount = Math.max(0, historyRows.length - HISTORY_PREVIEW_COUNT);

  return (
    <div
      className={`skill-history-panel flex h-full min-h-[360px] flex-col ${className}`}
      style={{ borderRadius: "4px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)" }}
    >
      <div className="flex items-center justify-between gap-2 px-3 py-2.5" style={{ borderBottom: "1px solid var(--th-border)" }}>
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => setTab("history")}
            className="px-2 py-1 text-[11px] font-mono transition-all"
            style={{
              borderRadius: "2px",
              border: `1px solid ${tab === "history" ? "var(--th-border-strong)" : "transparent"}`,
              background: tab === "history" ? "var(--th-bg-surface)" : "transparent",
              color: tab === "history" ? "var(--th-text-primary)" : "var(--th-text-muted)",
            }}
          >
            {t({ ko: "\uD559\uC2B5 \uC774\uB825", en: "Learning History", ja: "\u5B66\u7FD2\u5C65\u6B74", zh: "\u5B66\u4E60\u8BB0\u5F55" })}
          </button>
          <button
            type="button"
            onClick={() => setTab("available")}
            className="px-2 py-1 text-[11px] font-mono transition-all"
            style={{
              borderRadius: "2px",
              border: `1px solid ${tab === "available" ? "var(--th-border-strong)" : "transparent"}`,
              background: tab === "available" ? "var(--th-bg-surface)" : "transparent",
              color: tab === "available" ? "var(--th-text-primary)" : "var(--th-text-muted)",
            }}
          >
            {t({ ko: "\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uD6C5", en: "Available Hooks", ja: "\u5229\u7528\u53EF\u80FD\u306A\u30D5\u30C3\u30AF", zh: "\u53EF\u7528\u94A9\u5B50" })}
          </button>
        </div>
        <button
          type="button"
          onClick={() => void load()}
          className="px-2 py-1 text-[11px] font-mono transition-all"
          style={{ borderRadius: "2px", border: "1px solid var(--th-border)", color: "var(--th-text-secondary)", background: "transparent" }}
        >
          {t({ ko: "\uC0C8\uB85C\uACE0\uCE68", en: "Refresh", ja: "\u66F4\u65B0", zh: "\u5237\u65B0" })}
        </button>
      </div>

      <div className="flex items-center gap-1 overflow-x-auto px-3 py-2">
        <button
          type="button"
          onClick={() => setProviderFilter("all")}
          className="px-2 py-1 text-[10px] font-mono transition-all"
          style={{
            borderRadius: "2px",
            border: `1px solid ${providerFilter === "all" ? "rgba(251,191,36,0.5)" : "var(--th-border)"}`,
            background: providerFilter === "all" ? "rgba(251,191,36,0.1)" : "transparent",
            color: providerFilter === "all" ? "var(--th-accent)" : "var(--th-text-muted)",
          }}
        >
          All
        </button>
        {activeProviders.map((provider) => (
          <button
            key={provider}
            type="button"
            onClick={() => setProviderFilter(provider)}
            className="px-2 py-1 text-[10px] font-mono transition-all"
            style={{
              borderRadius: "2px",
              border: `1px solid ${providerFilter === provider ? "rgba(251,191,36,0.5)" : "var(--th-border)"}`,
              background: providerFilter === provider ? "rgba(251,191,36,0.1)" : "transparent",
              color: providerFilter === provider ? "var(--th-accent)" : "var(--th-text-muted)",
            }}
          >
            {hookProviderLabel(provider)}
          </button>
        ))}
      </div>

      <div className="min-h-0 flex-1 space-y-2 overflow-y-auto px-3 pb-3">
        {loading && historyRows.length === 0 && availableRows.length === 0 && (
          <div className="px-3 py-6 text-center text-xs font-mono" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)", color: "var(--th-text-muted)" }}>
            {t({ ko: "\uBA54\uBAA8\uB9AC \uAE30\uB85D \uB85C\uB529\uC911...", en: "Loading memory records...", ja: "\u30E1\u30E2\u30EA\u8A18\u9332\u3092\u8AAD\u307F\u8FBC\u307F\u4E2D...", zh: "\u6B63\u5728\u52A0\u8F7D\u8BB0\u5FC6\u8BB0\u5F55..." })}
          </div>
        )}

        {error && (
          <div className="px-3 py-2 text-[11px] text-rose-200" style={{ borderRadius: "2px", border: "1px solid rgba(244,63,94,0.3)", background: "rgba(244,63,94,0.1)" }}>
            {error}
          </div>
        )}
        {unlearnError && (
          <div className="px-3 py-2 text-[11px] text-rose-200" style={{ borderRadius: "2px", border: "1px solid rgba(244,63,94,0.3)", background: "rgba(244,63,94,0.1)" }}>
            {unlearnError}
          </div>
        )}

        {tab === "history" && historyRows.length === 0 && !loading && !error && (
          <div className="px-3 py-6 text-center text-xs font-mono" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)", color: "var(--th-text-muted)" }}>
            {t({ ko: "\uD559\uC2B5 \uC774\uB825\uC774 \uC5C6\uC2B5\uB2C8\uB2E4", en: "No learning history yet.", ja: "\u5B66\u7FD2\u5C65\u6B74\u304C\u3042\u308A\u307E\u305B\u3093", zh: "\u6682\u65E0\u5B66\u4E60\u8BB0\u5F55" })}
          </div>
        )}

        {tab === "history" &&
          visibleHistoryRows.map((row) => {
            const agent = representatives.get(row.provider) ?? null;
            const label = row.hook_label || row.hook_id;
            const eventAt = row.run_completed_at ?? row.updated_at ?? row.created_at;
            const rowKey = hookLearningRowKey(row);
            const isUnlearning = unlearningKeys.includes(rowKey);
            const unlearnEffect = unlearnEffects[rowKey];
            const canUnlearn = row.status === "succeeded";
            return (
              <div
                key={row.id}
                className="skill-history-card p-2.5"
                style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-surface)" }}
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <div className="truncate text-xs font-semibold font-mono" style={{ color: "var(--th-text-heading)" }}>{label}</div>
                    <div className="mt-0.5 truncate text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>{row.hook_id}</div>
                  </div>
                  <span className={`px-1.5 py-0.5 text-[10px] font-mono ${hookStatusClass(row.status)}`} style={{ borderRadius: "2px" }}>
                    {hookStatusLabel(row.status)}
                  </span>
                </div>
                <div className="skill-history-meta mt-2 flex items-center justify-between gap-2 text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>
                  <div className="flex min-w-0 items-center gap-2">
                    <div
                      className={`relative h-5 w-5 overflow-hidden ${unlearnEffect ? "unlearn-avatar-hit" : ""}`}
                      style={{ borderRadius: "2px", background: "var(--th-bg-primary)" }}
                    >
                      <AgentAvatar agent={agent ?? undefined} agents={agents} size={20} rounded="xl" />
                      {unlearnEffect === "pot" && <span className="unlearn-pot-drop-sm">?ご</span>}
                      {unlearnEffect === "hammer" && <span className="unlearn-hammer-swing-sm">?뵪</span>}
                      {unlearnEffect && <span className="unlearn-hit-text-sm">Bonk!</span>}
                    </div>
                    <span className="truncate">
                      {hookProviderLabel(row.provider)}
                      {agent ? ` 쨌 ${agent.name}` : ""}
                    </span>
                  </div>
                  <div className="flex shrink-0 items-center gap-2">
                    {canUnlearn && (
                      <button
                        type="button"
                        onClick={() => void handleUnlearn(row)}
                        disabled={isUnlearning}
                        className={`skill-unlearn-btn px-1.5 py-0.5 text-[10px] font-mono transition-all ${isUnlearning ? "cursor-not-allowed" : ""}`}
                        style={{
                          borderRadius: "2px",
                          border: `1px solid ${isUnlearning ? "rgba(51,65,85,1)" : "rgba(244,63,94,0.35)"}`,
                          color: isUnlearning ? "var(--th-text-muted)" : "rgb(253,164,175)",
                          background: isUnlearning ? "transparent" : "rgba(244,63,94,0.1)",
                        }}
                      >
                        {isUnlearning
                          ? t({ ko: "\uCDE8\uC18C\uC911...", en: "Unlearning...", ja: "\u53D6\u6D88\u4E2D...", zh: "\u53D6\u6D88\u4E2D..." })
                          : t({ ko: "\uD559\uC2B5 \uCDE8\uC18C", en: "Unlearn", ja: "\u5B66\u7FD2\u53D6\u6D88", zh: "\u53D6\u6D88\u5B66\u4E60" })}
                      </button>
                    )}
                    <span className="skill-history-time" style={{ color: "var(--th-text-muted)" }}>{hookRelativeTime(eventAt)}</span>
                  </div>
                </div>
                {row.error && <div className="mt-1 break-words text-[10px] text-rose-300">{row.error}</div>}
              </div>
            );
          })}

        {tab === "history" && hiddenHistoryCount > 0 && (
          <div className="flex justify-center pt-1">
            <button
              type="button"
              onClick={() => setHistoryExpanded((prev) => !prev)}
              className="px-2.5 py-1 text-[11px] font-mono transition-all"
              style={{ borderRadius: "2px", border: "1px solid var(--th-border)", color: "var(--th-text-secondary)", background: "transparent" }}
            >
              {historyExpanded
                ? t({ ko: "\uC811\uAE30", en: "Show less", ja: "\u6298\u308A\u305F\u305F\u3080", zh: "\u6536\u8D77" })
                : t({
                    ko: `${hiddenHistoryCount}\uAC1C \uB354 \uBCF4\uAE30`,
                    en: `Show ${hiddenHistoryCount} more`,
                    ja: `${hiddenHistoryCount}\u4EF6\u8868\u793A`,
                    zh: `\u663E\u793A${hiddenHistoryCount}\u66F4\u591A`,
                  })}
            </button>
          </div>
        )}

        {tab === "available" && availableRows.length === 0 && !loading && !error && (
          <div className="px-3 py-6 text-center text-xs font-mono" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)", color: "var(--th-text-muted)" }}>
            {t({ ko: "\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uD6C5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4", en: "No available hooks.", ja: "\u5229\u7528\u53EF\u80FD\u306A\u30D5\u30C3\u30AF\u304C\u3042\u308A\u307E\u305B\u3093", zh: "\u6682\u65E0\u53EF\u7528\u94A9\u5B50" })}
          </div>
        )}

        {tab === "available" &&
          availableRows.map((row) => {
            const agent = representatives.get(row.provider) ?? null;
            const label = row.hook_label || row.hook_id;
            const rowKey = hookLearningRowKey(row);
            const isUnlearning = unlearningKeys.includes(rowKey);
            const unlearnEffect = unlearnEffects[rowKey];
            return (
              <div
                key={`${row.provider}-${row.hook_id}`}
                className="skill-history-card p-2.5"
                style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-surface)" }}
              >
                <div className="truncate text-xs font-semibold font-mono" style={{ color: "var(--th-text-heading)" }}>{label}</div>
                <div className="mt-0.5 truncate text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>{row.hook_id}</div>
                <div className="skill-history-meta mt-2 flex items-center justify-between gap-2 text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>
                  <div className="flex min-w-0 items-center gap-2">
                    <div
                      className={`relative h-5 w-5 overflow-hidden ${unlearnEffect ? "unlearn-avatar-hit" : ""}`}
                      style={{ borderRadius: "2px", background: "var(--th-bg-primary)" }}
                    >
                      <AgentAvatar agent={agent ?? undefined} agents={agents} size={20} rounded="xl" />
                      {unlearnEffect === "pot" && <span className="unlearn-pot-drop-sm">?ご</span>}
                      {unlearnEffect === "hammer" && <span className="unlearn-hammer-swing-sm">?뵪</span>}
                      {unlearnEffect && <span className="unlearn-hit-text-sm">Bonk!</span>}
                    </div>
                    <span className="truncate">
                      {hookProviderLabel(row.provider)}
                      {agent ? ` 쨌 ${agent.name}` : ""}
                    </span>
                  </div>
                  <div className="flex shrink-0 items-center gap-2">
                    <button
                      type="button"
                      onClick={() => void handleUnlearn(row)}
                      disabled={isUnlearning}
                      className={`skill-unlearn-btn px-1.5 py-0.5 text-[10px] font-mono transition-all ${isUnlearning ? "cursor-not-allowed" : ""}`}
                      style={{
                        borderRadius: "2px",
                        border: `1px solid ${isUnlearning ? "rgba(51,65,85,1)" : "rgba(244,63,94,0.35)"}`,
                        color: isUnlearning ? "var(--th-text-muted)" : "rgb(253,164,175)",
                        background: isUnlearning ? "transparent" : "rgba(244,63,94,0.1)",
                      }}
                    >
                      {isUnlearning
                        ? t({ ko: "\uCDE8\uC18C\uC911...", en: "Unlearning...", ja: "\u53D6\u6D88\u4E2D...", zh: "\u53D6\u6D88\u4E2D..." })
                        : t({ ko: "\uD559\uC2B5 \uCDE8\uC18C", en: "Unlearn", ja: "\u5B66\u7FD2\u53D6\u6D88", zh: "\u53D6\u6D88\u5B66\u4E60" })}
                    </button>
                    <span className="skill-history-time" style={{ color: "var(--th-text-muted)" }}>{hookRelativeTime(row.learned_at)}</span>
                  </div>
                </div>
              </div>
            );
          })}
      </div>

      {centerBonk && (
        <div className="pointer-events-none fixed inset-0 z-[120] flex items-center justify-center">
          <div className="skill-history-center-card unlearn-center-card px-6 py-4" style={{ borderRadius: "4px", border: "1px solid rgba(251,113,133,0.3)", background: "var(--th-terminal-bg)" }}>
            <div className="relative mx-auto h-20 w-20 overflow-visible">
              <div className="unlearn-avatar-hit">
                <AgentAvatar agent={centerBonk.agent ?? undefined} agents={agents} size={80} rounded="xl" />
              </div>
              <span className="unlearn-hammer-swing-center">?뵪</span>
              <span className="unlearn-hit-text-center">Bonk!</span>
            </div>
            <div className="skill-history-center-label mt-2 text-center text-xs font-medium text-rose-100">
              {hookProviderLabel(centerBonk.provider)}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { HookEntry, HookEventType, Department, Agent } from "../../types";
import {
  getHooks,
  createHook,
  updateHook,
  toggleHook,
  deleteHook,
  startHookLearning,
  getHookLearningJob,
  getAvailableLearnedHooks,
  unlearnHook,
  type CreateHookInput,
  type UpdateHookInput,
  type HookLearnProvider,
  type HookHistoryProvider,
  type HookLearnJob,
  type LearnedHookEntry,
} from "../../api/hooks";
import type { TFunction, HookSortBy, UnlearnEffect } from "./model";
import {
  ALL_EVENT_TYPES,
  HOOK_LEARN_PROVIDER_ORDER,
  HOOK_LEARNED_PROVIDER_ORDER,
  pickRepresentativeForProvider,
} from "./model";

interface UseHooksStateOptions {
  agents: Agent[];
  departments: Department[];
  t: TFunction;
}

export function useHooksState({ agents, departments, t }: UseHooksStateOptions) {
  const [hooks, setHooks] = useState<HookEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Filters
  const [search, setSearch] = useState("");
  const [selectedEventType, setSelectedEventType] = useState<string>("All");
  const [sortBy, setSortBy] = useState<HookSortBy>("priority");

  // Modal state
  const [showFormModal, setShowFormModal] = useState(false);
  const [editingHook, setEditingHook] = useState<HookEntry | null>(null);
  const [formSubmitting, setFormSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  // Delete state
  const [deletingHookId, setDeletingHookId] = useState<string | null>(null);

  // ?? Learning state ??????????????????????????????????????????????
  const [learningHook, setLearningHook] = useState<HookEntry | null>(null);
  const [selectedProviders, setSelectedProviders] = useState<HookLearnProvider[]>([]);
  const [learnJob, setLearnJob] = useState<HookLearnJob | null>(null);
  const [learnSubmitting, setLearnSubmitting] = useState(false);
  const [learnError, setLearnError] = useState<string | null>(null);
  const [unlearnError, setUnlearnError] = useState<string | null>(null);
  const [unlearningProviders, setUnlearningProviders] = useState<HookLearnProvider[]>([]);
  const [unlearnEffects, setUnlearnEffects] = useState<Partial<Record<HookLearnProvider, UnlearnEffect>>>({});
  const [historyRefreshToken, setHistoryRefreshToken] = useState(0);
  const [learnedRows, setLearnedRows] = useState<LearnedHookEntry[]>([]);
  const [squadAgentIds, setSquadAgentIds] = useState<string[]>([]);
  const unlearnEffectTimersRef = useRef<Partial<Record<HookLearnProvider, number>>>({});

  // ?? Load hooks ????????????????????????????????????????????????????
  const loadHooks = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await getHooks();
      setHooks(data);
    } catch (err: unknown) {
      setError(String((err as Error).message ?? err));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadHooks();
  }, [loadHooks]);

  // ?? Load learned rows ?????????????????????????????????????????????
  useEffect(() => {
    let cancelled = false;
    getAvailableLearnedHooks({ limit: 500 })
      .then((rows) => {
        if (!cancelled) setLearnedRows(rows);
      })
      .catch(() => {
        if (!cancelled) setLearnedRows([]);
      });
    return () => {
      cancelled = true;
    };
  }, [historyRefreshToken]);

  // ?? Representatives ???????????????????????????????????????????????
  const representatives = useMemo(
    () =>
      HOOK_LEARN_PROVIDER_ORDER.map((provider) => ({
        provider,
        agent: pickRepresentativeForProvider(agents, provider),
      })),
    [agents],
  );

  const defaultSelectedProviders = useMemo(
    () => representatives.filter((row) => row.agent).map((row) => row.provider),
    [representatives],
  );

  const learnedRepresentatives = useMemo(() => {
    const out = new Map<HookHistoryProvider, Agent | null>();
    for (const provider of HOOK_LEARNED_PROVIDER_ORDER) {
      out.set(provider, pickRepresentativeForProvider(agents, provider));
    }
    return out;
  }, [agents]);

  // ?? Learned providers by hook ?????????????????????????????????????
  const learnedProvidersByHook = useMemo(() => {
    const map = new Map<string, HookHistoryProvider[]>();
    for (const row of learnedRows) {
      if (!map.has(row.hook_id)) map.set(row.hook_id, []);
      const providers = map.get(row.hook_id)!;
      if (!providers.includes(row.provider)) providers.push(row.provider);
    }
    return map;
  }, [learnedRows]);

  // ?? Modal learned providers (for current learningHook) ????????????
  const modalLearnedProviders = useMemo(() => {
    if (!learningHook) return new Set<HookHistoryProvider>();
    const providers = learnedProvidersByHook.get(learningHook.id) ?? [];
    return new Set<HookHistoryProvider>(providers);
  }, [learningHook, learnedProvidersByHook]);

  const preferKoreanName = true;

  // Event type counts
  const eventTypeCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const et of ALL_EVENT_TYPES) {
      counts[et] = et === "All" ? hooks.length : hooks.filter((h) => h.event_type === et).length;
    }
    return counts;
  }, [hooks]);

  // Filtered & sorted
  const filtered = useMemo(() => {
    let result = [...hooks];

    if (selectedEventType !== "All") {
      result = result.filter((h) => h.event_type === selectedEventType);
    }

    if (search.trim()) {
      const q = search.toLowerCase();
      result = result.filter(
        (h) =>
          h.title.toLowerCase().includes(q) ||
          h.title_ko.toLowerCase().includes(q) ||
          h.description.toLowerCase().includes(q) ||
          h.command.toLowerCase().includes(q) ||
          h.event_type.toLowerCase().includes(q),
      );
    }

    switch (sortBy) {
      case "priority":
        result.sort((a, b) => b.priority - a.priority || b.created_at - a.created_at);
        break;
      case "name":
        result.sort((a, b) => a.title.localeCompare(b.title));
        break;
      case "date":
        result.sort((a, b) => b.created_at - a.created_at);
        break;
      case "executions":
        result.sort((a, b) => b.execution_count - a.execution_count || b.created_at - a.created_at);
        break;
    }

    return result;
  }, [hooks, selectedEventType, search, sortBy]);

  // Handlers
  const openCreateModal = useCallback(() => {
    setEditingHook(null);
    setFormError(null);
    setShowFormModal(true);
  }, []);

  const openEditModal = useCallback((hook: HookEntry) => {
    setEditingHook(hook);
    setFormError(null);
    setShowFormModal(true);
  }, []);

  const closeFormModal = useCallback(() => {
    setShowFormModal(false);
    setEditingHook(null);
    setFormError(null);
  }, []);

  const handleCreateHook = useCallback(
    async (input: CreateHookInput) => {
      try {
        setFormSubmitting(true);
        setFormError(null);
        const created = await createHook(input);
        setHooks((prev) => [created, ...prev]);
        setShowFormModal(false);
        setEditingHook(null);
      } catch (err: unknown) {
        setFormError(String((err as Error).message ?? err));
      } finally {
        setFormSubmitting(false);
      }
    },
    [],
  );

  const handleUpdateHook = useCallback(
    async (id: string, input: UpdateHookInput) => {
      try {
        setFormSubmitting(true);
        setFormError(null);
        const updated = await updateHook(id, input);
        setHooks((prev) => prev.map((h) => (h.id === id ? updated : h)));
        setShowFormModal(false);
        setEditingHook(null);
      } catch (err: unknown) {
        setFormError(String((err as Error).message ?? err));
      } finally {
        setFormSubmitting(false);
      }
    },
    [],
  );

  const handleToggleHook = useCallback(async (id: string) => {
    try {
      const result = await toggleHook(id);
      setHooks((prev) => prev.map((h) => (h.id === id ? { ...h, enabled: result.enabled } : h)));
    } catch (err: unknown) {
      console.error("Failed to toggle hook:", err);
    }
  }, []);

  const handleDeleteHook = useCallback(async (id: string) => {
    try {
      setDeletingHookId(id);
      await deleteHook(id);
      setHooks((prev) => prev.filter((h) => h.id !== id));
    } catch (err: unknown) {
      console.error("Failed to delete hook:", err);
    } finally {
      setDeletingHookId(null);
    }
  }, []);

  // ?? Learning modal open/close ?????????????????????????????????????
  const learnInProgress = !!learnJob && (learnJob.status === "queued" || learnJob.status === "running");

  const openLearningModal = useCallback(
    (hook: HookEntry) => {
      setLearningHook(hook);
      setLearnJob(null);
      setLearnError(null);
      setUnlearnError(null);
      setLearnSubmitting(false);
      setUnlearningProviders([]);
      setUnlearnEffects({});
      // Pre-select only providers NOT yet learned
      const alreadyLearned = learnedProvidersByHook.get(hook.id) ?? [];
      const preSelected = defaultSelectedProviders.filter(
        (p) => !alreadyLearned.includes(p),
      );
      setSelectedProviders(preSelected);
      setSquadAgentIds([]);
    },
    [defaultSelectedProviders, learnedProvidersByHook],
  );

  const closeLearningModal = useCallback(() => {
    if (learnInProgress) return;
    setLearningHook(null);
    setLearnJob(null);
    setLearnError(null);
    setUnlearnError(null);
    setLearnSubmitting(false);
    setSelectedProviders([]);
    setUnlearningProviders([]);
    setUnlearnEffects({});
    setSquadAgentIds([]);
  }, [learnInProgress]);

  const toggleProvider = useCallback(
    (provider: HookLearnProvider) => {
      if (learnInProgress) return;
      setSelectedProviders((prev) =>
        prev.includes(provider) ? prev.filter((p) => p !== provider) : [...prev, provider],
      );
    },
    [learnInProgress],
  );

  // ?? Job polling ???????????????????????????????????????????????????
  useEffect(() => {
    if (!learnJob || (learnJob.status !== "queued" && learnJob.status !== "running")) return;
    const timer = window.setInterval(() => {
      getHookLearningJob(learnJob.id)
        .then(setLearnJob)
        .catch(() => {});
    }, 1500);
    return () => window.clearInterval(timer);
  }, [learnJob]);

  // Optimistic update: immediately reflect learned rows on success before server refetch
  useEffect(() => {
    if (!learnJob || learnJob.status !== "succeeded") return;
    const { hookId, hookTitle, providers, completedAt } = learnJob;
    const learnedAt = completedAt ?? Date.now();
    setLearnedRows((prev) => {
      const seen = new Set(prev.map((r) => `${r.hook_id}:${r.provider}`));
      const added: LearnedHookEntry[] = [];
      for (const provider of providers) {
        if (seen.has(`${hookId}:${provider}`)) continue;
        seen.add(`${hookId}:${provider}`);
        added.push({ provider, hook_id: hookId, hook_label: hookTitle, learned_at: learnedAt });
      }
      if (added.length === 0) return prev;
      return [...added, ...prev].sort((a, b) => b.learned_at - a.learned_at);
    });
  }, [learnJob?.id, learnJob?.status, learnJob?.hookId, learnJob?.hookTitle, learnJob?.providers, learnJob?.completedAt]);

  // Bump history on job completion (immediate + delayed to ensure server storage is reflected)
  useEffect(() => {
    if (!learnJob || (learnJob.status !== "succeeded" && learnJob.status !== "failed")) return;
    setHistoryRefreshToken((t) => t + 1);
    const id = window.setTimeout(() => {
      setHistoryRefreshToken((t) => t + 1);
    }, 1200);
    return () => window.clearTimeout(id);
  }, [learnJob?.id, learnJob?.status]);

  // ?? Start learning ????????????????????????????????????????????????
  const handleStartLearning = useCallback(async () => {
    if (!learningHook || selectedProviders.length === 0 || learnSubmitting || learnInProgress) return;
    setLearnSubmitting(true);
    setLearnError(null);
    try {
      const job = await startHookLearning({
        hookId: learningHook.id,
        providers: selectedProviders,
      });
      setLearnJob(job);
    } catch (err: unknown) {
      setLearnError(String((err as Error).message ?? err));
    } finally {
      setLearnSubmitting(false);
    }
  }, [learningHook, selectedProviders, learnSubmitting, learnInProgress]);

  // ?? Unlearn from modal ????????????????????????????????????????????
  const handleUnlearnProvider = useCallback(
    async (provider: HookLearnProvider) => {
      if (!learningHook || unlearningProviders.includes(provider)) return;
      setUnlearnError(null);
      setUnlearningProviders((prev) => [...prev, provider]);
      try {
        const result = await unlearnHook({
          provider,
          hookId: learningHook.id,
        });
        if (result.removed > 0) {
          setLearnedRows((prev) =>
            prev.filter((r) => !(r.provider === provider && r.hook_id === learningHook.id)),
          );
          // Trigger animation
          const effect: UnlearnEffect = Math.random() < 0.5 ? "pot" : "hammer";
          setUnlearnEffects((prev) => ({ ...prev, [provider]: effect }));
          const existing = unlearnEffectTimersRef.current[provider];
          if (typeof existing === "number") window.clearTimeout(existing);
          unlearnEffectTimersRef.current[provider] = window.setTimeout(() => {
            setUnlearnEffects((prev) => {
              const next = { ...prev };
              delete next[provider];
              return next;
            });
            delete unlearnEffectTimersRef.current[provider];
          }, 1100);
          setHistoryRefreshToken((t) => t + 1);
        }
      } catch (err: unknown) {
        setUnlearnError(String((err as Error).message ?? err));
      } finally {
        setUnlearningProviders((prev) => prev.filter((p) => p !== provider));
      }
    },
    [learningHook, unlearningProviders],
  );

  const bumpHistoryRefreshToken = useCallback(() => {
    setHistoryRefreshToken((t) => t + 1);
  }, []);

  const addAgentToSquad = useCallback(
    (agentId: string) => {
      setSquadAgentIds((prev) => (prev.includes(agentId) ? prev : [...prev, agentId]));
      const agent = agents.find((a) => a.id === agentId);
      if (agent?.cli_provider) {
        const provider = agent.cli_provider as HookLearnProvider;
        setSelectedProviders((prev) => (prev.includes(provider) ? prev : [...prev, provider]));
      }
    },
    [agents],
  );

  const removeAgentFromSquad = useCallback((agentId: string) => {
    setSquadAgentIds((prev) => prev.filter((id) => id !== agentId));
  }, []);

  // Cleanup timers
  useEffect(() => {
    return () => {
      for (const timerId of Object.values(unlearnEffectTimersRef.current)) {
        if (typeof timerId === "number") window.clearTimeout(timerId);
      }
    };
  }, []);

  return {
    // Data
    hooks,
    loading,
    error,
    loadHooks,

    // Filters
    search,
    setSearch,
    selectedEventType,
    setSelectedEventType,
    sortBy,
    setSortBy,
    eventTypeCounts,
    filtered,

    // Modal
    showFormModal,
    editingHook,
    formSubmitting,
    formError,
    openCreateModal,
    openEditModal,
    closeFormModal,
    handleCreateHook,
    handleUpdateHook,

    // Actions
    handleToggleHook,
    handleDeleteHook,
    deletingHookId,

    // Context data
    agents,
    departments,

    // Learning
    learningHook,
    learnInProgress,
    selectedProviders,
    representatives,
    preferKoreanName,
    modalLearnedProviders,
    unlearningProviders,
    unlearnEffects,
    learnJob,
    learnError,
    unlearnError,
    learnSubmitting,
    defaultSelectedProviders,
    learnedProvidersByHook,
    learnedRepresentatives,
    historyRefreshToken,
    openLearningModal,
    closeLearningModal,
    toggleProvider,
    handleStartLearning,
    handleUnlearnProvider,
    bumpHistoryRefreshToken,
    squadAgentIds,
    addAgentToSquad,
    removeAgentFromSquad,
  };
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  getAvailableLearnedMemories,
  getMemoryLearningHistory,
  unlearnMemory,
  type LearnedMemoryEntry,
  type MemoryHistoryProvider,
  type MemoryLearningHistoryEntry,
} from "../../api/memory";
import type { Agent } from "../../types";
import AgentAvatar from "../AgentAvatar";
import {
  MEMORY_LEARNED_PROVIDER_ORDER,
  memoryProviderLabel,
  memoryStatusLabel,
  memoryStatusClass,
  memoryRelativeTime,
  memoryLearningRowKey,
  pickRepresentativeForProvider,
  type TFunction,
  type UnlearnEffect,
} from "./model";

const HISTORY_PREVIEW_COUNT = 3;

interface MemoryHistoryPanelProps {
  t: TFunction;
  agents: Agent[];
  refreshToken?: number;
  className?: string;
  onLearningDataChanged?: () => void;
}

export default function MemoryHistoryPanel({
  t,
  agents,
  refreshToken = 0,
  className = "",
  onLearningDataChanged,
}: MemoryHistoryPanelProps) {
  const [tab, setTab] = useState<"history" | "available">("history");
  const [providerFilter, setProviderFilter] = useState<"all" | MemoryHistoryProvider>("all");
  const [historyRows, setHistoryRows] = useState<MemoryLearningHistoryEntry[]>([]);
  const [availableRows, setAvailableRows] = useState<LearnedMemoryEntry[]>([]);
  const [historyExpanded, setHistoryExpanded] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [unlearnError, setUnlearnError] = useState<string | null>(null);
  const [unlearningKeys, setUnlearningKeys] = useState<string[]>([]);
  const [unlearnEffects, setUnlearnEffects] = useState<Partial<Record<string, UnlearnEffect>>>({});
  const [centerBonk, setCenterBonk] = useState<{
    provider: MemoryHistoryProvider;
    agent: Agent | null;
  } | null>(null);
  const unlearnEffectTimersRef = useRef<Partial<Record<string, number>>>({});
  const centerBonkTimerRef = useRef<number | null>(null);

  const representatives = useMemo(() => {
    const out = new Map<MemoryHistoryProvider, Agent | null>();
    for (const provider of MEMORY_LEARNED_PROVIDER_ORDER) {
      out.set(provider, pickRepresentativeForProvider(agents, provider));
    }
    return out;
  }, [agents]);

  const activeProviders = useMemo(() => {
    const fromRows = new Set<MemoryHistoryProvider>();
    for (const row of historyRows) fromRows.add(row.provider);
    for (const row of availableRows) fromRows.add(row.provider);
    for (const provider of MEMORY_LEARNED_PROVIDER_ORDER) {
      if (representatives.get(provider)) {
        fromRows.add(provider);
      }
    }
    return MEMORY_LEARNED_PROVIDER_ORDER.filter((provider) => fromRows.has(provider));
  }, [availableRows, historyRows, representatives]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const provider = providerFilter === "all" ? undefined : providerFilter;
      const [historyData, availableData] = await Promise.all([
        getMemoryLearningHistory({ provider, limit: 80 }).catch((err) => {
          const msg = err instanceof Error ? err.message : String(err);
          if (/not_found|404/.test(msg)) return { history: [] as MemoryLearningHistoryEntry[], retentionDays: 180 };
          throw err;
        }),
        getAvailableLearnedMemories({ provider, limit: 30 }).catch((err) => {
          const msg = err instanceof Error ? err.message : String(err);
          if (/not_found|404/.test(msg)) return [] as LearnedMemoryEntry[];
          throw err;
        }),
      ]);
      setHistoryRows(historyData.history);
      setAvailableRows(availableData);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }, [providerFilter]);

  useEffect(() => {
    void load();
  }, [load, refreshToken]);

  useEffect(() => {
    setHistoryExpanded(false);
  }, [providerFilter, tab]);

  useEffect(() => {
    return () => {
      for (const timerId of Object.values(unlearnEffectTimersRef.current)) {
        if (typeof timerId === "number") window.clearTimeout(timerId);
      }
      if (typeof centerBonkTimerRef.current === "number") {
        window.clearTimeout(centerBonkTimerRef.current);
      }
    };
  }, []);

  function triggerUnlearnEffect(rowKey: string, provider: MemoryHistoryProvider) {
    const effect: UnlearnEffect = Math.random() < 0.5 ? "pot" : "hammer";
    setUnlearnEffects((prev) => ({ ...prev, [rowKey]: effect }));
    setCenterBonk({
      provider,
      agent: representatives.get(provider) ?? null,
    });
    if (typeof centerBonkTimerRef.current === "number") {
      window.clearTimeout(centerBonkTimerRef.current);
    }
    centerBonkTimerRef.current = window.setTimeout(() => {
      setCenterBonk(null);
      centerBonkTimerRef.current = null;
    }, 950);
    const existingTimer = unlearnEffectTimersRef.current[rowKey];
    if (typeof existingTimer === "number") {
      window.clearTimeout(existingTimer);
    }
    unlearnEffectTimersRef.current[rowKey] = window.setTimeout(() => {
      setUnlearnEffects((prev) => {
        const next = { ...prev };
        delete next[rowKey];
        return next;
      });
      delete unlearnEffectTimersRef.current[rowKey];
    }, 1100);
  }

  async function handleUnlearn(row: { provider: MemoryHistoryProvider; memory_id: string }) {
    const rowKey = memoryLearningRowKey(row);
    if (unlearningKeys.includes(rowKey)) return;
    setUnlearnError(null);
    setUnlearningKeys((prev) => [...prev, rowKey]);
    try {
      const result = await unlearnMemory({
        provider: row.provider,
        memoryId: row.memory_id,
      });
      if (result.removed > 0) {
        setAvailableRows((prev) => prev.filter((item) => memoryLearningRowKey(item) !== rowKey));
        setHistoryRows((prev) =>
          prev.filter(
            (item) =>
              !(item.provider === row.provider && item.memory_id === row.memory_id && item.status === "succeeded"),
          ),
        );
        triggerUnlearnEffect(rowKey, row.provider);
      }
      onLearningDataChanged?.();
      void load();
    } catch (e) {
      setUnlearnError(e instanceof Error ? e.message : String(e));
    } finally {
      setUnlearningKeys((prev) => prev.filter((key) => key !== rowKey));
    }
  }

  const visibleHistoryRows = useMemo(() => {
    if (historyExpanded) return historyRows;
    return historyRows.slice(0, HISTORY_PREVIEW_COUNT);
  }, [historyExpanded, historyRows]);

  const hiddenHistoryCount = Math.max(0, historyRows.length - HISTORY_PREVIEW_COUNT);

  return (
    <div
      className={`skill-history-panel flex h-full min-h-[360px] flex-col ${className}`}
      style={{ borderRadius: "4px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)" }}
    >
      <div className="flex items-center justify-between gap-2 px-3 py-2.5" style={{ borderBottom: "1px solid var(--th-border)" }}>
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => setTab("history")}
            className="px-2 py-1 text-[11px] font-mono transition-all"
            style={{
              borderRadius: "2px",
              border: `1px solid ${tab === "history" ? "var(--th-border-strong)" : "transparent"}`,
              background: tab === "history" ? "var(--th-bg-surface)" : "transparent",
              color: tab === "history" ? "var(--th-text-primary)" : "var(--th-text-muted)",
            }}
          >
            {t({ ko: "\uD559\uC2B5 \uC774\uB825", en: "Learning History", ja: "\u5B66\u7FD2\u5C65\u6B74", zh: "\u5B66\u4E60\u8BB0\u5F55" })}
          </button>
          <button
            type="button"
            onClick={() => setTab("available")}
            className="px-2 py-1 text-[11px] font-mono transition-all"
            style={{
              borderRadius: "2px",
              border: `1px solid ${tab === "available" ? "var(--th-border-strong)" : "transparent"}`,
              background: tab === "available" ? "var(--th-bg-surface)" : "transparent",
              color: tab === "available" ? "var(--th-text-primary)" : "var(--th-text-muted)",
            }}
          >
            {t({ ko: "\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uBA54\uBAA8\uB9AC", en: "Available Memories", ja: "\u5229\u7528\u53EF\u80FD\u306A\u30E1\u30E2\u30EA", zh: "\u53EF\u7528\u8BB0\u5FC6" })}
          </button>
        </div>
        <button
          type="button"
          onClick={() => void load()}
          className="px-2 py-1 text-[11px] font-mono transition-all"
          style={{ borderRadius: "2px", border: "1px solid var(--th-border)", color: "var(--th-text-secondary)", background: "transparent" }}
        >
          {t({ ko: "\uC0C8\uB85C\uACE0\uCE68", en: "Refresh", ja: "\u66F4\u65B0", zh: "\u5237\u65B0" })}
        </button>
      </div>

      <div className="flex items-center gap-1 overflow-x-auto px-3 py-2">
        <button
          type="button"
          onClick={() => setProviderFilter("all")}
          className="px-2 py-1 text-[10px] font-mono transition-all"
          style={{
            borderRadius: "2px",
            border: `1px solid ${providerFilter === "all" ? "rgba(251,191,36,0.5)" : "var(--th-border)"}`,
            background: providerFilter === "all" ? "rgba(251,191,36,0.1)" : "transparent",
            color: providerFilter === "all" ? "var(--th-accent)" : "var(--th-text-muted)",
          }}
        >
          All
        </button>
        {activeProviders.map((provider) => (
          <button
            key={provider}
            type="button"
            onClick={() => setProviderFilter(provider)}
            className="px-2 py-1 text-[10px] font-mono transition-all"
            style={{
              borderRadius: "2px",
              border: `1px solid ${providerFilter === provider ? "rgba(251,191,36,0.5)" : "var(--th-border)"}`,
              background: providerFilter === provider ? "rgba(251,191,36,0.1)" : "transparent",
              color: providerFilter === provider ? "var(--th-accent)" : "var(--th-text-muted)",
            }}
          >
            {memoryProviderLabel(provider)}
          </button>
        ))}
      </div>

      <div className="min-h-0 flex-1 space-y-2 overflow-y-auto px-3 pb-3">
        {loading && historyRows.length === 0 && availableRows.length === 0 && (
          <div className="px-3 py-6 text-center text-xs font-mono" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)", color: "var(--th-text-muted)" }}>
            {t({ ko: "\uBA54\uBAA8\uB9AC \uAE30\uB85D \uB85C\uB529\uC911...", en: "Loading memory records...", ja: "\u30E1\u30E2\u30EA\u8A18\u9332\u3092\u8AAD\u307F\u8FBC\u307F\u4E2D...", zh: "\u6B63\u5728\u52A0\u8F7D\u8BB0\u5FC6\u8BB0\u5F55..." })}
          </div>
        )}

        {error && (
          <div className="px-3 py-2 text-[11px] text-rose-200" style={{ borderRadius: "2px", border: "1px solid rgba(244,63,94,0.3)", background: "rgba(244,63,94,0.1)" }}>
            {error}
          </div>
        )}
        {unlearnError && (
          <div className="px-3 py-2 text-[11px] text-rose-200" style={{ borderRadius: "2px", border: "1px solid rgba(244,63,94,0.3)", background: "rgba(244,63,94,0.1)" }}>
            {unlearnError}
          </div>
        )}

        {tab === "history" && historyRows.length === 0 && !loading && !error && (
          <div className="px-3 py-6 text-center text-xs font-mono" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)", color: "var(--th-text-muted)" }}>
            {t({ ko: "\uD559\uC2B5 \uC774\uB825\uC774 \uC5C6\uC2B5\uB2C8\uB2E4", en: "No learning history yet.", ja: "\u5B66\u7FD2\u5C65\u6B74\u304C\u3042\u308A\u307E\u305B\u3093", zh: "\u6682\u65E0\u5B66\u4E60\u8BB0\u5F55" })}
          </div>
        )}

        {tab === "history" &&
          visibleHistoryRows.map((row) => {
            const agent = representatives.get(row.provider) ?? null;
            const label = row.memory_label || row.memory_id;
            const eventAt = row.run_completed_at ?? row.updated_at ?? row.created_at;
            const rowKey = memoryLearningRowKey(row);
            const isUnlearning = unlearningKeys.includes(rowKey);
            const unlearnEffect = unlearnEffects[rowKey];
            const canUnlearn = row.status === "succeeded";
            return (
              <div
                key={row.id}
                className="skill-history-card p-2.5"
                style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-surface)" }}
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <div className="truncate text-xs font-semibold font-mono" style={{ color: "var(--th-text-heading)" }}>{label}</div>
                    <div className="mt-0.5 truncate text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>{row.memory_id}</div>
                  </div>
                  <span className={`px-1.5 py-0.5 text-[10px] font-mono ${memoryStatusClass(row.status)}`} style={{ borderRadius: "2px" }}>
                    {memoryStatusLabel(row.status)}
                  </span>
                </div>
                <div className="skill-history-meta mt-2 flex items-center justify-between gap-2 text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>
                  <div className="flex min-w-0 items-center gap-2">
                    <div
                      className={`relative h-5 w-5 overflow-hidden ${unlearnEffect ? "unlearn-avatar-hit" : ""}`}
                      style={{ borderRadius: "2px", background: "var(--th-bg-primary)" }}
                    >
                      <AgentAvatar agent={agent ?? undefined} agents={agents} size={20} rounded="xl" />
                      {unlearnEffect === "pot" && <span className="unlearn-pot-drop-sm">?ご</span>}
                      {unlearnEffect === "hammer" && <span className="unlearn-hammer-swing-sm">?뵪</span>}
                      {unlearnEffect && <span className="unlearn-hit-text-sm">Bonk!</span>}
                    </div>
                    <span className="truncate">
                      {memoryProviderLabel(row.provider)}
                      {agent ? ` 쨌 ${agent.name}` : ""}
                    </span>
                  </div>
                  <div className="flex shrink-0 items-center gap-2">
                    {canUnlearn && (
                      <button
                        type="button"
                        onClick={() => void handleUnlearn(row)}
                        disabled={isUnlearning}
                        className={`skill-unlearn-btn px-1.5 py-0.5 text-[10px] font-mono transition-all ${isUnlearning ? "cursor-not-allowed" : ""}`}
                        style={{
                          borderRadius: "2px",
                          border: `1px solid ${isUnlearning ? "rgba(51,65,85,1)" : "rgba(244,63,94,0.35)"}`,
                          color: isUnlearning ? "var(--th-text-muted)" : "rgb(253,164,175)",
                          background: isUnlearning ? "transparent" : "rgba(244,63,94,0.1)",
                        }}
                      >
                        {isUnlearning
                          ? t({ ko: "\uCDE8\uC18C\uC911...", en: "Unlearning...", ja: "\u53D6\u6D88\u4E2D...", zh: "\u53D6\u6D88\u4E2D..." })
                          : t({ ko: "\uD559\uC2B5 \uCDE8\uC18C", en: "Unlearn", ja: "\u5B66\u7FD2\u53D6\u6D88", zh: "\u53D6\u6D88\u5B66\u4E60" })}
                      </button>
                    )}
                    <span className="skill-history-time" style={{ color: "var(--th-text-muted)" }}>{memoryRelativeTime(eventAt)}</span>
                  </div>
                </div>
                {row.error && <div className="mt-1 break-words text-[10px]" style={{ color: "rgb(253,164,175)" }}>{row.error}</div>}
              </div>
            );
          })}

        {tab === "history" && hiddenHistoryCount > 0 && (
          <div className="flex justify-center pt-1">
            <button
              type="button"
              onClick={() => setHistoryExpanded((prev) => !prev)}
              className="px-2.5 py-1 text-[11px] font-mono transition-all"
              style={{ borderRadius: "2px", border: "1px solid var(--th-border)", color: "var(--th-text-secondary)", background: "transparent" }}
            >
              {historyExpanded
                ? t({ ko: "\uC811\uAE30", en: "Show less", ja: "\u6298\u308A\u305F\u305F\u3080", zh: "\u6536\u8D77" })
                : t({
                    ko: `${hiddenHistoryCount}\uAC1C \uB354 \uBCF4\uAE30`,
                    en: `Show ${hiddenHistoryCount} more`,
                    ja: `${hiddenHistoryCount}\u4EF6\u8868\u793A`,
                    zh: `\u663E\u793A${hiddenHistoryCount}\u66F4\u591A`,
                  })}
            </button>
          </div>
        )}

        {tab === "available" && availableRows.length === 0 && !loading && !error && (
          <div className="px-3 py-6 text-center text-xs font-mono" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)", color: "var(--th-text-muted)" }}>
            {t({ ko: "\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uBA54\uBAA8\uB9AC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4", en: "No available memories.", ja: "\u5229\u7528\u53EF\u80FD\u306A\u30E1\u30E2\u30EA\u304C\u3042\u308A\u307E\u305B\u3093", zh: "\u6682\u65E0\u53EF\u7528\u8BB0\u5FC6" })}
          </div>
        )}

        {tab === "available" &&
          availableRows.map((row) => {
            const agent = representatives.get(row.provider) ?? null;
            const label = row.memory_label || row.memory_id;
            const rowKey = memoryLearningRowKey(row);
            const isUnlearning = unlearningKeys.includes(rowKey);
            const unlearnEffect = unlearnEffects[rowKey];
            return (
              <div
                key={`${row.provider}-${row.memory_id}`}
                className="skill-history-card p-2.5"
                style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-surface)" }}
              >
                <div className="truncate text-xs font-semibold font-mono" style={{ color: "var(--th-text-heading)" }}>{label}</div>
                <div className="mt-0.5 truncate text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>{row.memory_id}</div>
                <div className="skill-history-meta mt-2 flex items-center justify-between gap-2 text-[10px] font-mono" style={{ color: "var(--th-text-muted)" }}>
                  <div className="flex min-w-0 items-center gap-2">
                    <div
                      className={`relative h-5 w-5 overflow-hidden ${unlearnEffect ? "unlearn-avatar-hit" : ""}`}
                      style={{ borderRadius: "2px", background: "var(--th-bg-primary)" }}
                    >
                      <AgentAvatar agent={agent ?? undefined} agents={agents} size={20} rounded="xl" />
                      {unlearnEffect === "pot" && <span className="unlearn-pot-drop-sm">?ご</span>}
                      {unlearnEffect === "hammer" && <span className="unlearn-hammer-swing-sm">?뵪</span>}
                      {unlearnEffect && <span className="unlearn-hit-text-sm">Bonk!</span>}
                    </div>
                    <span className="truncate">
                      {memoryProviderLabel(row.provider)}
                      {agent ? ` 쨌 ${agent.name}` : ""}
                    </span>
                  </div>
                  <div className="flex shrink-0 items-center gap-2">
                    <button
                      type="button"
                      onClick={() => void handleUnlearn(row)}
                      disabled={isUnlearning}
                      className="skill-unlearn-btn px-1.5 py-0.5 text-[10px] transition-all"
                      style={isUnlearning
                        ? { borderRadius: "2px", border: "1px solid var(--th-border)", color: "var(--th-text-muted)", cursor: "not-allowed" }
                        : { borderRadius: "2px", border: "1px solid rgba(244,63,94,0.35)", background: "rgba(244,63,94,0.1)", color: "rgb(253,164,175)" }}
                    >
                      {isUnlearning
                        ? t({ ko: "\uCDE8\uC18C\uC911...", en: "Unlearning...", ja: "\u53D6\u6D88\u4E2D...", zh: "\u53D6\u6D88\u4E2D..." })
                        : t({ ko: "\uD559\uC2B5 \uCDE8\uC18C", en: "Unlearn", ja: "\u5B66\u7FD2\u53D6\u6D88", zh: "\u53D6\u6D88\u5B66\u4E60" })}
                    </button>
                    <span className="skill-history-time" style={{ color: "var(--th-text-muted)" }}>{memoryRelativeTime(row.learned_at)}</span>
                  </div>
                </div>
              </div>
            );
          })}
      </div>

      {centerBonk && (
        <div className="pointer-events-none fixed inset-0 z-[120] flex items-center justify-center">
          <div className="skill-history-center-card unlearn-center-card px-6 py-4" style={{ borderRadius: "4px", border: "1px solid rgba(251,113,133,0.3)", background: "var(--th-terminal-bg)" }}>
            <div className="relative mx-auto h-20 w-20 overflow-visible">
              <div className="unlearn-avatar-hit">
                <AgentAvatar agent={centerBonk.agent ?? undefined} agents={agents} size={80} rounded="xl" />
              </div>
              <span className="unlearn-hammer-swing-center">?뵪</span>
              <span className="unlearn-hit-text-center">Bonk!</span>
            </div>
            <div className="skill-history-center-label mt-2 text-center text-xs font-medium" style={{ color: "rgb(255,228,230)" }}>
              {memoryProviderLabel(centerBonk.provider)}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { MemoryEntry, MemoryCategory, Department, Agent } from "../../types";
import {
  getMemoryEntries,
  createMemoryEntry,
  updateMemoryEntry,
  toggleMemoryEntry,
  deleteMemoryEntry,
  startMemoryLearning,
  getMemoryLearningJob,
  getAvailableLearnedMemories,
  unlearnMemory,
  type CreateMemoryInput,
  type UpdateMemoryInput,
  type MemoryLearnProvider,
  type MemoryHistoryProvider,
  type MemoryLearnJob,
  type LearnedMemoryEntry,
} from "../../api/memory";
import type { TFunction, MemorySortBy, UnlearnEffect } from "./model";
import {
  ALL_CATEGORIES,
  MEMORY_LEARN_PROVIDER_ORDER,
  MEMORY_LEARNED_PROVIDER_ORDER,
  pickRepresentativeForProvider,
} from "./model";

interface UseMemoryStateOptions {
  agents: Agent[];
  departments: Department[];
  t: TFunction;
}

export function useMemoryState({ agents, departments, t }: UseMemoryStateOptions) {
  const [entries, setEntries] = useState<MemoryEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Filters
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("All");
  const [sortBy, setSortBy] = useState<MemorySortBy>("priority");

  // Modal state
  const [showFormModal, setShowFormModal] = useState(false);
  const [editingEntry, setEditingEntry] = useState<MemoryEntry | null>(null);
  const [formSubmitting, setFormSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  // Delete state
  const [deletingEntryId, setDeletingEntryId] = useState<string | null>(null);

  // ?? Learning state ??????????????????????????????????????????????
  const [learningEntry, setLearningEntry] = useState<MemoryEntry | null>(null);
  const [selectedProviders, setSelectedProviders] = useState<MemoryLearnProvider[]>([]);
  const [learnJob, setLearnJob] = useState<MemoryLearnJob | null>(null);
  const [learnSubmitting, setLearnSubmitting] = useState(false);
  const [learnError, setLearnError] = useState<string | null>(null);
  const [unlearnError, setUnlearnError] = useState<string | null>(null);
  const [unlearningProviders, setUnlearningProviders] = useState<MemoryLearnProvider[]>([]);
  const [unlearnEffects, setUnlearnEffects] = useState<Partial<Record<MemoryLearnProvider, UnlearnEffect>>>({});
  const [historyRefreshToken, setHistoryRefreshToken] = useState(0);
  const [learnedRows, setLearnedRows] = useState<LearnedMemoryEntry[]>([]);
  const [squadAgentIds, setSquadAgentIds] = useState<string[]>([]);
  const unlearnEffectTimersRef = useRef<Partial<Record<MemoryLearnProvider, number>>>({});

  // ?? Load entries ??????????????????????????????????????????????????
  const loadEntries = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await getMemoryEntries();
      setEntries(data);
    } catch (err: unknown) {
      setError(String((err as Error).message ?? err));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadEntries();
  }, [loadEntries]);

  // ?? Load learned rows ???????????????????????????????????????????
  useEffect(() => {
    let cancelled = false;
    getAvailableLearnedMemories({ limit: 500 })
      .then((rows) => {
        if (!cancelled) setLearnedRows(rows);
      })
      .catch(() => {
        if (!cancelled) setLearnedRows([]);
      });
    return () => {
      cancelled = true;
    };
  }, [historyRefreshToken]);

  // ?? Representatives ?????????????????????????????????????????????
  const representatives = useMemo(
    () =>
      MEMORY_LEARN_PROVIDER_ORDER.map((provider) => ({
        provider,
        agent: pickRepresentativeForProvider(agents, provider),
      })),
    [agents],
  );

  const defaultSelectedProviders = useMemo(
    () => representatives.filter((row) => row.agent).map((row) => row.provider),
    [representatives],
  );

  const learnedRepresentatives = useMemo(() => {
    const out = new Map<MemoryHistoryProvider, Agent | null>();
    for (const provider of MEMORY_LEARNED_PROVIDER_ORDER) {
      out.set(provider, pickRepresentativeForProvider(agents, provider));
    }
    return out;
  }, [agents]);

  // ?? Learned providers by entry ???????????????????????????????????
  const learnedProvidersByEntry = useMemo(() => {
    const map = new Map<string, MemoryHistoryProvider[]>();
    for (const row of learnedRows) {
      if (!map.has(row.memory_id)) map.set(row.memory_id, []);
      const providers = map.get(row.memory_id)!;
      if (!providers.includes(row.provider)) providers.push(row.provider);
    }
    return map;
  }, [learnedRows]);

  // ?? Modal learned providers (for current learningEntry) ??????????
  const modalLearnedProviders = useMemo(() => {
    if (!learningEntry) return new Set<MemoryHistoryProvider>();
    const providers = learnedProvidersByEntry.get(learningEntry.id) ?? [];
    return new Set<MemoryHistoryProvider>(providers);
  }, [learningEntry, learnedProvidersByEntry]);

  const preferKoreanName = true;

  // Category counts
  const categoryCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const cat of ALL_CATEGORIES) {
      counts[cat] = cat === "All" ? entries.length : entries.filter((e) => e.category === cat).length;
    }
    return counts;
  }, [entries]);

  // Filtered & sorted (scope ?꾪꽣 ?놁쓬, ?먯씠?꾪듃 猷곌낵 ?숈씪?섍쾶 移댄뀒怨좊━쨌寃?됰쭔)
  const filtered = useMemo(() => {
    let result = [...entries];

    if (selectedCategory !== "All") {
      result = result.filter((e) => e.category === selectedCategory);
    }

    if (search.trim()) {
      const q = search.toLowerCase();
      result = result.filter(
        (e) =>
          e.title.toLowerCase().includes(q) ||
          e.title_ko.toLowerCase().includes(q) ||
          e.description.toLowerCase().includes(q) ||
          e.content.toLowerCase().includes(q) ||
          e.category.toLowerCase().includes(q),
      );
    }

    switch (sortBy) {
      case "priority":
        result.sort((a, b) => b.priority - a.priority || b.created_at - a.created_at);
        break;
      case "name":
        result.sort((a, b) => a.title.localeCompare(b.title));
        break;
      case "date":
        result.sort((a, b) => b.created_at - a.created_at);
        break;
    }

    return result;
  }, [entries, selectedCategory, search, sortBy]);

  // Handlers
  const openCreateModal = useCallback(() => {
    setEditingEntry(null);
    setFormError(null);
    setShowFormModal(true);
  }, []);

  const openEditModal = useCallback((entry: MemoryEntry) => {
    setEditingEntry(entry);
    setFormError(null);
    setShowFormModal(true);
  }, []);

  const closeFormModal = useCallback(() => {
    setShowFormModal(false);
    setEditingEntry(null);
    setFormError(null);
  }, []);

  const handleCreateEntry = useCallback(
    async (input: CreateMemoryInput) => {
      try {
        setFormSubmitting(true);
        setFormError(null);
        const created = await createMemoryEntry(input);
        setEntries((prev) => [created, ...prev]);
        setShowFormModal(false);
        setEditingEntry(null);
      } catch (err: unknown) {
        setFormError(String((err as Error).message ?? err));
      } finally {
        setFormSubmitting(false);
      }
    },
    [],
  );

  const handleUpdateEntry = useCallback(
    async (id: string, input: UpdateMemoryInput) => {
      try {
        setFormSubmitting(true);
        setFormError(null);
        const updated = await updateMemoryEntry(id, input);
        setEntries((prev) => prev.map((e) => (e.id === id ? updated : e)));
        setShowFormModal(false);
        setEditingEntry(null);
      } catch (err: unknown) {
        setFormError(String((err as Error).message ?? err));
      } finally {
        setFormSubmitting(false);
      }
    },
    [],
  );

  const handleToggleEntry = useCallback(async (id: string) => {
    try {
      const result = await toggleMemoryEntry(id);
      setEntries((prev) => prev.map((e) => (e.id === id ? { ...e, enabled: result.enabled } : e)));
    } catch (err: unknown) {
      console.error("Failed to toggle memory entry:", err);
    }
  }, []);

  const handleDeleteEntry = useCallback(async (id: string) => {
    try {
      setDeletingEntryId(id);
      await deleteMemoryEntry(id);
      setEntries((prev) => prev.filter((e) => e.id !== id));
    } catch (err: unknown) {
      console.error("Failed to delete memory entry:", err);
    } finally {
      setDeletingEntryId(null);
    }
  }, []);

  // ?? Learning modal open/close ???????????????????????????????????
  const learnInProgress = !!learnJob && (learnJob.status === "queued" || learnJob.status === "running");

  const openLearningModal = useCallback(
    (entry: MemoryEntry) => {
      setLearningEntry(entry);
      setLearnJob(null);
      setLearnError(null);
      setUnlearnError(null);
      setLearnSubmitting(false);
      setUnlearningProviders([]);
      setUnlearnEffects({});
      setSquadAgentIds([]);
      // Pre-select only providers NOT yet learned
      const alreadyLearned = learnedProvidersByEntry.get(entry.id) ?? [];
      const preSelected = defaultSelectedProviders.filter(
        (p) => !alreadyLearned.includes(p),
      );
      setSelectedProviders(preSelected);
    },
    [defaultSelectedProviders, learnedProvidersByEntry],
  );

  const closeLearningModal = useCallback(() => {
    if (learnInProgress) return;
    setLearningEntry(null);
    setLearnJob(null);
    setLearnError(null);
    setUnlearnError(null);
    setLearnSubmitting(false);
    setSelectedProviders([]);
    setUnlearningProviders([]);
    setUnlearnEffects({});
    setSquadAgentIds([]);
  }, [learnInProgress]);

  const toggleProvider = useCallback(
    (provider: MemoryLearnProvider) => {
      if (learnInProgress) return;
      setSelectedProviders((prev) =>
        prev.includes(provider) ? prev.filter((p) => p !== provider) : [...prev, provider],
      );
    },
    [learnInProgress],
  );

  // ?? Job polling ?????????????????????????????????????????????????
  useEffect(() => {
    if (!learnJob || (learnJob.status !== "queued" && learnJob.status !== "running")) return;
    const timer = window.setInterval(() => {
      getMemoryLearningJob(learnJob.id)
        .then(setLearnJob)
        .catch(() => {});
    }, 1500);
    return () => window.clearInterval(timer);
  }, [learnJob]);

  // Optimistic update: immediately reflect learned rows on success before server refetch
  useEffect(() => {
    if (!learnJob || learnJob.status !== "succeeded") return;
    const { memoryId, memoryTitle, providers, completedAt } = learnJob;
    const learnedAt = completedAt ?? Date.now();
    setLearnedRows((prev) => {
      const seen = new Set(prev.map((r) => `${r.memory_id}:${r.provider}`));
      const added: LearnedMemoryEntry[] = [];
      for (const provider of providers) {
        if (seen.has(`${memoryId}:${provider}`)) continue;
        seen.add(`${memoryId}:${provider}`);
        added.push({ provider, memory_id: memoryId, memory_label: memoryTitle, learned_at: learnedAt });
      }
      if (added.length === 0) return prev;
      return [...added, ...prev].sort((a, b) => b.learned_at - a.learned_at);
    });
  }, [learnJob?.id, learnJob?.status, learnJob?.memoryId, learnJob?.memoryTitle, learnJob?.providers, learnJob?.completedAt]);

  // Bump history on job completion (immediate + delayed to ensure server storage is reflected)
  useEffect(() => {
    if (!learnJob || (learnJob.status !== "succeeded" && learnJob.status !== "failed")) return;
    setHistoryRefreshToken((t) => t + 1);
    const id = window.setTimeout(() => {
      setHistoryRefreshToken((t) => t + 1);
    }, 1200);
    return () => window.clearTimeout(id);
  }, [learnJob?.id, learnJob?.status]);

  // ?? Start learning ??????????????????????????????????????????????
  const handleStartLearning = useCallback(async () => {
    if (!learningEntry || selectedProviders.length === 0 || learnSubmitting || learnInProgress) return;
    setLearnSubmitting(true);
    setLearnError(null);
    try {
      const job = await startMemoryLearning({
        memoryId: learningEntry.id,
        providers: selectedProviders,
      });
      setLearnJob(job);
    } catch (err: unknown) {
      setLearnError(String((err as Error).message ?? err));
    } finally {
      setLearnSubmitting(false);
    }
  }, [learningEntry, selectedProviders, learnSubmitting, learnInProgress]);

  // ?? Unlearn from modal ??????????????????????????????????????????
  const handleUnlearnProvider = useCallback(
    async (provider: MemoryLearnProvider) => {
      if (!learningEntry || unlearningProviders.includes(provider)) return;
      setUnlearnError(null);
      setUnlearningProviders((prev) => [...prev, provider]);
      try {
        const result = await unlearnMemory({
          provider,
          memoryId: learningEntry.id,
        });
        if (result.removed > 0) {
          setLearnedRows((prev) =>
            prev.filter((r) => !(r.provider === provider && r.memory_id === learningEntry.id)),
          );
          // Trigger animation
          const effect: UnlearnEffect = Math.random() < 0.5 ? "pot" : "hammer";
          setUnlearnEffects((prev) => ({ ...prev, [provider]: effect }));
          const existing = unlearnEffectTimersRef.current[provider];
          if (typeof existing === "number") window.clearTimeout(existing);
          unlearnEffectTimersRef.current[provider] = window.setTimeout(() => {
            setUnlearnEffects((prev) => {
              const next = { ...prev };
              delete next[provider];
              return next;
            });
            delete unlearnEffectTimersRef.current[provider];
          }, 1100);
          setHistoryRefreshToken((t) => t + 1);
        }
      } catch (err: unknown) {
        setUnlearnError(String((err as Error).message ?? err));
      } finally {
        setUnlearningProviders((prev) => prev.filter((p) => p !== provider));
      }
    },
    [learningEntry, unlearningProviders],
  );

  const bumpHistoryRefreshToken = useCallback(() => {
    setHistoryRefreshToken((t) => t + 1);
  }, []);

  const addAgentToSquad = useCallback(
    (agentId: string) => {
      setSquadAgentIds((prev) => (prev.includes(agentId) ? prev : [...prev, agentId]));
      const agent = agents.find((a) => a.id === agentId);
      if (agent?.cli_provider) {
        const provider = agent.cli_provider as MemoryLearnProvider;
        setSelectedProviders((prev) => (prev.includes(provider) ? prev : [...prev, provider]));
      }
    },
    [agents],
  );

  const removeAgentFromSquad = useCallback((agentId: string) => {
    setSquadAgentIds((prev) => prev.filter((id) => id !== agentId));
  }, []);

  // Cleanup timers
  useEffect(() => {
    return () => {
      for (const timerId of Object.values(unlearnEffectTimersRef.current)) {
        if (typeof timerId === "number") window.clearTimeout(timerId);
      }
    };
  }, []);

  return {
    // Data
    entries,
    loading,
    error,
    loadEntries,

    // Filters
    search,
    setSearch,
    selectedCategory,
    setSelectedCategory,
    sortBy,
    setSortBy,
    categoryCounts,
    filtered,

    // Modal
    showFormModal,
    editingEntry,
    formSubmitting,
    formError,
    openCreateModal,
    openEditModal,
    closeFormModal,
    handleCreateEntry,
    handleUpdateEntry,

    // Actions
    handleToggleEntry,
    handleDeleteEntry,
    deletingEntryId,

    // Context data
    agents,
    departments,

    // Learning
    learningEntry,
    learnInProgress,
    selectedProviders,
    representatives,
    preferKoreanName,
    modalLearnedProviders,
    unlearningProviders,
    unlearnEffects,
    learnJob,
    learnError,
    unlearnError,
    learnSubmitting,
    defaultSelectedProviders,
    learnedProvidersByEntry,
    learnedRepresentatives,
    historyRefreshToken,
    openLearningModal,
    closeLearningModal,
    toggleProvider,
    handleStartLearning,
    handleUnlearnProvider,
    bumpHistoryRefreshToken,
    squadAgentIds,
    addAgentToSquad,
    removeAgentFromSquad,
  };
}

import type { Department, Agent } from "../../types";
import type { CliStatusMap } from "../../types";
import type { CliUsageEntry } from "../../api";

interface Props {
  departments: Department[];
  agents: Agent[];
  tasks?: import("../../types").Task[];
  selectedDeptId: string | null;
  onSelectDept: (dept: Department) => void;
  onCallElevator?: (dept: Department, floorIdx: number) => void;
  onScrollToFloor?: (target: "ceo" | "conf" | "basement") => void;
  visitorsByDeptId?: Record<string, number>;
  cliStatus?: CliStatusMap | null;
  cliUsage?: Record<string, CliUsageEntry> | null;
  cliUsageRefreshing?: boolean;
  onRefreshCliUsage?: () => void;
  /** When true, show simplified dept list (no ACT bars, LIFT, task details) */
  isOverviewMode?: boolean;
}

function getAttrFillColor(pct: number): string {
  if (pct >= 80) return "#22c55e";
  if (pct >= 60) return "#f59e0b";
  if (pct >= 40) return "#fbbf24";
  return "#f87171";
}

export default function OfficeDeptPanel({
  departments,
  agents,
  tasks,
  selectedDeptId,
  onSelectDept,
  onCallElevator,
  onScrollToFloor,
  visitorsByDeptId,
  cliStatus,
  cliUsage,
  cliUsageRefreshing,
  onRefreshCliUsage,
  isOverviewMode,
}: Props) {
  // departments is already sorted by tower floor order (sortedDepartments from OfficeView)
  const sortedDepts = departments;

  // CLI usage ??pick the most-used provider's utilization for the summary bar
  const cliProviders = ["claude", "codex", "gemini"] as const;
  const bestUsage = (() => {
    if (!cliUsage) return null;
    let maxPct = 0;
    let label = "";
    for (const key of cliProviders) {
      const entry = cliUsage[key];
      if (!entry || entry.error) continue;
      const w = entry.windows?.[0];
      if (w && w.utilization > maxPct) {
        maxPct = w.utilization;
        label = `${key}: ${Math.round(w.utilization * 100)}%`;
      }
    }
    return maxPct > 0 ? { pct: Math.round(maxPct * 100), label } : null;
  })();

  const isConnected = cliProviders.some((k) => {
    const s = cliStatus?.[k as keyof CliStatusMap];
    return s?.installed && s?.authenticated;
  });

  return (
    <>
      <div className="office-panel-label">Building</div>

      {/* P ??CEO Penthouse (top of tower) */}
      <div
        className="office-dept-item"
        style={{ cursor: "pointer", opacity: 0.9 }}
        onClick={() => onScrollToFloor?.("ceo")}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
          <span style={{
            fontFamily: "var(--th-font-mono)", fontSize: "0.55rem", fontWeight: 700,
            color: "#000", background: "#f59e0b",
            padding: "0 4px", lineHeight: "14px", flexShrink: 0, letterSpacing: 1,
          }}>P</span>
          <div className="office-dept-item__name" style={{ flex: 1, minWidth: 0, color: "var(--th-accent)" }}>
            CEO Penthouse
          </div>
        </div>
        {!isOverviewMode && (
          <div style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.5rem", color: "var(--th-text-muted)", letterSpacing: 1 }}>
            ??scroll to top
          </div>
        )}
      </div>

      {/* CONF ??Meeting Room (fixed floor between penthouse and depts) */}
      <div
        className="office-dept-item"
        style={{ cursor: "pointer", opacity: 0.85 }}
        onClick={() => onScrollToFloor?.("conf")}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
          <span style={{
            fontFamily: "var(--th-font-mono)", fontSize: "0.55rem", fontWeight: 700,
            color: "#000", background: "#a855f7",
            padding: "0 4px", lineHeight: "14px", flexShrink: 0, letterSpacing: 1,
          }}>CONF</span>
          <div className="office-dept-item__name" style={{ flex: 1, minWidth: 0, color: "var(--th-text-secondary)" }}>
            Meeting Room
          </div>
        </div>
        {!isOverviewMode && (
          <div style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.5rem", color: "var(--th-text-muted)", letterSpacing: 1 }}>
            ??scroll to view
          </div>
        )}
      </div>

      <div className="office-panel-label">Departments</div>

      {sortedDepts.length === 0 ? (
        <div style={{ padding: "12px", fontFamily: "var(--th-font-mono)", fontSize: "0.65rem", color: "var(--th-text-muted)" }}>
          $ ls depts/ (empty)
        </div>
      ) : (
        sortedDepts.map((dept, floorIdx) => {
          const deptAgents = agents.filter((a) => a.department_id === dept.id);
          const runningCount = deptAgents.filter((a) => a.status === "working").length;
          const idleCount = deptAgents.filter((a) => a.status === "idle").length;
          const breakCount = deptAgents.filter((a) => a.status === "break").length;
          const totalCount = deptAgents.length;
          const activityPct = totalCount > 0 ? Math.round((runningCount / totalCount) * 100) : 0;
          const floorLabel = `F${floorIdx + 1}`;

          const deptAgentIds = new Set(deptAgents.map((a) => a.id));
          const activeTasks = tasks?.filter((t) => deptAgentIds.has(t.assigned_agent_id ?? "") && t.status === "in_progress").length ?? 0;
          const doneTasks = tasks?.filter((t) => deptAgentIds.has(t.assigned_agent_id ?? "") && t.status === "done").length ?? 0;

          return (
            <div
              key={dept.id}
              className={`office-dept-item${selectedDeptId === dept.id ? " office-dept-item--active" : ""}`}
              onClick={() => onSelectDept(dept)}
            >
              {/* FM-style header row: floor badge + activity dot + name + lift button */}
              <div style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: isOverviewMode ? 0 : 2 }}>
                <span style={{
                  fontFamily: "var(--th-font-mono)", fontSize: "0.55rem", fontWeight: 700,
                  color: "#000", background: "var(--th-accent)",
                  padding: "0 4px", lineHeight: "14px", flexShrink: 0, letterSpacing: 1,
                }}>
                  {floorLabel}
                </span>
                <span style={{
                  width: 5, height: 5, borderRadius: "50%", flexShrink: 0,
                  background: activityPct >= 70 ? "#22c55e" : activityPct >= 30 ? "#f59e0b" : totalCount === 0 ? "#444" : "#f87171",
                }} title={`Activity: ${activityPct}%`} />
                <div className="office-dept-item__name" title={dept.name} style={{ flex: 1, minWidth: 0 }}>
                  {dept.icon} {dept.name}
                </div>
                {!isOverviewMode && visitorsByDeptId?.[dept.id] ? (
                  <span style={{
                    fontFamily: "var(--th-font-mono)", fontSize: "0.42rem", fontWeight: 700,
                    color: "#22c55e", background: "rgba(34,197,94,0.12)",
                    border: "1px solid rgba(34,197,94,0.35)", padding: "0 3px", lineHeight: "14px",
                    flexShrink: 0, letterSpacing: 1,
                  }} title={`${visitorsByDeptId[dept.id]} visitor(s) incoming`}>
                    ??visitorsByDeptId[dept.id]}
                  </span>
                ) : null}
                {!isOverviewMode && onCallElevator && (
                  <button
                    className="fm-lift-btn"
                    title={`Send elevator to ${dept.name} (${floorLabel})`}
                    onClick={(e) => { e.stopPropagation(); onCallElevator(dept, floorIdx + 1); }}
                  >
                    LIFT
                  </button>
                )}
                {isOverviewMode && (
                  <span style={{
                    fontFamily: "var(--th-font-mono)", fontSize: "0.5rem",
                    color: "var(--th-text-muted)", flexShrink: 0,
                  }}>
                    {runningCount}/{totalCount}
                  </span>
                )}
              </div>

              {/* FM attribute bars row ??hidden in overview */}
              {!isOverviewMode && (
                <div className="fm-attr-row">
                  <div className="fm-attr">
                    <span className="fm-attr__lbl">ACT</span>
                    <div className="fm-attr__bar">
                      <div className="fm-attr__fill" style={{ width: `${activityPct}%`, background: getAttrFillColor(activityPct) }} />
                    </div>
                    <span className="fm-attr__val">{activityPct}</span>
                  </div>
                  <div className="fm-attr__agents">
                    <span style={{ color: "#22c55e" }}>{runningCount}W</span>
                    {idleCount > 0 && <span style={{ color: "var(--th-text-muted)" }}> {idleCount}I</span>}
                    {breakCount > 0 && <span style={{ color: "var(--th-accent)" }}> {breakCount}B</span>}
                    {totalCount === 0 && <span style={{ color: "var(--th-text-muted)" }}>no agents</span>}
                  </div>
                </div>
              )}
              {/* Task mini-summary ??hidden in overview */}
              {!isOverviewMode && (activeTasks > 0 || doneTasks > 0) && (
                <div style={{ display: "flex", gap: 6, marginTop: 2 }}>
                  {activeTasks > 0 && (
                    <span style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.42rem", color: "#f59e0b", letterSpacing: 1 }}>
                      ??activeTasks} ACTIVE
                    </span>
                  )}
                  {doneTasks > 0 && (
                    <span style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.42rem", color: "#22c55e", letterSpacing: 1 }}>
                      ??doneTasks} DONE
                    </span>
                  )}
                </div>
              )}
            </div>
          );
        })
      )}

      {/* B1 ??Break Room (basement, at bottom of tower) */}
      <div
        className="office-dept-item"
        style={{ cursor: "pointer", opacity: 0.85 }}
        onClick={() => onScrollToFloor?.("basement")}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
          <span style={{
            fontFamily: "var(--th-font-mono)", fontSize: "0.55rem", fontWeight: 700,
            color: "#000", background: "#22c55e",
            padding: "0 4px", lineHeight: "14px", flexShrink: 0, letterSpacing: 1,
          }}>B1</span>
          <div className="office-dept-item__name" style={{ flex: 1, minWidth: 0, color: "var(--th-text-secondary)" }}>
            Break Room
          </div>
        </div>
        {!isOverviewMode && (
          <div style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.5rem", color: "var(--th-text-muted)", letterSpacing: 1 }}>
            ??scroll to view
          </div>
        )}
      </div>

      {/* CLI Usage ??hidden in overview mode */}
      {!isOverviewMode && (
        <>
          <div className="office-panel-divider" />
          <div className="office-panel-label">CLI Usage</div>

          {!isConnected ? (
            <div style={{ padding: "6px 12px 10px", fontFamily: "var(--th-font-mono)", fontSize: "0.6rem", color: "var(--th-text-muted)", lineHeight: 1.5 }}>
              No CLI connected.<br />
              Check Settings.
            </div>
          ) : (
            <div style={{ padding: "6px 12px 10px" }}>
              {bestUsage ? (
                <>
                  <div style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.65rem", color: bestUsage.pct >= 80 ? "#f85149" : "var(--th-accent)", marginBottom: 4 }}>
                    {bestUsage.label}
                  </div>
                  <div style={{ height: 3, background: "var(--th-border)", borderRadius: 2, overflow: "hidden" }}>
                    <div
                      style={{
                        height: "100%",
                        width: `${Math.min(100, bestUsage.pct)}%`,
                        background: bestUsage.pct >= 80 ? "#f85149" : "var(--th-accent)",
                        borderRadius: 2,
                        transition: "width 300ms linear",
                      }}
                    />
                  </div>
                </>
              ) : (
                <div style={{ fontFamily: "var(--th-font-mono)", fontSize: "0.6rem", color: "var(--th-text-muted)" }}>
                  No data yet.
                </div>
              )}
              {onRefreshCliUsage && (
                <button
                  className="office-actionbar-btn"
                  style={{ marginTop: 6, padding: "2px 0" }}
                  onClick={(e) => { e.stopPropagation(); onRefreshCliUsage(); }}
                  disabled={cliUsageRefreshing}
                >
                  {cliUsageRefreshing ? "..." : "REFRESH"}
                </button>
              )}
            </div>
          )}
        </>
      )}
    </>
  );
}

