    );
    this._scale = new VecProxy(
      () => this._obj.scaleX, v => { this._obj.scaleX = v; },
      () => this._obj.scaleY, v => { this._obj.scaleY = v; },
      (x, y) => this._obj.setScale(x, y),
    );
  }

  get text()           { return this._obj.text; }
