/* ?? Persistence ?? */

export function loadRoomDecorations(): Record<string, RoomDecoration> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    return JSON.parse(raw);
  } catch {
    return {};
  }
}

export function saveRoomDecorations(decorations: Record<string, RoomDecoration>): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(decorations));
  } catch {}
  window.dispatchEvent(new CustomEvent("agentdesk_room_decor_change", { detail: decorations }));
}

export function getRoomDecoration(decorations: Record<string, RoomDecoration>, deptId: string): RoomDecoration {
  return decorations[deptId] ?? { ...DEFAULT_DECORATION };
}

export function getDefaultDecoration(): RoomDecoration {
  return { ...DEFAULT_DECORATION };
}

/* ?? Lighting color modifier ?? */

export function getLightingTint(mood: LightingMood): { glowColor: number; glowAlpha: number } {
  switch (mood) {
    case "warm": return { glowColor: 0xffd080, glowAlpha: 0.08 };
    case "cool": return { glowColor: 0x80c0ff, glowAlpha: 0.06 };
    case "dim": return { glowColor: 0x404060, glowAlpha: 0.12 };
    default: return { glowColor: 0, glowAlpha: 0 };
  }
}

import { Container, Graphics } from "./pixi-compat";

/* ================================================================== */
/*  Types                                                               */
/* ================================================================== */

export type SeasonKey = "spring" | "summer" | "autumn" | "winter" | "none";

export interface SeasonalParticle {
  g: Graphics;
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  alpha: number;
  rotation: number;
  rotSpeed: number;
  life: number;
  maxLife: number;
}

export interface SeasonalParticleState {
  container: Container;
  particles: SeasonalParticle[];
  season: SeasonKey;
  areaW: number;
  areaH: number;
}

/* ================================================================== */
/*  Season config                                                       */
/* ================================================================== */

const MAX_PARTICLES = 60;
const SPAWN_RATE = 0.3; // particles per tick

interface SeasonConfig {
  colors: number[];
  sizeRange: [number, number];
  speedRange: [number, number]; // vy
  driftRange: [number, number]; // vx
  rotRange: [number, number];
  lifeRange: [number, number];
  shape: "circle" | "leaf" | "diamond" | "flake";
}

const SEASON_CONFIGS: Record<Exclude<SeasonKey, "none">, SeasonConfig> = {
  spring: {
    colors: [0xffb7c5, 0xffc0cb, 0xffe0e8, 0xffd4dd, 0xffffff],
    sizeRange: [2, 4],
    speedRange: [0.3, 0.8],
    driftRange: [-0.3, 0.3],
    rotRange: [-0.03, 0.03],
    lifeRange: [200, 400],
    shape: "leaf",
  },
  summer: {
    colors: [0xfff8b0, 0xffe580, 0xffffff, 0xb0e0ff],
    sizeRange: [1, 2.5],
    speedRange: [0.05, 0.2],
    driftRange: [-0.1, 0.1],
    rotRange: [-0.01, 0.01],
    lifeRange: [300, 500],
    shape: "diamond",
  },
  autumn: {
    colors: [0xd4622b, 0xc94d18, 0xe8a040, 0xbb4400, 0xd08830],
    sizeRange: [2.5, 5],
    speedRange: [0.4, 1.0],
    driftRange: [-0.5, 0.5],
    rotRange: [-0.05, 0.05],
    lifeRange: [180, 350],
    shape: "leaf",
  },
  winter: {
    colors: [0xffffff, 0xe8f0ff, 0xd8e8ff, 0xf0f8ff],
    sizeRange: [1.5, 3.5],
    speedRange: [0.2, 0.6],
    driftRange: [-0.2, 0.2],
    rotRange: [-0.02, 0.02],
    lifeRange: [250, 450],
    shape: "flake",
  },
};

/* ================================================================== */
/*  Helpers                                                             */
/* ================================================================== */

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

function pick<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function drawShape(g: Graphics, shape: SeasonConfig["shape"], size: number, color: number) {
  switch (shape) {
    case "circle":
      g.circle(0, 0, size).fill({ color, alpha: 0.8 });
      break;
    case "leaf": {
      // petal / leaf shape
      g.ellipse(0, 0, size * 0.6, size).fill({ color, alpha: 0.75 });
      g.ellipse(size * 0.3, 0, size * 0.4, size * 0.7).fill({ color, alpha: 0.5 });
      break;
    }
    case "diamond": {
      // sparkle / light mote
      g.star(0, 0, 4, size, size * 0.4).fill({ color, alpha: 0.6 });
      break;
    }
    case "flake": {
      // snowflake ??small cross + diagonals
      const s = size;
      g.circle(0, 0, s * 0.4).fill({ color, alpha: 0.9 });
      g.rect(-s, -0.5, s * 2, 1).fill({ color, alpha: 0.7 });
      g.rect(-0.5, -s, 1, s * 2).fill({ color, alpha: 0.7 });
      break;
    }
  }
}

/* ================================================================== */
/*  Public API                                                          */
/* ================================================================== */

export function createSeasonalParticleState(parent: Container, season: SeasonKey, areaW: number, areaH: number): SeasonalParticleState {
  const container = new Container();
  parent.addChild(container);
  return { container, particles: [], season, areaW, areaH };
}

export function updateSeasonalParticles(state: SeasonalParticleState, tick: number): void {
  if (state.season === "none") return;
  const config = SEASON_CONFIGS[state.season];
  if (!config) return;

  // Spawn
  if (state.particles.length < MAX_PARTICLES && Math.random() < SPAWN_RATE) {
    const color = pick(config.colors);
    const size = rand(...config.sizeRange);
    const g = new Graphics();
    drawShape(g, config.shape, size, color);

    const p: SeasonalParticle = {
      g,
      x: rand(-20, state.areaW + 20),
      y: rand(-30, -5),
      vx: rand(...config.driftRange),
      vy: rand(...config.speedRange),
      size,
      alpha: 1,
      rotation: rand(0, Math.PI * 2),
      rotSpeed: rand(...config.rotRange),
      life: 0,
      maxLife: rand(...config.lifeRange),
    };
    g.position.set(p.x, p.y);
    g.rotation = p.rotation;
    state.container.addChild(g);
    state.particles.push(p);
  }

  // Update
  for (let i = state.particles.length - 1; i >= 0; i--) {
    const p = state.particles[i];
    p.life++;
    p.x += p.vx + Math.sin(tick * 0.02 + p.rotation) * 0.15;
    p.y += p.vy;
    p.rotation += p.rotSpeed;

    // Fade out in last 20% of life
    const lifeRatio = p.life / p.maxLife;
    p.alpha = lifeRatio > 0.8 ? 1 - (lifeRatio - 0.8) / 0.2 : Math.min(1, p.life / 20);

    p.g.position.set(p.x, p.y);
    p.g.rotation = p.rotation;
    p.g.alpha = p.alpha;

    // Remove dead or out of bounds
    if (p.life >= p.maxLife || p.y > state.areaH + 10) {
      state.container.removeChild(p.g);
      p.g.destroy();
      state.particles.splice(i, 1);
    }
  }
}

export function destroySeasonalParticles(state: SeasonalParticleState): void {
  for (const p of state.particles) {
    if (!p.g.destroyed) p.g.destroy();
  }
  state.particles.length = 0;
  if (!state.container.destroyed) state.container.destroy({ children: true });
}

/** Auto-detect season from current date */
export function detectSeason(): SeasonKey {
  const month = new Date().getMonth(); // 0-11
  if (month >= 2 && month <= 4) return "spring";
  if (month >= 5 && month <= 7) return "summer";
  if (month >= 8 && month <= 10) return "autumn";
  return "winter";
}

/** Load season preference from localStorage */
export function loadSeasonPreference(): SeasonKey | "auto" {
  try {
    const val = localStorage.getItem("agentdesk_seasonal_decor");
    if (val === "auto" || val === "spring" || val === "summer" || val === "autumn" || val === "winter" || val === "none") return val;
  } catch {}
  return "auto";
}

/** Save season preference to localStorage and notify listeners */
export function saveSeasonPreference(value: SeasonKey | "auto"): void {
  try {
    localStorage.setItem("agentdesk_seasonal_decor", value);
  } catch {}
  window.dispatchEvent(new CustomEvent("agentdesk_season_change", { detail: value }));
}

/** Resolve actual season from preference */
export function resolveSeasonKey(pref: SeasonKey | "auto"): SeasonKey {
  return pref === "auto" ? detectSeason() : pref;
}

import { useEffect, type MutableRefObject } from "react";
import { Application, Assets, TextureStyle, type Texture } from "./pixi-compat";
import type { Agent, Department, SubAgent, Task } from "../../types";
import { buildSpriteMap } from "../AgentAvatar";
import { type Delivery, MIN_OFFICE_W } from "./model";
import { runOfficeTickerStep, type OfficeTickerContext } from "./officeTicker";

interface UseOfficePixiRuntimeParams {
  containerRef: MutableRefObject<HTMLDivElement | null>;
  appRef: MutableRefObject<Application | null>;
  texturesRef: MutableRefObject<Record<string, Texture>>;
  destroyedRef: MutableRefObject<boolean>;
  initIdRef: MutableRefObject<number>;
  initDoneRef: MutableRefObject<boolean>;
  officeWRef: MutableRefObject<number>;
  deliveriesRef: MutableRefObject<Delivery[]>;
  dataRef: MutableRefObject<{ agents: Agent[] }>;
  buildScene: () => void;
  followCeoInView: () => void;
  triggerDepartmentInteract: () => void;
  keysRef: MutableRefObject<Record<string, boolean>>;
  tickerContext: OfficeTickerContext;
  departments: Department[];
  agents: Agent[];
  tasks: Task[];
  subAgents: SubAgent[];
  unreadAgentIds?: Set<string>;
  language: string;
  activeMeetingTaskId?: string | null;
  customDeptThemes?: Record<string, { floor1: number; floor2: number; wall: number; accent: number }>;
  currentTheme: string;
}

export function useOfficePixiRuntime({
  containerRef,
  appRef,
  texturesRef,
  destroyedRef,
  initIdRef,
  initDoneRef,
  officeWRef,
  deliveriesRef,
  dataRef,
  buildScene,
  followCeoInView,
  triggerDepartmentInteract,
  keysRef,
  tickerContext,
  departments,
  agents,
  tasks,
  subAgents,
  unreadAgentIds,
  language,
  activeMeetingTaskId,
  customDeptThemes,
  currentTheme,
}: UseOfficePixiRuntimeParams): void {
  useEffect(() => {
    const element = containerRef.current;
    if (!element) return;

    destroyedRef.current = false;
    const currentInitId = ++initIdRef.current;

    async function init() {
      if (!element) return;
      TextureStyle.defaultOptions.scaleMode = "nearest";

      // Viewport = container dimensions (flexbox gives definite height)
      const viewportW = Math.max(MIN_OFFICE_W, element.clientWidth);
      const viewportH = Math.max(300, element.clientHeight || 600);
      officeWRef.current = viewportW;

      const app = new Application();
      await app.init({
        width: viewportW,
        height: viewportH,
        backgroundAlpha: 1,
        antialias: false,
        resolution: 2,
        autoDensity: true,
        parent: element,
      });

      // Apply DPR scaling (viewport-sized canvas at 2x physical pixels)
      app.resizeViewport(viewportW, viewportH);

      if (initIdRef.current !== currentInitId) {
        try {
          app.destroy();
        } catch {}
        return;
      }

      appRef.current = app;
      const canvas = app.canvas as HTMLCanvasElement;
      canvas.style.imageRendering = "pixelated";
      canvas.style.background = "#080c14";
      element.innerHTML = "";
      element.appendChild(canvas);

      const spriteMap = buildSpriteMap(dataRef.current.agents);
      const textures: Record<string, Texture> = {};
      const loads: Promise<void>[] = [];
      const spriteNums = new Set<number>();

      for (let i = 1; i <= 13; i++) spriteNums.add(i);
      for (const num of spriteMap.values()) spriteNums.add(num);

      for (const spriteNum of spriteNums) {
        for (const frame of [1, 2, 3]) {
          const key = `${spriteNum}-D-${frame}`;
          loads.push(
            Assets.load<Texture>(`/sprites/${key}.png`)
              .then((texture) => {
                textures[key] = texture;
              })
              .catch(() => {}),
          );
        }

        for (const direction of ["L", "R"]) {
          const key = `${spriteNum}-${direction}-1`;
          loads.push(
            Assets.load<Texture>(`/sprites/${key}.png`)
              .then((texture) => {
                textures[key] = texture;
              })
              .catch(() => {}),
          );
        }
      }

      loads.push(
        Assets.load<Texture>("/sprites/ceo-lobster.png")
          .then((texture) => {
            textures.ceo = texture;
          })
          .catch(() => {}),
      );

      await Promise.all(loads);

      if (initIdRef.current !== currentInitId) {
        try {
          app.destroy();
        } catch {}
        return;
      }

      texturesRef.current = textures;
      buildScene();
      initDoneRef.current = true;
      followCeoInView();

      app.ticker.add(() => {
        if (destroyedRef.current || appRef.current !== app) return;
        runOfficeTickerStep(tickerContext);
      });
    }

    const isInputFocused = () => {
      const tag = document.activeElement?.tagName;
      return (
        tag === "INPUT" ||
        tag === "TEXTAREA" ||
        tag === "SELECT" ||
        (document.activeElement as HTMLElement)?.isContentEditable
      );
    };

    const onKeyDown = (event: KeyboardEvent) => {
      if (isInputFocused()) return;
      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "KeyW", "KeyA", "KeyS", "KeyD"].includes(event.code)) {
        event.preventDefault();
        keysRef.current[event.code] = true;
      }
      if (event.code === "Enter" || event.code === "Space") {
        event.preventDefault();
        triggerDepartmentInteract();
      }
    };

    const onKeyUp = (event: KeyboardEvent) => {
      if (isInputFocused()) return;
      keysRef.current[event.code] = false;
    };

    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("keyup", onKeyUp);

    init();

    const resizeObserver = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry || !appRef.current || destroyedRef.current || initIdRef.current !== currentInitId) return;
      const newWidth = Math.max(MIN_OFFICE_W, Math.floor(entry.contentRect.width));
      const newHeight = Math.max(300, Math.floor(entry.contentRect.height));
      const widthChanged = Math.abs(newWidth - officeWRef.current) > 10;
      const heightChanged = Math.abs(newHeight - (appRef.current.getCameraViewportSize().h * appRef.current.getCameraZoom())) > 10;
      if (widthChanged || heightChanged) {
        officeWRef.current = newWidth;
        // Resize viewport canvas to match container
        appRef.current.resizeViewport(newWidth, newHeight);
        buildScene();
      }
    });

    resizeObserver.observe(element);

    return () => {
      destroyedRef.current = true;
      initIdRef.current++;
      resizeObserver.disconnect();
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("keyup", onKeyUp);
      deliveriesRef.current = [];
      initDoneRef.current = false;

      if (appRef.current) {
        appRef.current.destroy(true, { children: true });
        appRef.current = null;
      }
    };
  }, [
    containerRef,
    appRef,
    texturesRef,
    destroyedRef,
    initIdRef,
    initDoneRef,
    officeWRef,
    deliveriesRef,
    dataRef,
    buildScene,
    followCeoInView,
    triggerDepartmentInteract,
    keysRef,
    tickerContext,
  ]);

  useEffect(() => {
    if (initDoneRef.current && appRef.current) {
      buildScene();
    }
  }, [
    departments,
    agents,
    tasks,
    subAgents,
    unreadAgentIds,
    language,
    activeMeetingTaskId,
    customDeptThemes,
    currentTheme,
    buildScene,
    initDoneRef,
    appRef,
  ]);
}

