import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  getAvailableLearnedSkills,
  getSkillDetail,
  getSkillLearningJob,
  getSkills,
  startSkillLearning,
  unlearnSkill,
  type LearnedSkillEntry,
  type SkillDetail,
  type SkillHistoryProvider,
  type SkillLearnJob,
  type SkillLearnProvider,
} from "../../api";
import type { Agent } from "../../types";
import {
  categorize,
  formatInstalls,
  LEARN_PROVIDER_ORDER,
  LEARNED_PROVIDER_ORDER,
  pickRepresentativeForProvider,
  type CategorizedSkill,
  type TFunction,
  type UnlearnEffect,
} from "./model";
import { useCustomSkillsState } from "./useCustomSkillsState";

export function useSkillsLibraryState({ agents, localeTag, t }: { agents: Agent[]; localeTag: string; t: TFunction }) {
  const [skills, setSkills] = useState<Awaited<ReturnType<typeof getSkills>>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [sortBy, setSortBy] = useState<"rank" | "name" | "installs">("rank");
  const [copiedSkill, setCopiedSkill] = useState<string | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<string | null>(null);
  const [detailCache, setDetailCache] = useState<Record<string, SkillDetail | "loading" | "error">>({});
  const hoverTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const tooltipRef = useRef<HTMLDivElement | null>(null);

  const [learningSkill, setLearningSkill] = useState<CategorizedSkill | null>(null);
  const [selectedProviders, setSelectedProviders] = useState<SkillLearnProvider[]>([]);
  const [learnJob, setLearnJob] = useState<SkillLearnJob | null>(null);
  const [learnSubmitting, setLearnSubmitting] = useState(false);
  const [learnError, setLearnError] = useState<string | null>(null);
  const [unlearnError, setUnlearnError] = useState<string | null>(null);
  const [unlearningProviders, setUnlearningProviders] = useState<SkillLearnProvider[]>([]);
  const [unlearnEffects, setUnlearnEffects] = useState<Partial<Record<SkillLearnProvider, UnlearnEffect>>>({});
  const [historyRefreshToken, setHistoryRefreshToken] = useState(0);
  const [learnedRows, setLearnedRows] = useState<LearnedSkillEntry[]>([]);
  const [squadAgentIds, setSquadAgentIds] = useState<string[]>([]);
  const unlearnEffectTimersRef = useRef<Partial<Record<SkillLearnProvider, number>>>({});

  const representatives = useMemo(
    () =>
      LEARN_PROVIDER_ORDER.map((provider) => ({
        provider,
        agent: pickRepresentativeForProvider(agents, provider),
      })),
    [agents],
  );

  const defaultSelectedProviders = useMemo(
    () => representatives.filter((row) => row.agent).map((row) => row.provider),
    [representatives],
  );

  const bumpHistoryRefreshToken = useCallback(() => {
    setHistoryRefreshToken((prev) => prev + 1);
  }, []);

  const customState = useCustomSkillsState({
    defaultSelectedProviders,
    t,
    onHistoryChanged: bumpHistoryRefreshToken,
  });

  const learnedRepresentatives = useMemo(() => {
    const out = new Map<SkillHistoryProvider, Agent | null>();
    for (const provider of LEARNED_PROVIDER_ORDER) {
      out.set(provider, pickRepresentativeForProvider(agents, provider));
    }
    return out;
  }, [agents]);

  const handleCardMouseEnter = useCallback(
    (skill: CategorizedSkill) => {
      if (hoverTimerRef.current) clearTimeout(hoverTimerRef.current);
      hoverTimerRef.current = setTimeout(() => {
        const detailId = skill.skillId || skill.name;
        const key = `${skill.repo}/${detailId}`;
        setHoveredSkill(key);
        if (!detailCache[key]) {
          setDetailCache((prev) => ({ ...prev, [key]: "loading" }));
          getSkillDetail(skill.repo, detailId)
            .then((detail) => {
              setDetailCache((prev) => ({ ...prev, [key]: detail ?? "error" }));
            })
            .catch(() => {
              setDetailCache((prev) => ({ ...prev, [key]: "error" }));
            });
        }
      }, 300);
    },
    [detailCache],
  );

  const handleCardMouseLeave = useCallback(() => {
    if (hoverTimerRef.current) clearTimeout(hoverTimerRef.current);
    setHoveredSkill(null);
  }, []);

  const loadSkills = useCallback(() => {
    setLoading(true);
    setError(null);
    getSkills()
      .then(setSkills)
      .catch((error) => setError(error.message))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    loadSkills();
  }, [loadSkills]);

  useEffect(() => {
    let cancelled = false;
    getAvailableLearnedSkills({ limit: 500 })
      .then((rows) => {
        if (!cancelled) setLearnedRows(rows);
      })
      .catch(() => {
        if (!cancelled) setLearnedRows([]);
      });
    return () => {
      cancelled = true;
    };
  }, [historyRefreshToken]);

  const categorizedSkills = useMemo<CategorizedSkill[]>(
    () =>
      skills.map((skill) => ({
        ...skill,
        category: categorize(skill.name, skill.repo),
        installsDisplay: formatInstalls(skill.installs, localeTag),
      })),
    [skills, localeTag],
  );

  const filtered = useMemo(() => {
    let result = categorizedSkills;

    if (selectedCategory !== "All") {
      result = result.filter((skill) => skill.category === selectedCategory);
    }

    if (search.trim()) {
      const q = search.toLowerCase();
      result = result.filter(
        (skill) =>
          skill.name.toLowerCase().includes(q) ||
          skill.repo.toLowerCase().includes(q) ||
          skill.category.toLowerCase().includes(q),
      );
    }

    if (sortBy === "name") {
      result = [...result].sort((a, b) => a.name.localeCompare(b.name, localeTag));
    } else if (sortBy === "installs") {
      result = [...result].sort((a, b) => b.installs - a.installs);
    }

    return result;
  }, [categorizedSkills, localeTag, search, selectedCategory, sortBy]);

  const categoryCounts = useMemo(() => {
    const counts: Record<string, number> = { All: categorizedSkills.length };
    for (const skill of categorizedSkills) {
      counts[skill.category] = (counts[skill.category] || 0) + 1;
    }
    return counts;
  }, [categorizedSkills]);

  const learnedProvidersBySkill = useMemo(() => {
    const map = new Map<string, SkillHistoryProvider[]>();
    for (const row of learnedRows) {
      const key = `${row.repo}/${row.skill_id}`;
      if (!map.has(key)) {
        map.set(key, []);
      }
      const providers = map.get(key)!;
      if (!providers.includes(row.provider)) {
        providers.push(row.provider);
      }
    }
    for (const providers of map.values()) {
      providers.sort((a, b) => LEARNED_PROVIDER_ORDER.indexOf(a) - LEARNED_PROVIDER_ORDER.indexOf(b));
    }
    return map;
  }, [learnedRows]);

  const learningSkillDetailId = learningSkill ? learningSkill.skillId || learningSkill.name : "";
  const learningSkillKey = learningSkill ? `${learningSkill.repo}/${learningSkillDetailId}` : "";
  const modalLearnedProviders = useMemo(() => {
    if (!learningSkillKey) return new Set<SkillHistoryProvider>();
    return new Set(learnedProvidersBySkill.get(learningSkillKey) ?? []);
  }, [learnedProvidersBySkill, learningSkillKey]);

  const learnInProgress = learnJob?.status === "queued" || learnJob?.status === "running";
  const learnInProgressRef = useRef(learnInProgress);
  learnInProgressRef.current = learnInProgress;
  const preferKoreanName = localeTag.startsWith("ko");

  useEffect(() => {
    return () => {
      for (const timerId of Object.values(unlearnEffectTimersRef.current)) {
        if (typeof timerId === "number") {
          window.clearTimeout(timerId);
        }
      }
    };
  }, []);

  useEffect(() => {
    if (!learnJob || (learnJob.status !== "queued" && learnJob.status !== "running")) {
      return;
    }
    let cancelled = false;
    const timer = window.setInterval(() => {
      getSkillLearningJob(learnJob.id)
        .then((job) => {
          if (!cancelled) {
            setLearnJob(job);
          }
        })
        .catch((error: Error) => {
          if (!cancelled) {
            setLearnError(error.message);
          }
        });
    }, 1500);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [learnJob]);

  useEffect(() => {
    if (!learnJob) return;
    if (learnJob.status === "succeeded" || learnJob.status === "failed") {
      setHistoryRefreshToken((prev) => prev + 1);
    }
  }, [learnJob?.id, learnJob?.status]);

  const openLearningModal = useCallback(
    (skill: CategorizedSkill) => {
      const detailId = skill.skillId || skill.name;
      const key = `${skill.repo}/${detailId}`;
      const learnedProviders = new Set(learnedProvidersBySkill.get(key) ?? []);
      const initialSelection = defaultSelectedProviders.filter((provider) => !learnedProviders.has(provider));
      setLearningSkill(skill);
      setSelectedProviders(initialSelection);
      setLearnJob(null);
      setLearnError(null);
      setUnlearnError(null);
      setUnlearningProviders([]);
      setUnlearnEffects({});
      setSquadAgentIds([]);
    },
    [defaultSelectedProviders, learnedProvidersBySkill],
  );

  const closeLearningModal = useCallback(() => {
    if (learnInProgressRef.current) return;
    setLearningSkill(null);
    setSelectedProviders([]);
    setLearnJob(null);
    setLearnError(null);
    setUnlearnError(null);
    setUnlearningProviders([]);
    setUnlearnEffects({});
    setSquadAgentIds([]);
  }, []);

  useEffect(() => {
    if (!learningSkill) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      closeLearningModal();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [closeLearningModal, learningSkill]);

  const toggleProvider = useCallback(
    (provider: SkillLearnProvider) => {
      if (learnInProgress) return;
      setSelectedProviders((prev) =>
        prev.includes(provider) ? prev.filter((item) => item !== provider) : [...prev, provider],
      );
    },
    [learnInProgress],
  );

  const handleStartLearning = useCallback(async () => {
    if (!learningSkill || selectedProviders.length === 0 || learnSubmitting || learnInProgress) return;
    setLearnSubmitting(true);
    setLearnError(null);
    try {
      const job = await startSkillLearning({
        repo: learningSkill.repo,
        skillId: learningSkill.skillId || learningSkill.name,
        providers: selectedProviders,
      });
      setLearnJob(job);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      setLearnError(message);
    } finally {
      setLearnSubmitting(false);
    }
  }, [learnInProgress, learningSkill, learnSubmitting, selectedProviders]);

  const triggerUnlearnEffect = useCallback((provider: SkillLearnProvider) => {
    const effect: UnlearnEffect = Math.random() < 0.5 ? "pot" : "hammer";
    setUnlearnEffects((prev) => ({ ...prev, [provider]: effect }));
    const currentTimer = unlearnEffectTimersRef.current[provider];
    if (typeof currentTimer === "number") {
      window.clearTimeout(currentTimer);
    }
    unlearnEffectTimersRef.current[provider] = window.setTimeout(() => {
      setUnlearnEffects((prev) => {
        const next = { ...prev };
        delete next[provider];
        return next;
      });
      delete unlearnEffectTimersRef.current[provider];
    }, 1100);
  }, []);

  const handleUnlearnProvider = useCallback(
    async (provider: SkillLearnProvider) => {
      if (!learningSkill || learnInProgress || unlearningProviders.includes(provider)) return;
      const skillId = learningSkill.skillId || learningSkill.name;
      setUnlearnError(null);
      setUnlearningProviders((prev) => [...prev, provider]);
      try {
        const result = await unlearnSkill({ provider, repo: learningSkill.repo, skillId });
        if (result.removed > 0) {
          setLearnedRows((prev) =>
            prev.filter(
              (row) => !(row.provider === provider && row.repo === learningSkill.repo && row.skill_id === skillId),
            ),
          );
          triggerUnlearnEffect(provider);
        }
        setHistoryRefreshToken((prev) => prev + 1);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        setUnlearnError(message);
      } finally {
        setUnlearningProviders((prev) => prev.filter((item) => item !== provider));
      }
    },
    [learnInProgress, learningSkill, triggerUnlearnEffect, unlearningProviders],
  );

  const addAgentToSquad = useCallback(
    (agentId: string) => {
      setSquadAgentIds((prev) => (prev.includes(agentId) ? prev : [...prev, agentId]));
      const agent = agents.find((a) => a.id === agentId);
      if (agent?.cli_provider) {
        const provider = agent.cli_provider as SkillLearnProvider;
        setSelectedProviders((prev) => (prev.includes(provider) ? prev : [...prev, provider]));
      }
    },
    [agents],
  );

  const removeAgentFromSquad = useCallback((agentId: string) => {
    setSquadAgentIds((prev) => prev.filter((id) => id !== agentId));
  }, []);

  const handleCopy = useCallback((skill: CategorizedSkill) => {
    const cmd = `npx skills add ${skill.repo}`;
    navigator.clipboard.writeText(cmd).then(() => {
      setCopiedSkill(skill.name);
      setTimeout(() => setCopiedSkill(null), 2000);
    });
  }, []);

  return {
    skills,
    loading,
    error,
    search,
    setSearch,
    selectedCategory,
    setSelectedCategory,
    sortBy,
    setSortBy,
    copiedSkill,
    hoveredSkill,
    setHoveredSkill,
    detailCache,
    hoverTimerRef,
    tooltipRef,
    learningSkill,
    selectedProviders,
    learnJob,
    learnSubmitting,
    learnError,
    unlearnError,
    unlearningProviders,
    unlearnEffects,
    historyRefreshToken,
    setHistoryRefreshToken,
    showCustomModal: customState.showCustomModal,
    customSkillName: customState.customSkillName,
    setCustomSkillName: customState.setCustomSkillName,
    customSkillContent: customState.customSkillContent,
    customSkillFileName: customState.customSkillFileName,
    customSkillProviders: customState.customSkillProviders,
    customSkillSubmitting: customState.customSkillSubmitting,
    customSkillError: customState.customSkillError,
    customSkills: customState.customSkills,
    showClassroomAnimation: customState.showClassroomAnimation,
    classroomAnimSkillName: customState.classroomAnimSkillName,
    classroomAnimProviders: customState.classroomAnimProviders,
    customFileInputRef: customState.customFileInputRef,
    representatives,
    defaultSelectedProviders,
    learnedRepresentatives,
    categorizedSkills,
    filtered,
    categoryCounts,
    learnedProvidersBySkill,
    modalLearnedProviders,
    learnInProgress,
    preferKoreanName,
    openCustomSkillModal: customState.openCustomSkillModal,
    closeCustomSkillModal: customState.closeCustomSkillModal,
    handleCustomFileSelect: customState.handleCustomFileSelect,
    toggleCustomProvider: customState.toggleCustomProvider,
    handleCustomSkillSubmit: customState.handleCustomSkillSubmit,
    handleDeleteCustomSkill: customState.handleDeleteCustomSkill,
    refreshCustomSkills: customState.refreshCustomSkills,
    handleCardMouseEnter,
    handleCardMouseLeave,
    loadSkills,
    openLearningModal,
    closeLearningModal,
    toggleProvider,
    handleStartLearning,
    handleUnlearnProvider,
    handleCopy,
    squadAgentIds,
    addAgentToSquad,
    removeAgentFromSquad,
  };
}

import { useState, useMemo, useEffect } from "react";
import { useI18n } from "../../i18n";
import type { Task, Agent, Department } from "../../types";

interface Props {
  tasks: Task[];
  agents: Agent[];
  departments: Department[];
}

type ZoomLevel = "day" | "week" | "month";

const STATUS_COLORS: Record<string, string> = {
  done: "bg-emerald-500/80",
  in_progress: "bg-sky-500/80",
  review: "bg-amber-500/80",
  collaborating: "bg-violet-500/80",
  planned: "bg-[rgba(148,163,184,0.6)]",
  inbox: "bg-[rgba(100,116,139,0.4)]",
  pending: "bg-orange-400/60",
  cancelled: "bg-red-500/30",
};

const STATUS_LABELS: Record<string, { ko: string; en: string }> = {
  done: { ko: "?꾨즺", en: "Done" },
  in_progress: { ko: "吏꾪뻾以?

Pending" },
  cancelled: { ko: "痍⑥냼", en: "Cancelled" },
};

function daysBetween(a: number, b: number): number {
  return Math.ceil((b - a) / 86_400_000);
}

function formatDate(ts: number): string {
  const d = new Date(ts);
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

function formatDateFull(ts: number): string {
  return new Date(ts).toLocaleDateString();
}

export default function GanttChart({ tasks, agents, departments }: Props) {
  const { t, locale } = useI18n();
  const tr = (ko: string, en: string) => t({ ko, en, ja: en, zh: en });

  const [zoom, setZoom] = useState<ZoomLevel>("day");
  const [filterStatus, setFilterStatus] = useState<string>("all");
  const [filterDept, setFilterDept] = useState<string>("all");
  const [nowMs, setNowMs] = useState(Date.now());

  // Live "now" line ??updates every minute
  useEffect(() => {
    const id = setInterval(() => setNowMs(Date.now()), 60_000);
    return () => clearInterval(id);
  }, []);

  // Filter tasks that have meaningful time data
  const chartTasks = useMemo(() => {
    let filtered = tasks.filter(
      (t) => t.created_at && t.status !== "cancelled",
    );
    if (filterStatus !== "all") filtered = filtered.filter((t) => t.status === filterStatus);
    if (filterDept !== "all") filtered = filtered.filter((t) => t.department_id === filterDept);
    // Sort by start time
    return filtered.sort((a, b) => (a.started_at ?? a.created_at) - (b.started_at ?? b.created_at));
  }, [tasks, filterStatus, filterDept]);

  // Calculate time range
  const timeRange = useMemo(() => {
    if (chartTasks.length === 0) return { start: nowMs, end: nowMs + 86_400_000 * 7, days: 7 };
    const starts = chartTasks.map((t) => t.started_at ?? t.created_at);
    const ends = chartTasks.map((t) => t.completed_at ?? nowMs);
    const minStart = Math.min(...starts);
    const maxEnd = Math.max(...ends);
    // Add 1 day padding on each side
    const start = minStart - 86_400_000;
    const end = maxEnd + 86_400_000;
    return { start, end, days: Math.max(daysBetween(start, end), 1) };
  }, [chartTasks]);

  // Column width based on zoom
  const colWidth = zoom === "day" ? 40 : zoom === "week" ? 24 : 12;
  const totalWidth = timeRange.days * colWidth;

  // Generate time headers
  const headers = useMemo(() => {
    const result: { label: string; width: number; isWeekend?: boolean }[] = [];
    const cursor = new Date(timeRange.start);
    cursor.setHours(0, 0, 0, 0);

    for (let i = 0; i < timeRange.days; i++) {
      const d = new Date(cursor.getTime() + i * 86_400_000);
      const dow = d.getDay();
      if (zoom === "day") {
        result.push({
          label: `${d.getMonth() + 1}/${d.getDate()}`,
          width: colWidth,
          isWeekend: dow === 0 || dow === 6,
        });
      } else if (zoom === "week") {
        if (dow === 1 || i === 0) {
          result.push({ label: `${d.getMonth() + 1}/${d.getDate()}`, width: colWidth });
        }
      } else {
        if (d.getDate() === 1 || i === 0) {
          result.push({ label: `${d.getFullYear()}.${d.getMonth() + 1}`, width: colWidth });
        }
      }
    }
    return result;
  }, [timeRange, zoom, colWidth]);

  // Resolve agent name
  const agentMap = useMemo(() => {
    const m = new Map<string, Agent>();
    agents.forEach((a) => m.set(a.id, a));
    return m;
  }, [agents]);

  function getBarPosition(task: Task): { left: number; width: number } {
    const start = task.started_at ?? task.created_at;
    const end = task.completed_at ?? Date.now();
    const leftDays = daysBetween(timeRange.start, start);
    const durationDays = Math.max(daysBetween(start, end), 0.5);
    return {
      left: leftDays * colWidth,
      width: Math.max(durationDays * colWidth, 8),
    };
  }

  if (chartTasks.length === 0) {
    return (
      <div className="text-center py-16 font-mono" style={{ color: "var(--th-text-muted)" }}>
        <p>{tr("?쒖떆???쒖뒪?ш? ?놁뒿?덈떎", "No tasks to display")}</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Controls */}
      <div className="flex items-center gap-3 flex-wrap">
        <div className="flex items-center gap-1 p-0.5" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-elevated)" }}>
          {(["day", "week", "month"] as ZoomLevel[]).map((z) => (
            <button
              key={z}
              onClick={() => setZoom(z)}
              className="px-3 py-1 text-xs font-mono transition"
              style={zoom === z
                ? { borderRadius: "2px", background: "rgba(251,191,36,0.15)", border: "1px solid rgba(251,191,36,0.5)", color: "var(--th-accent)" }
                : { borderRadius: "2px", background: "transparent", border: "1px solid transparent", color: "var(--th-text-muted)" }}
            >
              {z === "day" ? tr("??

Month")}
            </button>
          ))}
        </div>

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="px-2 py-1 text-xs font-mono outline-none"
          style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-input-bg)", color: "var(--th-text-primary)" }}
        >
          <option value="all">{tr("?꾩껜 ?곹깭", "All Status")}</option>
          {Object.entries(STATUS_LABELS).map(([k, v]) => (
            <option key={k} value={k}>
              {locale === "ko" ? v.ko : v.en}
            </option>
          ))}
        </select>

        {departments.length > 0 && (
          <select
            value={filterDept}
            onChange={(e) => setFilterDept(e.target.value)}
            className="px-2 py-1 text-xs font-mono outline-none"
            style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-input-bg)", color: "var(--th-text-primary)" }}
          >
            <option value="all">{tr("?꾩껜 遺??

All Depts")}</option>
            {departments.map((d) => (
              <option key={d.id} value={d.id}>
                {d.icon} {locale === "ko" ? d.name_ko : d.name}
              </option>
            ))}
          </select>
        )}

        <span className="text-xs font-mono" style={{ color: "var(--th-text-muted)" }}>
          {chartTasks.length} {tr("嫄?

tasks")}
        </span>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-3 text-[10px]">
        {Object.entries(STATUS_LABELS).map(([k, v]) => (
          <span key={k} className="flex items-center gap-1">
            <span className={`w-3 h-2 rounded-sm ${STATUS_COLORS[k]}`} />
            {locale === "ko" ? v.ko : v.en}
          </span>
        ))}
      </div>

      {/* Chart */}
      <div className="overflow-hidden" style={{ borderRadius: "2px", border: "1px solid var(--th-border)", background: "var(--th-bg-primary)" }}>
        <div className="flex">
          {/* Left: Task names */}
          <div className="shrink-0 w-52" style={{ borderRight: "1px solid var(--th-border)", background: "var(--th-bg-elevated)" }}>
            {/* Header placeholder */}
            <div className="h-8 px-2 flex items-center" style={{ borderBottom: "1px solid var(--th-border)" }}>
              <span className="text-[10px] font-semibold font-mono" style={{ color: "var(--th-text-muted)" }}>
                {tr("?쒖뒪??

Task")}
              </span>
            </div>
            {/* Task labels */}
            {chartTasks.map((task) => {
              const agent = task.assigned_agent_id ? agentMap.get(task.assigned_agent_id) : null;
              return (
                <div
                  key={task.id}
                  className="h-7 px-2 flex items-center gap-1 hover:bg-[var(--th-bg-surface-hover)] transition"
                  style={{ borderBottom: "1px solid var(--th-border)" }}
                  title={task.title}
                >
                  {agent && <span className="text-xs">{agent.avatar_emoji}</span>}
                  <span className="text-[11px] font-mono truncate flex-1" style={{ color: "var(--th-text-secondary)" }}>
                    {task.title}
                  </span>
                </div>
              );
            })}
          </div>

          {/* Right: Timeline */}
          <div className="flex-1 overflow-x-auto">
            <div className="relative" style={{ minWidth: totalWidth }}>
              {/* Time header */}
              <div className="h-8 flex" style={{ borderBottom: "1px solid var(--th-border)" }}>
                {headers.map((h, i) => (
                  <div
                    key={i}
                    className="shrink-0 flex items-center justify-center text-[10px] font-mono"
                    style={{
                      width: h.width,
                      borderRight: "1px solid var(--th-border)",
                      background: h.isWeekend ? "var(--th-bg-elevated)" : "transparent",
                      color: h.isWeekend ? "var(--th-text-muted)" : "var(--th-text-secondary)",
                    }}
                  >
                    {h.label}
                  </div>
                ))}
              </div>

              {/* Bars */}
              {chartTasks.map((task) => {
                const { left, width } = getBarPosition(task);
                const statusColor = STATUS_COLORS[task.status] ?? STATUS_COLORS.inbox;
                const startTs = task.started_at ?? task.created_at;
                const endTs = task.completed_at ?? nowMs;

                return (
                  <div
                    key={task.id}
                    className="h-7 relative"
                    style={{ borderBottom: "1px solid var(--th-border)" }}
                  >
                    {/* Bar */}
                    <div
                      className={`absolute top-1 h-5 ${statusColor} cursor-default transition-all hover:brightness-110`}
                      style={{ borderRadius: "2px", left, width }}
                      title={`${task.title}\n${formatDateFull(startTs)} ??${task.completed_at ? formatDateFull(endTs) : tr("吏꾪뻾以?

ongoing")}\n${locale === "ko" ? STATUS_LABELS[task.status]?.ko : STATUS_LABELS[task.status]?.en}`}
                    >
                      {width > 60 && (
                        <span className="absolute inset-0 flex items-center px-1.5 text-[9px] text-white/90 truncate font-medium">
                          {task.title}
                        </span>
                      )}
                    </div>
                  </div>
                );
              })}

              {/* NOW line ??single full-height amber line */}
              {(() => {
                const nowLeft = daysBetween(timeRange.start, nowMs) * colWidth;
                if (nowLeft < 0 || nowLeft > totalWidth) return null;
                return (
                  <div
                    className="absolute top-0 bottom-0 pointer-events-none"
                    style={{ left: nowLeft, width: 1, background: "rgba(251,191,36,0.6)", zIndex: 10 }}
                  >
                    <div
                      className="absolute text-[8px] font-mono font-bold whitespace-nowrap px-1 py-0.5"
                      style={{
                        top: 0,
                        left: "50%",
                        transform: "translateX(-50%)",
                        background: "var(--th-accent)",
                        color: "#000",
                        borderRadius: "0 0 2px 2px",
                        letterSpacing: 0.5,
                      }}
                    >
                      NOW
                    </div>
                  </div>
                );
              })()}
            </div>
          </div>
        </div>
      </div>

      {/* Summary */}
      <div className="flex gap-4 text-xs font-mono" style={{ color: "var(--th-text-muted)" }}>
        <span>
          {tr("湲곌컙", "Period")}: {formatDate(timeRange.start)} ??{formatDate(timeRange.end)} ({timeRange.days}{tr("??

d")})
        </span>
        <span className="flex items-center gap-1">
          <span className="w-px h-3" style={{ background: "rgba(251,191,36,0.7)" }} />
          {tr("?꾩옱 ?쒓컖", "Now")}
        </span>
      </div>
    </div>
  );
}

import { useEffect, useRef, useCallback, useState } from "react";

export function usePolling<T>(fetcher: () => Promise<T>, intervalMs: number = 3000, deps: unknown[] = []) {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const timerRef = useRef<ReturnType<typeof setInterval>>(undefined);

  const refresh = useCallback(async () => {
    try {
      const result = await fetcher();
      setData(result);
      setError(null);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }, deps);

  useEffect(() => {
    refresh();
    timerRef.current = setInterval(refresh, intervalMs);

    function handleVisibility() {
      clearInterval(timerRef.current);
      if (!document.hidden) {
        refresh();
        timerRef.current = setInterval(refresh, intervalMs);
      }
    }
    document.addEventListener("visibilitychange", handleVisibility);

    return () => {
      clearInterval(timerRef.current);
      document.removeEventListener("visibilitychange", handleVisibility);
    };
  }, [refresh, intervalMs]);

  return { data, loading, error, refresh };
}

import { useEffect, useRef, useCallback, useState } from "react";
import { bootstrapSession } from "../api";
import type { WSEvent, WSEventType } from "../types";

type Listener = (payload: unknown) => void;

export function useWebSocket() {
  const wsRef = useRef<WebSocket | null>(null);
  const listenersRef = useRef<Map<WSEventType, Set<Listener>>>(new Map());
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    const proto = location.protocol === "https:" ? "wss:" : "ws:";
    const url = `${proto}//${location.host}/ws`;
    let alive = true;
    let ws: WebSocket;
    let reconnectTimer: ReturnType<typeof setTimeout>;
    let forceSessionBootstrap = false;

    async function connect() {
      if (!alive) return;
      const forceBootstrap = forceSessionBootstrap;
      try {
        const bootstrapped = await bootstrapSession({
          promptOnUnauthorized: false,
          force: forceBootstrap,
        });
        if (!bootstrapped) {
          reconnectTimer = setTimeout(() => {
            void connect();
          }, 2000);
          return;
        }
        forceSessionBootstrap = false;
      } catch {
        // Avoid force bootstrap busy-loop when unauthorized recovery itself fails.
        if (forceBootstrap) forceSessionBootstrap = false;
        // ignore bootstrap errors; ws connect result will drive retry
        reconnectTimer = setTimeout(() => {
          void connect();
        }, 2000);
        return;
      }
      ws = new WebSocket(url);
      wsRef.current = ws;

      ws.onopen = () => {
        if (alive) setConnected(true);
      };
      ws.onclose = (event) => {
        if (!alive) return;
        setConnected(false);
        if (event.code === 1008) {
          forceSessionBootstrap = true;
        }
        reconnectTimer = setTimeout(() => {
          void connect();
        }, 2000);
      };
      ws.onerror = () => ws.close();
      ws.onmessage = (e) => {
        if (!alive) return;
        try {
          const evt: WSEvent = JSON.parse(e.data);
          const listeners = listenersRef.current.get(evt.type);
          if (listeners) {
            for (const fn of listeners) fn(evt.payload);
          }
        } catch {}
      };
    }

    void connect();
    return () => {
      alive = false;
      clearTimeout(reconnectTimer);
      ws?.close();
    };
  }, []);

  const on = useCallback((type: WSEventType, fn: Listener) => {
    if (!listenersRef.current.has(type)) {
      listenersRef.current.set(type, new Set());
    }
    listenersRef.current.get(type)!.add(fn);
    return () => {
      listenersRef.current.get(type)?.delete(fn);
    };
  }, []);

  return { connected, on };
}
